import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Пресвятій Богородиці перед іконою «Неупиваєма Чаша» (інший акафіст)","e":"Akathist to the Theotokos before her icon “The Inexhaustible Chalice” (another akathist)","secs":[{"h":"Кондак 1","ps":["Ізбра́нноє і ди́вноє ізбавле́ніє нам дарова́ся Твой о́браз честни́й, Влади́чице Богоро́дице, я́ко ізба́вльшеся явле́нієм єго́ от неду́гов душе́вних і тіле́сних і ско́рбних обстоя́ній, благода́рственная хвале́нія прино́сим Ті, Всеми́лостивая Засту́пнице. Ти же, Влади́чице, «Неупива́ємою Ча́шею» на́ми імену́ємая, приклони́ся благоутро́бно к на́шим воздиха́нієм і во́плем серде́чним і ізбавле́ніє пода́ждь стра́ждущим неду́гом пія́нства, да с ві́рою воззове́м Ті:","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Ікос 1","ps":["А́нгельстії чи́ни і пра́ведников со́нми непреста́нно сла́в'ять Тя, Цари́цю Богоро́дицю, Хода́таїцю о многогрі́шнім ро́де христия́нстім, погря́зшем в беззако́ніїх і пребива́ющем во грісі́х, і́бо во утіше́ніє і спасе́ніє да́руєши єму́ ми́лость Свою́ чрез многоіме́нния чудотво́рния іко́ни Твоя́, ї́хже, я́ко зві́зди небе́сния, по всей землі́ на́шей зрим; к єди́ному же із сих о́бразов, «Неупива́ємая Ча́ша» імену́ємому, припа́дающе, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, непреста́нноє люде́й удивле́ніє.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́льми на́ша не́мощі врачу́ющая.","Ра́дуйся, ми́лость Свою́ чрез чудотво́рния іко́ни Твоя́ нам сви́ше посила́ющая;","ра́дуйся, явле́нієм їх ско́рбная сердця́ на́ша возвеселя́ющая.","Ра́дуйся, пречу́дноє всіх с Бо́гом примире́ніє;","ра́дуйся, геє́нни ві́чния ізбавле́ніє.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи, Пресвята́я Влади́чице, ско́рби серде́чния, му́ки душе́вния, і́скреннєє покая́ніє люде́й, одержи́мих губи́тельним поро́ком пія́нства, благоволи́ла єси́ яви́ти богоспаса́ємому гра́ду Се́рпухову ми́лость Свою́ явле́нієм пречу́днаго о́браза Своєго́ «Неупива́ємая Ча́ша», да всі к нему́ припа́дающії с ві́рою і сокруше́нним се́рдцем, получи́вше ісціле́ніє от тя́жкаго неду́га своєго́, із глубини́ душі́ вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в трикра́тноє явле́ніє преподо́бнаго Варлаа́ма і повелі́ніє єго́ в путь ше́ствовати в богоспаса́ємий град Се́рпухов, челові́к ні́кий, стра́стію пія́нства одержи́мий, обрі́те та́мо в монастирі́ іко́ну Твою́ святу́ю, «Неупива́ємая Ча́ша» імену́ємую. Ми же, ви́дяще таково́є о нас, грі́шних, попече́ніє, с благогові́нієм вопіє́м Ті:","Ра́дуйся, чрез благочести́вих люде́й сла́ву чуде́с Твої́х грі́шним открива́ющая;","ра́дуйся, Путеводи́тельнице прозорли́вая, путь спасе́нія їм показу́ющая.","Ра́дуйся, всеблага́я на́ша Наста́внице, любо́вію Твоє́ю нас привлека́ющая;","ра́дуйся, за вся благодія́нія Твоя́ благодаре́нію нас науча́ющая.","Ра́дуйся, скорб на́шу в ра́дость претворя́ющая;","ра́дуйся, несомні́нною наде́ждою нас увеселя́ющая.","Ра́дуйся, губи́тельния стра́сті на́ша разруша́ющая;","ра́дуйся, благи́м намі́ренієм спосо́бствующая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго і благода́ть Влади́чиці укріпля́ше ні́коєго челові́ка, стра́ждущаго неду́гом пія́нства, єгда́ он, но́зі разсла́бленеї іму́ще, і́де во град Се́рпухов, повелі́ніє Богома́тере, чрез преподо́бнаго Варлаа́ма рече́нноє, ісполня́я. Прише́д же во град сей, обрі́те іко́ну Пречи́стия Богома́тере, а́біє ісцілі́ от неду́га своєго́ душе́внаго і тіле́снаго і із глубини́ душі́ благода́рственно воззва́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще істо́чник неоскудіва́ємий, неупива́ємую ча́шу небе́сних дарова́ній, не то́кмо лю́діє гра́да Се́рпухова, но і всі правосла́внії христия́ни іни́х градо́в і ве́сей, притека́ющії к Твоєму́ пречу́дному о́бразу, «Неупива́ємая Ча́ша» імену́ємому, і пред сим получи́вше ісціле́ніє, припа́дающе, благода́рними усти́ вопію́ть Ті:","Ра́дуйся, купе́ле, в не́йже вся ско́рбі на́ша погружа́ються;","ра́дуйся, ча́ше, є́юже ра́дость спасе́нія на́шего восприє́млем.","Ра́дуйся, на́ша не́мощі душе́вния і тіле́сния врачу́ющая;","ра́дуйся, стра́сті на́ша си́лою моли́тв Твої́х укроща́ющая.","Ра́дуйся, коєму́ждо, во вся́кой потре́бі прося́щим, поле́зная да́рующая;","ра́дуйся, бесчи́сленния щедро́ти всім подаю́щая.","Ра́дуйся, ми́лости сокро́вище нам открива́ющая;","ра́дуйся, милосе́рдіє к па́дшим явля́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 4","ps":["Бу́рю внутр іму́ще помишле́ній сумни́тельних, но с і́скренним покая́нієм притека́юще к Твоєму́ неізрече́нному милосе́рдію, одержи́мії пія́нственною стра́стію получа́ють ісціле́ніє і із глубини́ се́рдця вопію́ть рожде́нному от Тебе́ Спаси́телю на́шему: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь тя́жкия ско́рби, во́пли і плач жен, ста́риць, діте́й, сро́дниці ко́їх обурева́ємі суть пія́нственною стра́стію, дарова́ їм Твою́, Влади́чице, іко́ну, от нея́же всі притека́ющії обріта́ють утіше́ніє і ра́дость духо́вную і вопію́ть Ті со слеза́ми:","Ра́дуйся, А́гнице, ро́ждшая А́гнця, взе́млющаго гріхи́ ми́ра;","ра́дуйся, ча́ше, че́рплющая нам ра́дость от істо́чника безсме́ртія.","Ра́дуйся, ско́рбних ма́терей утіше́ніє;","ра́дуйся, безнаде́жних Наде́ждо.","Ра́дуйся, притека́ющих к Тебі́ благода́тноє охране́ніє;","ра́дуйся, скорб'я́щих отра́до і увеселе́ніє.","Ра́дуйся, волне́ніє стра́сті пія́нства утиша́ющая;","ра́дуйся, руку́ по́мощі Твоєя́ тре́бующим простира́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 5","ps":["Я́ко боготе́чную звізду́, честну́ю іко́ну Твою́ показа́ла єси́ нам, Влади́чице ми́ра, ю́же зря́ще і с ві́рою серде́чною моля́щеся Тебі́, Богоро́дице, глаго́лем: ісціли́ пія́нством і іно́ю болі́знію душе́вною і тіле́сною стра́ждущих, ві́рних же научи́ воспіва́ти хвалу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще чудеса́ пресла́вная і зна́менія пречу́дная, бива́ємая не то́кмо от іко́ни Твоєя́, Богома́ти, во гра́ді Се́рпухове явле́нния, но і от по подо́бію сея́ іко́ни спи́санних ізображе́ній, припа́дающе к ним, смире́нно вопіє́м Ті:","Ра́дуйся, скоропредста́тельная Помо́щнице усе́рдно к Тебі́ притека́ющих;","ра́дуйся, благосе́рдная Усли́шательнице моле́ній на́ших.","Ра́дуйся, град Се́рпухов благослове́нієм Твої́м осіни́вшая;","ра́дуйся, в преді́ліх Моско́вських сла́ву чуде́с Твої́х показа́вшая.","Ра́дуйся, всім тре́бующим сокро́вище ісціле́ній неоску́дноє;","ра́дуйся, в трезве́нії благоподвиза́ющихся всемо́щная Покрови́тельнице.","Ра́дуйся, веду́щим брань проти́ву ми́ра, пло́ті, дия́вола і пія́нства до́брая Споспі́шнице;","ра́дуйся, в ми́рі благоче́стно живу́щих усе́рдная Засту́пнице.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дающе чудеса́ Твоя́, Богороди́тельнице, от іко́ни Твоєя́ «Неупива́ємая Ча́ша» імену́ємия, бива́ємая, мо́лим Тя, Пречи́стая, со слеза́ми: ізба́ви всіх нас от ви́ннаго пристра́стія і от паде́нія гріхо́внаго, научи́ нас воздержа́нію, подвиза́ющи воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ в сві́тлости Боже́ственния сла́ви, Ді́во Богоотрокови́це, на Младе́нця, Преві́чнаго Бо́га, Го́спода на́шего Ісу́са Христа́, зря́щи. І́же в сосу́ді, а́ки в неупива́ємой ча́ше, предстої́ть, я́коже Тя ви́дим ізображе́нную на іко́ні Твоє́й, «Неупива́ємая Ча́ша» та́їнственно пронарече́нней, от нея́же ізбавле́ніє от пія́нственния стра́сті притека́ющим с ві́рою да́руєши, сего́ ра́ди со слеза́ми прино́сим Тебі́ гла́си немо́лчния си́це:","Ра́дуйся, я́ко о Тебі́ ра́дується і торжеству́єть а́нгельський собо́р і челові́чеський род;","ра́дуйся, я́ко Твоя́ сла́ва превосхо́дить похвали́ земни́я і небе́сния.","Ра́дуйся, та́їнственним ізображе́нієм Си́на в сосу́ді Та́йну Боже́ственния Євхари́стії нам открива́ющая;","ра́дуйся, рожде́ннаго Тобо́ю А́гнця, всегда́ ядо́маго і нікогда́же іждива́ємаго, нам ди́вно указу́ющая.","Ра́дуйся, ча́ше жи́зні і безсме́ртія, ко врата́м ві́чния жи́зні нас приводя́щая;","ра́дуйся, істо́чником нетлі́нія і ра́дости жа́ждущия ду́ші напоя́ющая.","Ра́дуйся, несче́тною бла́гостію не оставля́ющая са́мих презрі́нних і отве́рженних;","ра́дуйся, от ро́ва поги́белі милосе́рдієм Твої́м ісхища́ющая безнаде́жних.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 7","ps":["Хотя́ челові́к ні́кий возблагодари́ти Тя, Влади́чице, за ісціле́ніє от неду́га пія́нства, украси́ Твою́ пречу́дную іко́ну, Богома́ти, во гра́ді Се́рпухове пребива́ющую, із глубини́ се́рдця воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до ви́дим, Влади́чице, от іко́ни Твоєя́ святи́я: стра́ждущий бо неду́гом пія́нства ні́кий раб Бо́жий Стефа́н, прибіга́я к Твоєму́ Ма́тернему предста́тельству, от тя́жкаго неду́га своєго́ ізба́вися, і, благодаря́ще Тя, благолі́пними да́ри іко́ну Твою́ украси́, і припа́дающи к ней, со слеза́ми возопи́ Тебі́ та́ко:","Ра́дуйся, Живоно́сний Істо́чниче ісціле́ній;","ра́дуйся, ча́ше небе́сная Боже́ственних дарова́ній.","Ра́дуйся, ріко́ ісціле́ній приснотеку́щая;","ра́дуйся, мо́ре, вся на́ша стра́сті потопля́ющеє.","Ра́дуйся, под тя́жестію гріха́ пія́нства па́дающих Ма́тернима рука́ма Твої́ма возставля́ющая;","ра́дуйся, благода́рственния да́ри не отверга́ющая.","Ра́дуйся, сердца́ благочести́вих люде́й возвеселя́ющая;","ра́дуйся, вся блага́я проше́нія на́ша ісполня́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 8","ps":["Стра́нно і сумни́тельно неве́рующим сли́шати, ка́ко іко́на Твоя́ свята́я «Неупива́ємая Ча́ша» Боже́ственних ісціле́ній істоча́єть чу́до. Ми же, ві́рующе сло́ву Твоєму́, Влади́чице, рече́нному к первопи́санній Твоє́й іко́ні: «Благода́ть Ро́ждшагося от Мене́ і Моя́ с се́ю іко́ною да бу́деть», — ві́руєм, я́ко і сія́ іко́на Твоя́ благода́ть Твою́ істоча́єть. Ті́мже, благогові́йно поклоня́ющеся, лобиза́єм ю, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все упова́ніє лю́діє, стра́ждущії неду́гом пія́нства, на Тя, Влади́чице, возлага́ють. Приклони́ся к не́мощем і страсте́м на́шим. Кто бо нас, грі́шних, ізведе́ть от ро́ва поги́белі і нищети́ духо́вния і тіле́сния, а́ще не Ти, Влади́чице! Сего́ ра́ди, прикло́нше колі́на пред Твої́м пречи́стим о́бразом, вопіє́м Ті та́ко:","Ра́дуйся, моле́нія грі́шников не отверга́ющая;","ра́дуйся, призива́ющим Тя Свою́ небе́сную по́мощ ниспосила́ющая.","Ра́дуйся, глубину́ милосе́рдія Твоєго́ грі́шним показу́ющая;","ра́дуйся, отча́янних і безнаде́жних ободря́ющая.","Ра́дуйся, одержи́мим стра́стію пія́нства руку́ по́мощі простира́ющая;","ра́дуйся, терпіли́вих страда́льцев благода́тними да́ри утіша́ющая.","Ра́дуйся, неду́ги на́ша душе́вния і тіле́сния врачу́ющая;","ра́дуйся, су́єтния ра́дости ми́ра сего́ презира́ти нас науча́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся ді́лу Твоєго́ милосе́рдія, Го́споди, я́ко дарова́л єси́ гре́шнему ро́ду челові́чеському тве́рдую Засту́пницю і Помо́щницю, к на́шим не́мощем приклоня́ющуюся і от го́ркаго неду́га пія́нства свобожда́ющую, ві́рния же науча́ющую пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я челові́честії недоумі́ють восхвали́ти по достоя́нію сла́вноє, Влади́чице, іко́ни Твоєя́ явле́ніє, ніже́ ми, грі́шнії, от скве́рних усте́н на́ших возмо́жем принести́ досто́йноє похвале́ніє Засту́пниці на́шей. Оба́че неісче́тная чудеса́, іко́ною Твоє́ю явля́ємая, ви́дівше, душе́ю і се́рдцем ра́дующеся, Тебі́ глаго́лем:","Ра́дуйся, от свяще́ннаго ли́ка Твоєго́ чудеса́ істоча́ющая;","ра́дуйся, от бід і скорбе́й ско́ро ізбавля́ющая.","Ра́дуйся, отверга́ющих Тя посрамля́ющая;","ра́дуйся, от вся́каго зла прибіга́ющих к Тебі́ сохраня́ющая.","Ра́дуйся, кро́тким сія́нієм Твої́м мрак гріхо́в і мглу страсте́й на́ших разгоня́ющая;","ра́дуйся, ду́ші на́ша любо́вію к Тебі́ і Си́ну Твоєму́ ісполня́ющая.","Ра́дуйся, на стезю́ покая́нія нас прему́дре наставля́ющая;","ра́дуйся, до́браго отві́та пред Судіє́ю Пра́ведним нам усе́рдная Хода́тайце.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи лю́ди мно́гія, стра́ждущия неду́гом пія́нства, чу́дную іко́ну Твою́, Богома́ти, дарова́ла єси́, да всі одержи́ми се́ю стра́стію к чудотво́рному о́бразу Твоєму́ притека́ють, і, получи́вше ісціле́ніє, во умиле́нії взива́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і щит, Богома́ти, лю́дем, стра́ждущим неду́гом пія́нства, і всім, усе́рдно к Тебі́ притека́ющим і іко́ну Твою́ святу́ю благогові́йно чту́щим, і́бо сію́ дарова́ нам благи́х пода́тель Госпо́дь в по́мощ і врачева́ніє от губи́тельния стра́сті, єя́ же ра́ди внуша́єть нам пі́ти Тебі́:","Ра́дуйся, отча́янних Наде́ждо і печа́лей на́ших утоле́ніє;","ра́дуйся, болі́зней душе́вних і тіле́сних ісціле́ніє.","Ра́дуйся, на́шу скве́рну чистото́ю Твоє́ю очища́ющая;","ра́дуйся, Своє́ю благода́тію на́ше недосто́їнство просвіща́ющая.","Ра́дуйся, бре́ніє на́ше тлі́нноє в нетлі́ніє облека́ющая;","ра́дуйся, моле́нія на́ша Твої́м предста́тельством подкрепля́ющая.","Ра́дуйся, в неможе́нії на́шем нас утвержда́ющая;","ра́дуйся, облега́ющий нас о́блак страсте́й ско́ро разгоня́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше смире́нноє, от полноти́ любві́ і усе́рдія Тебі́ приноси́моє, не пре́зри, Чи́стая, і не отврати́ от отча́явшихся і стра́ждущих неду́гом пія́нства ли́ка Своєго́, но помози́ їм же і нам очи́ститися от вся́кия скве́рни гріхо́вния, да возмо́жем досто́йно і пра́ведно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ зрим Тя, Пресвята́я Ді́во, і́бо о́браз Твой святи́й луча́ми благода́ті Твоєя́ мглу гріхо́вную прогоня́єть і на сві́тлую стезю́ доброді́телей наставля́єть с ві́рою зову́щих Ті такова́я:","Ра́дуйся, заступле́нієм Твої́м от суєти́ ми́ра сего́ многом'яте́жнаго нас ізбавля́ющая;","ра́дуйся, прираже́нія страсте́й плотськи́х отража́ти нам помога́ющая.","Ра́дуйся, мисль благу́ю в се́рдці на́ше полага́ющая;","ра́дуйся, нечи́стую со́вість на́шу просвіща́ющая.","Ра́дуйся, от мучи́тельнаго неду́га пія́нства стра́ждущих ізбавля́ющая;","ра́дуйся, к і́скреннему покая́нію і вразумле́нію призива́ющая.","Ра́дуйся, ду́ші всіх озло́бленних ум'ягча́ющая;","ра́дуйся, на по́мощ Тя призива́ющих і і́м'я Твоє́ сла́в'ящих спаса́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия, прису́щая іко́ні Твоє́й, «Неупива́ємая Ча́ша» імену́ємой, влече́ть к ней, Влади́чице, всіх скорб'я́щих, обездо́ленних, вдов і ста́риць, найпа́че же всіх стра́ждущих неду́гом пія́нства і не тще́тни отхо́дять, Пречи́стая, от неупива́ємия ча́ші Твої́х Боже́ственних дарова́ній, но, неоску́дно получа́юще цільби́ от чудотво́рнаго о́браза Твоєго́, Всебла́гая, благода́рственно пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́ і ве́лію ми́лость, лю́дем, одержи́мим стра́стію пія́нства, явле́нния, мо́лим Тя, Влади́чице, спаси́ і поми́луй, і наста́ви нас на стезю́ пра́ву, і не оста́ви нас, покро́ва Твоєго́ і́щущих і зову́щих Ті:","Ра́дуйся, воздержа́нію от гріха́ пія́нства всіх подвиза́ющая;","ра́дуйся, от пристра́стія к вину́ росо́ю ми́лости Твоєя́ свобожда́ющая.","Ра́дуйся, стра́ждущих от тя́жкаго гріха́ пія́нства при́сноє врачева́ніє;","ра́дуйся, бе́дствующим в страстеіх ско́рая Помо́щнице.","Ра́дуйся, малоду́шних ди́вноє ободре́ніє;","ра́дуйся, благоду́шних ве́лія ра́досте.","Ра́дуйся, го́рдих смиря́ющая;","ра́дуйся, смире́нния возвиша́ющая і всім спасе́нія жела́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 13","ps":["О Преми́лостивая Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́! Ни́нішнєє на́ше усли́ши моле́ніє і ізба́ви нас от всіх неду́гов душе́вних і тіле́сних, найпа́че же свободи́ стра́ждущих неду́гом пія́нства рабо́в Твої́х (імена́ їх), да не во злі поги́бнуть, но да спасе́ннії Тобо́ю, при́сно вопію́ть Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельстії чи́ни і пра́ведников со́нми непреста́нно сла́в'ять Тя, Цари́цю Богоро́дицю, Хода́таїцю о многогрі́шнім ро́де христия́нстім, погря́зшем в беззако́ніїх і пребива́ющем во грісі́х, і́бо во утіше́ніє і спасе́ніє да́руєши єму́ ми́лость Свою́ чрез многоіме́нния чудотво́рния іко́ни Твоя́, ї́хже, я́ко зві́зди небе́сния, по всей землі́ на́шей зрим; к єди́ному же із сих о́бразов, «Неупива́ємая Ча́ша» імену́ємому, припа́дающе, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, непреста́нноє люде́й удивле́ніє.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́льми на́ша не́мощі врачу́ющая.","Ра́дуйся, ми́лость Свою́ чрез чудотво́рния іко́ни Твоя́ нам сви́ше посила́ющая;","ра́дуйся, явле́нієм їх ско́рбная сердця́ на́ша возвеселя́ющая.","Ра́дуйся, пречу́дноє всіх с Бо́гом примире́ніє;","ра́дуйся, геє́нни ві́чния ізбавле́ніє.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нноє і ди́вноє ізбавле́ніє нам дарова́ся Твой о́браз честни́й, Влади́чице Богоро́дице, я́ко ізба́вльшеся явле́нієм єго́ от неду́гов душе́вних і тіле́сних і ско́рбних обстоя́ній, благода́рственная хвале́нія прино́сим Ті, Всеми́лостивая Засту́пнице. Ти же, Влади́чице, «Неупива́ємою Ча́шею» на́ми імену́ємая, приклони́ся благоутро́бно к на́шим воздиха́нієм і во́плем серде́чним і ізбавле́ніє пода́ждь стра́ждущим неду́гом пія́нства, да с ві́рою воззове́м Ті:","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Молитва","ps":["О, Преми́лостивая Влади́чице! К Твоєму́ заступле́нію ни́ні прибіга́єм, моле́ній на́ших не пре́зри, но ми́лостивно усли́ши нас, жен, діте́й і ма́терей, і ісціли́ тя́жким неду́гом пія́нства одержи́мих і того́ ра́ди от ма́тері своєя́, Це́ркве Христо́ви, і спасе́нія отпада́ющих бра́тій і сесте́р і сро́дник на́ших. О Ми́лостивая Ма́ти Бо́жия, косни́ся серде́ць їх і ско́ро возста́ви от паде́ній гріхо́вних, ко спаси́тельному воздержа́нію приведи́ їх. Умоли́ Си́на Своєго́, Христа́ Бо́га на́шего, да прости́ть нам согріше́нія на́ша і не отврати́ть ми́лости Своєя́ от люде́й Свої́х, но да укріпи́ть нас в трезве́нії і цілому́дрії. Прийми́, Пресвята́я Богоро́дице, моли́тви ма́терей, о ча́діх свої́х сле́зи пролива́ющих, жен, о мужеіх свої́х рида́ющих, чад, си́рих і убо́гих, заблу́дшими оста́вленних, і всіх нас, к іко́ні Твоє́й припа́дающих. І да при́йдеть сей вопль наш, моли́твами Твої́ми, ко Престо́лу Всеви́шняго. Покри́й і соблюди́ нас от лука́ваго ловле́нія і всіх ко́зней вра́жиїх, в стра́шний же час ісхо́да на́шего помози́ проіти́ непреткнове́нно возду́шная мита́рства моли́твами Твої́ми, ізба́ви нас ві́чнаго осужде́нія, да покро́єть нас ми́лость Бо́жия в несконча́ємия ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь притеце́м ві́рнії / к Боже́ственному і пречу́дному о́бразу Пресвяти́я Богома́тері, / напоя́ющей ві́рних сердця́ / небе́сною Неупива́ємою Ча́шею Своєго́ милосе́рдія / і лю́дем ві́рним чудеса́ показу́ющей. / Я́же ми ви́дяще і сли́шаще духо́вно пра́зднуєм і те́плі вопіє́м: / Влади́чице преми́лостивая, / ісціли́ на́ша неду́ги і стра́сті / моля́щи Си́на Твоєго́ Христа́ Бо́га на́шего // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, хода́тайство ко Творцю́ непрело́жноє, не пре́зри грі́шних моле́ній гла́си, но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті; ускори́ на моли́тву і потщи́ся на умоле́ніє, предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Піщанська»","e":"Akathist to the Theotokos before her icon “Peschansk”","secs":[{"h":"Кондак 1","ps":["Взбра́нная Воєво́до, всего́ ми́ра уті́шительнице і наде́ждо спасе́нія ро́да христия́нськаго, к Тебі́ припа́даєм во вся дні жи́зні на́шея, я́ко к істо́чнику всіх духо́вних дарова́ній, і мо́лим Тя: усли́ши нас, вопію́щих к Тебі́ в часи́ дневни́я і нощни́я, в болі́зніх і ско́рбіх, в ну́ждах і напа́стіх, всегда́ в ра́дості зову́щих:","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Ікос 1","ps":["А́нгелом предста́телем наче́нши, восхваля́єть Тя, Ма́тер Бо́жию, вселе́нная вся, я́ко Ти єси́ світ просвіще́нія ра́зума на́шего, Ти посредниця на́ша между́ на́ми і Бо́гом, Твоя́ Ма́тернія моли́тви мно́го мо́гуть пред Престо́лом Вседержи́теля, Ти десни́цею Своє́ю приво́диши нас от землі́ к Небесі́, Ти неізглаго́ланноє і непостижи́моє спасе́нія на́шего сокро́вище, і сего́ ра́ди не ві́ми, грі́шнії, ки́їми похвала́ми воспі́ти благода́рная Тебі́; прийми́ же от благи́х серде́ць велича́нія сія́:","Ра́дуйся, в ра́йськой сла́дости всегда́ пребива́ющая;","ра́дуйся, такови́я ра́дости всім жела́ющая.","Ра́дуйся, лю́б'ящих Си́на Твоєго́ ча́да Своя́ іменующая;","ра́дуйся, милосе́рдія Бо́жия нам хода́тайце.","Ра́дуйся, о продленії жи́зні на землі́ Си́на Своєго́ умоляющая;","ра́дуйся, за уме́рших всіх без покая́нія ви́ну скорб'я́щая.","Ра́дуйся, со А́нгелом храни́телем Храни́тельнице на́ша усе́рдная;","ра́дуйся, на Стра́шнім Суді́ Си́на Твоєго́ єди́на наде́ждо спасе́нія на́шего.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 2","ps":["Ви́диши, о Преблагослове́нная Ма́ти Бо́жия, ка́ко вели́ко беззако́ніє ро́да челові́чеськаго, і того́ ра́ди попусти́ Госпо́дь на зе́млю і живу́щия на ней глади, мори, тру́си, сухости і потопле́нія. Ти же, Всеми́лостивая, умоли́ Всеблага́го Бо́га, да удалить от ро́да сего́ фараони́тськоє жестокосе́рдіє, і да бу́деть он покорен десни́ці Госпо́дній, да при́йдеть в соверше́нноє покая́ніє, возопи́в Єму́ согла́сно: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом соверше́нним Небе́снаго ві́стника Гавриї́ла, благовіству́ющаго Тебі́ во́лю Бо́жию, я́ко Тебі́ Єди́ній би́ти блаже́нній в жена́х, восприя́ла єси́, Ма́ти Бо́жия. Та́же предрекла́ єси́, я́ко ублажа́ти Тя бу́дуть всі роди́, і от того́ часа́ возопію́ть Тебі́ свято́є хвале́ніє сицево́є:","Ра́дуйся, от Преві́чнаго Бо́га всего́ ми́ра ізбра́нная Отрокови́це;","ра́дуйся, Невмісти́маго Бо́га вмісти́лище, Спаси́теля на́шего во утро́бу Свою́ приє́мшая.","Ра́дуйся, Ма́терію Того́ от Го́спода найменованная;","ра́дуйся, от того́ же вре́мене весь мир Богоматернею любо́вію покрива́ющая.","Ра́дуйся, живи́х наде́ждо і усо́пших упова́ніє в стра́шний час Суда́ Бо́жия;","ра́дуйся, к отві́ту на Стра́шнім Суді́ нас приуготовляющая.","Ра́дуйся, от рождества́ до разлуче́нія душі́ от ті́ла на́шего нас не оставля́ющая;","ра́дуйся, побо́рнице на́ша на ра́ти зло́бних сил поднебе́сних.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго спа́се мир от потопле́нія гріхо́внаго воплоще́нієм от Тебе́ Си́на Бо́жия, Цари́це Небе́сная, і́бо враг ро́да на́шего дия́вол восхоті́ погуби́ти в отчужденії от і́стиннаго Бо́га весь род челові́чеський, в беззако́нії і ідолослуженії ходи́ти поуча́я. Госпо́дь же разруби сі́ті єго́ посла́нієм в мир Си́на Своєго́ Єдинароднаго і Тя, Ма́тер чи́стую, дарова́ нам, да побіжде́на бу́деть си́ла вра́жия, і да обратя́ться всі лю́діє к Творцю́ своєму́ і Бо́гу вопію́ще: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще такову́ю Посредницю спасе́нія на́шего, моля́щеся не престає́м взива́ти к Тебі́: бу́ди же нам огражде́ніє і стіна́ крі́пкая і необори́мая, сохрани́ нас во ві́рі правосла́вной отечеськой во вся дні жи́зні на́шея, научи́ ни покорству, чад Це́ркве Си́на Твоєго́, ю́же стяжа́ Христо́с Кро́вію Своє́ю честно́ю. Сподо́би нас благода́рними би́ти Бо́гу за вели́кия ми́лости Єго́, научи́ ісполня́ти за́повіді Єго́ і уста́ви святоотечеськия, направля́ющи нас, Всеблага́я, на путь спасе́нія. Ізба́ви от гріха́ і гні́ва Бо́жия, во є́же воспіва́ти Тебі́ благодаре́нія такова́я:","Ра́дуйся, неусипа́ющая Моли́твеннице і Хода́тайце на́ша пред Престо́лом Бо́жиїм;","ра́дуйся, на Небесі́х ца́рствующая і нас до́лі не оставля́ющая.","Ра́дуйся, всіх ра́достей неісчерпа́ємий істо́чниче;","ра́дуйся, сокро́вище, жизнь на́шу услажда́ющеє.","Ра́дуйся, недремлющая, нас же спя́щих сохраня́ющая;","ра́дуйся, на труди́ дневни́я нас благословляющая.","Ра́дуйся, благодаре́нія Бо́гу приноси́ти нас науча́ющая;","ра́дуйся, во дні пра́здников на путь ко хра́му Бо́жию стопи́ на́ша направля́ющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 4","ps":["Бу́рю внутр іму́ще помишле́ній сумни́тельних, сли́шаша лю́діє, о́крест живу́щії, о вели́цій си́лі благода́тній, ісходя́щей от іко́ни Богома́тере во гра́ді Ізюме, притеко́ша, припа́дающе ко о́бразу с ра́достію вели́кою, я́ко к Самі́й су́щей Цари́це Небе́сній, іму́ще наде́жду на Тя, Пречи́стая, і во весе́лії серде́ць возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша лю́діє всі, я́ко ві́рний Бо́гу і Тебі́, Богома́тері, служи́тель Твой святи́тель Іоаса́ф, узрі́во во сні іко́ну Твою́, в неведомом хра́мі в сорном мі́сті лежа́щую, і лучеза́рноє сія́ніє із нея́ ісходя́щеє, потща́ся воспомина́нієм чу́днаго виді́нія напра́вити стопи́ своя́ на путь ісканія святи́ні сея́ во всей обширней єпа́рхії своє́й. Єгдаже гра́да Ізюма дости́же, вшед в це́рков, ви́ді іко́ну Твою́, Богома́ти, в притво́рі у́гли кадильния ограждающую, і а́біє пом'яну́ єсть нощно́є виді́ніє, і благода́ть от нея́ ісходя́щую ощути́, і пад на колі́на, пред не́ю си́це моля́шеся: Прості́, Цари́це Небе́сная, небрежность Твої́х служи́телей, не ві́дять бо, что творя́ть, Тебі́ же Само́й во умиле́нії се́рдця возопи́ такова́я:","Ра́дуйся, іко́н Свої́х чудотво́рних храни́тельнице усе́рдная;","ра́дуйся, в со́нних виді́ніїх от іко́н Свої́х мно́гим си́лу благода́тную показу́ющая.","Ра́дуйся, ве́тхия іко́ни лучеза́рним сія́нієм обновля́ющая;","ра́дуйся, христия́ном, в біда́х су́щим, ко святи́м іко́нам Твої́м обраща́тися повеліва́ющая.","Ра́дуйся, святи́теля Іоаса́фа от ра́ннія ю́ности возлюби́вшая;","ра́дуйся, єму́же чудотво́рную си́лу в іко́ні Твоє́й Песчанськой открившая.","Ра́дуйся, пе́рвая єго́ моле́нія пред святи́нею се́ю прия́вшая;","ра́дуйся, сокро́вище в хра́мі Вознесе́нія Си́на Твоєго́ іко́ною Твоє́ю яви́вшая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 5","ps":["Стра́нно і сумнительно неверующим сли́шати, о Пресла́вная Ма́ти Царя́ Небе́снаго, ка́ко на Твой святи́й о́браз ві́рнії лю́діє очи́ма свої́ма і умиле́нними душа́ми взира́юще, і от скорбе́й ізбавля́ються, і от бід сохраня́ються. Бу́ди же нам, Всеблага́я, хода́тайця о спасе́нії на́шем, да ві́чно сла́вим Тя со всі́ми небожители, вопію́ще піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів ісполне́ніє Про́мисла Бо́жия на себі́ во обрі́тенії святи́ні Песчанськия, преби́сть святи́тель Іоаса́ф во гра́ді Ізюме три дні і три нощі́, по всяк час вознося́ в це́ркві благода́рственноє моле́бноє пі́ніє пред пречи́стим о́бразом Богома́тере, за є́же удосто́їся чу́днаго виді́нія і глас сли́шати: се́ю іко́ною Пресвята́я Влади́чиця явля́єть особоє зна́меніє Своєго́ засту́пничества гра́да сего́ і страни́ ці́лия, чесого́ ра́ди Богоро́диці возопії́м:","Ра́дуйся, ми́ра неіссякаємий істо́чниче;","ра́дуйся, се́рдця на́ша неізрече́нною ра́достію наполняющая.","Ра́дуйся, наде́жду іму́щих на Тя не посрамля́ющая;","ра́дуйся, іко́нам Свої́м си́лу чудоді́йствовати да́рующая.","Ра́дуйся, земни́х і малоду́шних нас не оставля́ющая;","ра́дуйся, печа́ль жите́йськую от серде́ць на́ших прогоня́ющая.","Ра́дуйся безро́дних сиро́т заступа́ющая Свої́м покро́вом і благода́тно сохраня́ющая;","ра́дуйся, райською ра́достію душі́ на́ша озаря́ющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 6","ps":["Я́ко Боготе́чную звізду́ ізюмстії лю́діє іко́ну Твою́ от рук святи́теля восприє́мше, потща́шася но́вий храм Бо́гу устро́їти. І бисть между́ создательми єго́ ра́спря на вре́м'я ні́коє; із загробнаго же ми́ра уме́ршая жена́ боля́рина ні́коєго бога́таго, три́щі явля́ющися му́жу своєму́ в со́нном виді́нії, повелі́ єму́ оста́вити ску́пость свою́, єя́же ра́ди поги́бель душі́ єго́ бисть, і сооруди́ти храм на бога́тство своє́. Он же, со стра́хом приї́м вразумле́ніє сви́ше, созда́ храм в честь Вознесе́нія Си́на Твоєго́, Пречи́стая, і во весе́лії се́рдця возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ іко́на Твоя́ чудотво́рная, Богома́ти, єгда́ принесе́на бисть в новосозданний храм. Лю́діє ві́рнії стека́хуся со всіх стран от жили́щ свої́х і наполняху не то́кмо храм, но і огра́ду, і в ра́дості духо́вной взива́ху Ті си́це:","Ра́дуйся, пе́рвійшая помо́щнице в созда́нії хра́ма на́шего;","ра́дуйся, обогати́вшая о́ний іко́ною Твоє́ю чудотво́рною.","Ра́дуйся, поклоне́нія на́ша приє́млющая;","ра́дуйся, тве́рдоє основа́ніє упова́нія на́шего.","Ра́дуйся, град наш покро́вом Твої́м при́сно покрива́ющая;","ра́дуйся, неуси́пная Попечи́тельнице на́ша.","Ра́дуйся, Богоматернею любо́вію нас согріва́ющая;","ра́дуйся, на вся́кий час в моли́твах нас приє́млющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 7","ps":["Бисть ні́кий учи́тель во гра́ді Ізюме, у него́же младе́нці єди́н по єди́ному умира́ху. Єгда́ же послі́дній бисть одержи́м болі́знію ве́лієй, взе́мше роди́телі єго́ і несо́ша к іко́ні Твоє́й, Богома́ти, іму́ще єди́ну наде́жду на Тя. Єще́ же на путі́ їм су́щу, коне́ць пости́же младе́нця сего́. Роди́телі же єго́, іму́ще вели́кую ві́ру Тебі́, Пречи́стая, положи́ша младе́нця уме́ршаго пред іко́ною Твоє́ю. Во вре́м'я же пі́нія моле́бнаго нача́ша со слеза́ми і во́плем го́рким взива́ти: Ма́ти Бо́жия, помози́ нам, спаси́ ча́до на́ше. Ти же, Всеми́лостивая, ви́дящи тве́рдую ві́ру їх і упова́ніє на Тя, возврати́ла жизнь младе́нцю. Тогда́ же і лю́діє, о́крест стоя́щії, в ра́дості неізрече́нній прославля́ху Тя, Пречи́стая, і Вседержи́теля Го́спода хваля́ху пі́снію: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє показа́ чу́до Цари́ця Небе́сная, єгда́ во вре́м'я пі́нія «О Всепі́тая Ма́ти» воскре́сшему младе́нцю уста́ отве́рзе і повелі́ єму́ гла́сом возда́ти хвалу́ Тебі́. Всі же, зря́ще зна́меніє сіє́, во умиле́нії серде́чнім возопи́ша Тебі́ та́ко:","Ра́дуйся, уме́рших оживле́ніє;","ра́дуйся, рида́ющих роди́телей увеселе́ніє.","Ра́дуйся, чудеса́ми от іко́ни Твоєя́ к Себі́ призива́ющая;","ра́дуйся, безнаде́жних Наде́ждо крі́пкая.","Ра́дуйся, Пода́тельнице утіше́нія унивающим;","ра́дуйся, в ско́рбіх су́щих приє́млющая.","Ра́дуйся, у Си́на Твоєго́ і Бо́га на́шего вся́ких благ нам іспроша́ющая;","ра́дуйся, всю жизнь на́шу земну́ю во бла́го нам устроя́ющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 8","ps":["Хотя́щи яви́ти ко всім притекающим милосе́рдіє Своє́, вразумила єси́ служи́теля Олтаря́ Госпо́дня, і́же во іскуше́ніє впаде́ от врага́ ро́да челові́чеськаго і за́вистію му́чим, дерзну́ запрети́ти моле́бноє пі́ніє Цари́це Небе́сній пред іко́ною Єя́, поразила єси́ того́ болезею. Єгда́ же принесо́ша єго́ на одрі́ і положи́ша пред чудотво́рним о́бразом Твої́м, нача́ моли́ти Тя: Ма́ти Милосе́рдная, прості́ ожесточе́ніє се́рдця моєго́ і воздви́гни м'я от одра́ болі́зні. По сконча́нії же пі́нія моле́бнаго, ісціле́ніє восчувствовав, воста́в, облобиза́ честни́й о́браз, со слеза́ми благода́рні вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся би́вши го́ре, і земни́х не оставля́єши, о Всеблага́я і Всеми́лостивая Ма́ти Бо́жия: Ти, я́коже і Син Твой, не хо́щеши сме́рти грі́шника, но є́же обрати́тися і живу́ єму́ би́ти. За такову́ю Твою́ ми́лость взива́єм всі Тебі́:","Ра́дуйся, ієре́єв Бо́жиїх вразумле́ніє;","ра́дуйся, вре́менно наказу́ющая і ві́чно ми́лующая.","Ра́дуйся, в болі́зніх су́щих к Себі́ призива́ющая;","ра́дуйся, і́стинному покая́нію науча́ющая.","Ра́дуйся, неусипа́ющая Моли́твеннице і Хода́тайце на́ша пред Престо́лом Бо́жиїм;","ра́дуйся, наде́жду іму́щих на Тя нікогда́же посрамля́ющая.","Ра́дуйся, разсла́бленним ті́лом і ду́хом ско́роє врачева́ніє подава́ющая;","ра́дуйся, во вся́кой біді́ і ну́жді нас не оставля́ющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся о неописуємом мо́рі чуде́с, ізливаємом от іко́н Твої́х, Богоро́дице: Тебі́ ублажа́ють всі роди́, Тебі́ велича́ють вся Небе́сния Си́ли, і ми, земноро́днії, Тебе́, єди́ну отра́ду і утіше́ніє в жи́зні сей вре́менній, прославля́юще, оТебе Си́ну Твоєму́ вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії яви́шася лю́діє, обрі́тше по́мощ во вели́цім озлобле́нії своє́м, єгда́ за беззако́нія їх попусти́ Госпо́дь вели́цій болі́зні во гра́ді Ізюме би́ти і во всіх ве́сіх єго́, і мно́жество люде́й погибо́ша. Страх же нападе́ на всяк во́зраст. Ті́мже лю́діє, взе́мше Пречи́стий о́браз Твой, несо́ша єго́ освяще́нія ра́ди улиць і домо́в, с моли́твою сле́зною взива́юще: О Всеблага́я Ціли́тельнице, спаси́ нас от сме́рти лю́тия. Ти же, Всеми́лостивая, укроти́ла бу́рю сме́ртную, лю́ди же научи́ла єси́ благода́рственно воспіва́ти Бо́гу сла́ву подоба́ющую, Тебі́ же Само́й взива́ти си́це:","Ра́дуйся, сле́зи на́ша ізсушающая;","ра́дуйся, бе́здно врачева́ній неістощи́мая.","Ра́дуйся, ра́дость в хра́мини на́ша принося́щая;","ра́дуйся, роди́телей ми́лующая і діте́й сохраня́ющая.","Ра́дуйся, весе́ліє ві́чноє нам уготовля́ющая;","ра́дуйся, с на́ми присносу́щая.","Ра́дуйся, в земно́м уді́ле нас не оставля́ющая;","ра́дуйся, к небе́сному наслі́дію нас руково́дствующая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи лю́ди Своя́ от зол мно́гих, дарова́ла єси́ іко́ну Твою́, Влади́чице, сліпи́м в прозрі́ніє, хроми́м в хожде́ніє, разсла́бленним во воста́ніє, беснующимся в ісціле́ніє, го́рдим в смире́ніє, нераскаянним в покая́ніє, всім коєго́ждо неду́га ісціле́ніє, зол і скорбе́й, і болі́зней отгна́ніє, градо́в утвержде́ніє, землі́ плодоно́сіє, за ня́же нікто́же от земноро́дних возмо́жеть восхвали́ти Тя по достоя́нію, по вели́честву ми́лости Твоєя́ к ро́ду челові́чеському. Ми же, любо́вію понужда́єми, дерза́єм взива́ти Бо́гу, усиновившему нас Тебі́ при Кресті́ Своє́м і дарова́вшему нам такову́ю Путеводительницю на Не́бо: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ всім прибегающим к Тебі́, Ді́во, всегда́ явля́єшися, і почита́телю іко́ни Твоєя́ Ігна́тію, імевшему благо́є намі́реніє посіти́ти святи́й град Ієрусали́м і Святу́ю Зе́млю, ю́же освяти́ Госпо́дь стопа́ми Свої́ми, Помо́щниця єси́ яви́лася, єгда́ той, пад пред о́бразом Твої́м, проша́ше на путь благослове́нія і по́мощі Твоєя́. Ти же, Всеще́драя, неотло́жно чрез рабу́ ні́кую зла́та дово́льно подала́ єси́ єму́, да іспо́лнить благо́є жела́ніє своє́. Он же умиле́нною душе́ю вознесе́ Тебі́ благода́рственноє хвале́ніє сицево́є:","Ра́дуйся, до́брая намі́ренія благословляющая;","ра́дуйся, на путь к Ца́рствію Небе́сному нас наставля́ющая.","Ра́дуйся, спаси́тельною і́стиною нас вразумляющая;","ра́дуйся, к благоче́стію і цілому́дрію жизнь на́шу направля́ющая.","Ра́дуйся, на опа́сних путеіх нас охраня́ющая;","ра́дуйся, от собла́знов ми́ра сего́ му́дро отводя́щая.","Ра́дуйся, от поги́бельнаго путі́ сохраня́ющая;","ра́дуйся, посещающих свята́я мі́ста оби́льно благословляющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє хвалебноблагода́рственноє принося́ще Тебе́, Влади́чице, ві́ми, каковую скорб прино́сим грі́шнії Си́ну Твоєму́ отсту́пстви свої́ми, малові́рієм, суєві́рієм і про́чим злові́рієм. Моли́ти у́бо Тебі́, Всеми́лостивая, не престає́м: Свої́м предста́тельством і хода́тайством пред Престо́лом Бо́жиїм сохрани́ нас в ло́ні Святі́й Собо́рній і Апо́стольстій Це́ркві, да бу́дем всі єди́но, я́коже Оте́ць, Син і Святи́й Дух. Да в єди́нстві ві́ри воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко світоприє́мную свіщу́ яви́ла єси́, Влади́чице, іко́ну Твою́ во гра́ді сем Ізюме, істо́чник благода́тния води́ откри́ла єси́ близ хра́ма Си́на Твоєго́, іді́же іко́на Твоя́ чудотво́рная Песчанськая пребива́єть, слепорожденному младе́нцю прозрі́ніє от нея́ дарова́ла єси́, за є́же лю́діє от вре́мене того́ почерпа́ють благи́й дар сей на по́льзу душе́вную і тіле́сную. Тебі́ же Само́й, Влади́чице, от усе́рдія своєго́ взива́ють:","Ра́дуйся, жи́зні на́шея укріпле́ніє;","ра́дуйся, водо́ю свято́ю не́мощі на́ша врачу́ющая.","Ра́дуйся, почерплющим єя́ си́ли обновля́ющая;","ра́дуйся, беззако́нія на́ша істребля́ющая.","Ра́дуйся, с ві́рою приємлющим ісціле́ніє неду́гов подава́ющая;","ра́дуйся, неістощи́мий кла́дезю сокро́вищ духо́вних.","Ра́дуйся, скве́рну нечистоти́ на́шея умивающая;","ра́дуйся, чудотво́рною си́лою водни́й істо́чник дони́ні сохраня́ющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 12","ps":["Благода́ть ісхо́дить всегда́, Пречи́стая, от іко́ни Твоєя́ Песчанськия: я́ко непобіди́мая Воєво́да на враги́ на́ша, ви́димия і неви́димия, нечи́стия ду́хи прогоня́єши, враждующия ми́ром і любо́вію умудря́єши, непокорния наказу́єши, раздо́ри семейния соу́зом любве́ связуєши, неведущия і неві́рующія на путь і́стинний наставля́єши; ми же, прославля́юще Тя, Всеблагу́ю Помо́щницю в жи́зні на́шей, благода́рні воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м Твоє́ із дре́вніх време́н ди́вноє защище́ніє Оте́чества на́шего, єгда́ постиго́ша єго́ глади і мори, огнь і опустоше́ніє, наше́ствія іноплеме́нних і междоусо́бния бра́ні. У Тебе́, Влади́чице, отці́ і ма́тері, і ма́лая ді́ти со слеза́ми по́мощі проша́ху, Ти же, Всеблага́я, спасе́ніє дарова́ла єси́ неотло́жно, покрива́ющи омофо́ром Твої́м Оте́чество на́ше. Ми же Тебі́, Ізба́вительнице на́шей, вопіє́м сіє́ благодаре́ніє і похвали́ сицева́я:","Ра́дуйся, правові́рних ві́рная Храни́тельнице;","ра́дуйся, пра́вия бра́ні Спобо́рнице.","Ра́дуйся, христия́нських оби́телей і всіх святи́нь Храни́тельнице;","ра́дуйся, о Оте́честві на́шем пред Бо́гом Моли́твеннице.","Ра́дуйся, Оте́чества на́шего небе́снаго Зиждительнице;","ра́дуйся, во времена́ наше́ствія інові́рних на́ша Свободи́тельнице.","Ра́дуйся, во вре́м'я гла́да на́ша Корми́тельнице;","ра́дуйся, во вре́м'я бі́дствій нас не оставля́ющая.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, прийми́ от нас благода́рноє пі́ніє сіє́, Тебі́ возноси́моє. Бу́ди нам в жи́зні сей Хода́тайця пред Бо́гом о Жи́зні Ві́чной, да ви́ну благода́рно восхваля́єм Тя і Бо́гу поє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом предста́телем наче́нши, восхваля́єть Тя, Ма́тер Бо́жию, вселе́нная вся, я́ко Ти єси́ світ просвіще́нія ра́зума на́шего, Ти посредниця на́ша между́ на́ми і Бо́гом, Твоя́ Ма́тернія моли́тви мно́го мо́гуть пред Престо́лом Вседержи́теля, Ти десни́цею Своє́ю приво́диши нас от землі́ к Небесі́, Ти неізглаго́ланноє і непостижи́моє спасе́нія на́шего сокро́вище, і сего́ ра́ди не ві́ми, грі́шнії, ки́їми похвала́ми воспі́ти благода́рная Тебі́; прийми́ же от благи́х серде́ць велича́нія сія́:","Ра́дуйся, в ра́йськой сла́дости всегда́ пребива́ющая;","ра́дуйся, такови́я ра́дости всім жела́ющая.","Ра́дуйся, лю́б'ящих Си́на Твоєго́ ча́да Своя́ іменующая;","ра́дуйся, милосе́рдія Бо́жия нам хода́тайце.","Ра́дуйся, о продленії жи́зні на землі́ Си́на Своєго́ умоляющая;","ра́дуйся, за уме́рших всіх без покая́нія ви́ну скорб'я́щая.","Ра́дуйся, со А́нгелом храни́телем Храни́тельнице на́ша усе́рдная;","ра́дуйся, на Стра́шнім Суді́ Си́на Твоєго́ єди́на наде́ждо спасе́нія на́шего.","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Кондак 1","ps":["Взбра́нная Воєво́до, всего́ ми́ра уті́шительнице і наде́ждо спасе́нія ро́да христия́нськаго, к Тебі́ припа́даєм во вся дні жи́зні на́шея, я́ко к істо́чнику всіх духо́вних дарова́ній, і мо́лим Тя: усли́ши нас, вопію́щих к Тебі́ в часи́ дневни́я і нощни́я, в болі́зніх і ско́рбіх, в ну́ждах і напа́стіх, всегда́ в ра́дості зову́щих:","Ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Молитва","ps":["О преми́лостивая і премилосе́рдная Ма́ти Бо́жия, Покрови́тельнице держа́ви на́шея, ку́пно же і о всем ми́рі Моли́твеннице, прийми́ се́рдця на́шего воздиха́нія, і усли́ши коленопреклоненния моли́тви, во умиле́нії душ на́ших Тебі́ возсилаємия, я́коже іздре́вле приймала єси́ моли́тви лю́б'ящих душ зді, пред іко́ною Твоє́ю возноси́мия. Помози́ нам в побіжде́нії пре́лестей і собла́знов ми́ра сего́, не попусти́ нам отве́рженним би́ти ві́чнаго Небе́снаго блаже́нства. Ти Єди́на на́ша ра́дость і утіше́ніє в жи́зні сей вре́менній, Ти на́ша наде́жда і в Жи́зні Ві́чній. Ві́руєм, я́ко Ти Своє́ю Ма́тернею любо́вію і снисхожденієм удостоїши нас вожделі́ннаго Ца́рствія Си́на Твоєго́. Тебі́ у́бо про́сим: не отступа́й от нас, Всеблага́я, защища́й от всіх ко́зней вра́жиїх, не попусти́ нам чрез гріхи́ на́ша лиши́тися милосе́рдія Бо́жия, ізжени́ із нас лі́ность в моли́тві і посіще́нії хра́ма Бо́жия. Ізба́ви нас от малоду́шія, уни́нія, вражди́, гні́ва, подозрі́нія, за́висти, клевети́, не́нависті і го́рдості бісо́вськия. Вразуми́ попра́вших за́повіді Це́ркве Христо́ви. Сро́дником на́шим да́руй мир і любо́в, да согла́сно поживу́ть роди́телі і ді́ти. Да бу́деть в страні́ на́шей пра́вда Бо́жия, да сохраня́ться в наро́ді на́шем благочести́вії оби́чаї. Вознеси́, о Всеблага́я, усе́рдния моли́тви пред Бо́гом о всего́ ми́ра умире́нії, да не поги́бнеть род людськи́й в пла́мені опустошенія всеми́рнаго, да позна́ють всі наро́ди Отця́ Своєго́ Небе́снаго і Тя, Ма́тер Бо́жию, Засту́пницю ро́да христия́нськаго. Приведи́ вся наро́ди к і́стинному покая́нію і жи́зні гріхо́вния ісправле́нію, да не осу́димся в день Стра́шнаго Суда́ Бо́жия, но да сподо́бит нас Госпо́дь ві́чния ра́дости в Небе́сних селе́ніїх, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["О Пречу́дная, Преблагослове́нная Ма́ти Христа́ Бо́га на́шего, сві́том небе́сним от іко́ни Твоєя́ лю́ди страни́ Украї́нськия при́сно озаря́ющая, Ти бо єси́ преізоби́льная ріка́ Благода́ті Боже́ственния. Сего́ ра́ди к Си́ну Твоєму́ моли́твами Твої́ми от вся́ких бід нас защити́, покро́вом ми́лости Твоєя́ огради́ і в Го́рній Ієрусали́м, Ца́рствіє Небе́сноє, возведи́."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді і покрови́тельнице страни́ Украї́нськия, мно́гая чудеса́ от іко́ни Твоєя́ преди́вния приє́мше, похва́льная воспіва́єм Ті, Цари́це Богоро́дице; Ти же, я́ко іму́щи благода́ть от вся́ких нас бід свобожда́ти, спаси́ душі́ на́ша, да зове́м Ті: ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Новоникитська»","e":"Akathist to the Theotokos before her icon “Novonikitsk”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Преблагослове́нній Ді́ві Богоро́диці похва́льноє прино́сим пі́ніє; Ти же, я́ко іму́щая держа́ву непобіди́мую і милосе́рдіє неізрече́нноє, от вся́ких нас бід і скорбе́й свободи́ і от наві́тов вра́жиїх защити́, да зове́м Ті: Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов чи́ни благогові́йно Тебі́ слу́жать і вся Небе́сния Си́ли немо́лчними гла́си Тя, Пресвята́я Ді́во, воспіва́ють, я́ко ро́ждшую Царя́ Небе́снаго. Ми же, предстоя́ пред чудотво́рним о́бразом Твої́м, со умиле́нієм поє́м Ті такова́я:","Ра́дуйся, благода́ть у Бо́га обрі́тшая.","Ра́дуйся, па́че А́нгел возвели́ченная.","Ра́дуйся, Арха́нгельським благові́стієм обра́дованная.","Ра́дуйся, две́рі ра́йськія нам отве́рзшая.","Ра́дуйся, смире́нная Рабо́ Госпо́дня.","Ра́дуйся, от всіх родо́в ублажа́ємая.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 2","ps":["Ви́дящи Всенепоро́чная Ма́ти с висоти́ Небе́сния, іді́же Ти с Сино́м Твої́м во сла́ві пребива́єши, бі́ди і ско́рби люде́й Твої́х, яви́ла єси́ нам іко́ну Твою́, да утвержда́єми зна́меньми Твоєя́ благода́ті, ві́рно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний откривающи, Богоро́дице Ді́во, благоволи́ла єси́ мно́гими чудеси́ просла́вити іко́ну Твою́ святу́ю, да всі, ві́дущи таково́є Твоє́ о ней благоволе́ніє, пі́сненно зову́ть Ті такова́я:","Ра́дуйся, сосу́дом Богоізбра́нним соделавшаяся.","Ра́дуйся, Мате́рією Бо́жиєю ста́ти сподо́бившаяся.","Ра́дуйся, Одіва́ющагося сві́том я́ко ри́зою пелена́ми пови́вшая.","Ра́дуйся, Жизнода́вця Ісу́са млеко́м Твої́м пита́вшая.","Ра́дуйся, о Рождестві́ Твоє́м от волхво́в поклоне́ніє приі́мшая.","Ра́дуйся, Нося́щаго весь мир дла́нію на руку́ Твоє́ю носи́вшая.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 3","ps":["Си́ла благода́тная осіня́єть всіх, Цари́це Небе́сная, с ві́рою к Тебі́ притека́ющих: єди́ній бо то́чію Тебі́ даде́ся, да вся́коє проше́ніє Твоє́ іспо́лниться. Тім у́бо всяк во́зраст ві́рних славосло́вить Тя і Си́на Твоєго́, зову́щ: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи ма́тернюю любо́в к лю́дем, Всеблага́я, всім в біда́х і напа́стіх к Тебі́ прибегающим, ру́ку по́мощі простира́єши. Ми же, все упова́ніє о спасе́нії своє́м возложи́вше на Тя, Пресвята́я Ді́во, с наде́ждою взива́єм Ті:","Ра́дуйся, А́нгелами хвали́мая і Серафи́мами воспіва́ємая.","Ра́дуйся, я́ко Тобо́ю вся вселе́нная ра́дости і весе́лія ісполня́ється.","Ра́дуйся, я́ко от вся́кия душі́ христия́нськия проше́ніє ми́лостиво приє́млеши.","Ра́дуйся, я́ко покро́вом Твої́м весь род челові́чеський покрива́єши.","Ра́дуйся, я́ко благода́тную си́лу Твою́ іко́нам Твої́м дарова́ла єси́.","Ра́дуйся, я́ко чрез святи́я іко́ни Твоя́ Сама́ неви́димо посреді́ нас пребива́єши.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 4","ps":["Бу́рею сомні́ній обдержи́м бі во́їн готфський Ники́та, єгда́ у́зрі во виді́нії со́ннім О́трока прекра́снаго, крест в руці́ Своє́й держашаго. Не могу́ще же єму́ ра́зумом свої́м сего́ пости́гнути, ді́ва ні́кая Іуліянія повелі́ єму́ взор свой на пе́рси своя́ напра́вити, на ни́хже бі о́браз Твой святи́й, Пречи́стая Ді́во. Он же, див'я́ся сему́, со умиле́нієм возопи́ Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав во́їн Ники́та, я́ко чуде́с вели́коє мно́жество і благодія́нія неісче́тная ісхо́дять от іко́ни Твоєя́, непреста́нно благодари́ Тя, Ма́ти і Ді́во, за ми́лості Твоя́ ро́ду христия́нському; Тобо́ю же вразумляємий, мно́гия лю́ди наста́ви на путь спаси́тельний і похва́льная Тебі́ зва́ти научи́:","Ра́дуйся, я́ко благода́ть Твою́ ро́ду челові́чеському низпосила́єши.","Ра́дуйся, я́ко ві́рним вся блага́я в жи́зні сей ми́лостиво подає́ши.","Ра́дуйся, благочести́вих христия́н Наста́внице.","Ра́дуйся, боголюби́вих і́ноков Попечи́тельнице.","Ра́дуйся, веду́щих брань проти́ву ми́ра, пло́ті і дия́вола до́брая Споспі́шнице.","Ра́дуйся, ревнующим о цілому́дрії і чистоті́ ізря́дная Пособнице.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся іко́на Твоя́ Новоникитськая, Влади́чице, сего́ ра́ди притека́ющії к Тебі́ ну́жди своя́ і ско́рби пред не́ю прино́сять, мно́гая же ми́лости от Тебе́ приє́млюще, ра́достно вопію́ть Пода́телю всіх благ: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще христолюби́вії лю́діє Тобо́ю подава́ємоє їм от многообра́зних бід ізбавле́ніє, познаю́ть вели́чіє Твоє́ на Небесі́ і с любо́вію вопію́ть Ті си́це:","Ра́дуйся, Преблагослове́нная, покро́в Свой над на́ми простирающая.","Ра́дуйся, іко́ною Твоє́ю, я́ко стіно́ю неруши́мою, лю́ди Твоя́ огражда́ющая.","Ра́дуйся, сосу́де благода́ті ізбра́нний, ми́ро благово́нноє в сердця́ на́ша ізливающий.","Ра́дуйся, милосе́рдія істо́чниче, жа́ждущим утіше́ніє істоча́ющий.","Ра́дуйся, в злих обстоя́ніїх ско́рая Помо́щнице.","Ра́дуйся, ві́чния ра́дости Хода́тайце.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь ми́лості і чудеса́, от іко́ни Твоєя́ бива́ємая, Пресвята́я Ді́во, Ти бо вся́кия болі́зні чрез сію́ ісціля́єши і ско́рби утоля́єши. Сего́ ра́ди со благогові́нієм почита́єм многоціле́бний о́браз Твой і, моля́щеся пред ним, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ я́ко пресві́тлая заря́ свята́я іко́на Твоя́, Богома́ти Пречи́стая, є́юже ісціле́нія і по́мощ ві́рним оби́льно подає́ши. Ми же, таково́му промишле́нію пред бо́гом о нас див'я́ся, с любо́вію прино́сим Тебі́ пі́нія сицеви́я:","Ра́дуйся, ко Христу́ Бо́гу всіх нас приводя́щая.","Ра́дуйся, безчи́сленния щедро́ти всім подаю́щая.","Ра́дуйся, я́ко іко́ною Твоє́ю вся лю́ди возвеселя́єши.","Ра́дуйся, я́ко ско́рби на́ша в ра́дость претворяєши.","Ра́дуйся, Боже́ственния благода́ті неістощи́мая сокро́вищнице.","Ра́дуйся, моли́тв на́ших пред Бо́гом злата́я кади́льнице.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 7","ps":["Хотя́ще от бід, зол і напа́стей ізба́витися, со слеза́ми предстої́м пред іко́ною Твоє́ю честно́ю, о Богома́ти, моля́щи, да не пре́зриши проше́ній на́ших, но спасе́ши всіх нас, при́сно зову́щих Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вна і пресла́вна діла́ Твоя́, Влади́чице, всім бо с прилі́жною моли́твою к цільбоно́сній іко́ні Твоє́й притекающим вся блага́я по коєго́ждо потре́бі подає́ши. Ті́мже і ми, благода́рно прославля́я ми́лості Твоя́, глаго́лем Ті:","Ра́дуйся, во вся́кой ну́жді нам помога́ющая.","Ра́дуйся, упова́ющих на Тя по́мощію Твоє́ю не оставля́ющая.","Ра́дуйся, Тобо́ю бо низхо́дить к нам Бо́жиє благоволе́ніє.","Ра́дуйся, Тобо́ю бо і́мами к Бо́гу в'я́щеє дерзнове́ніє.","Ра́дуйся, звіздо́, путь нам во тьмі указу́ющая.","Ра́дуйся, ми́сленная очеса́ на́ша ко го́рнім оби́телем направля́ющая.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 8","ps":["Стра́нно і непости́жно єсть неві́рним разумі́ти, ка́ко чрез ізображе́ніє пречи́стаго ли́ка Твоєго́ чудеса́ явля́єши, Преблагослове́нная Ді́во. Ми же, сли́шаще і ви́дяще, я́ко многообра́зна єсть по́мощ Твоя́, чрез іко́ни Твоя́ нам ще́дро подаваємая, в ра́дості вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир христия́нський ублажа́єть Тя гла́си хвале́бними, Пречи́стая Ді́во Богоро́дице, всім бо ві́рним уті́шительно єсть взира́ти на всечестну́ю іко́ну Твою́. О Влади́чице, прийми́ і на́ша умиле́нная благохвале́нія такова́я:","Ра́дуйся, лі́ствице, в го́рнія оби́телі нас возводя́щая.","Ра́дуйся, кни́го, та́йни Ца́рствія Бо́жия ві́рним открива́ющая.","Ра́дуйся, лучеза́рний сві́те любве́ і всепроще́нія.","Ра́дуйся, сосу́де Боже́ственний ві́чнаго блаже́нства.","Ра́дуйся, усе́рдная о нас пред Го́сподем Моли́твеннице.","Ра́дуйся, несконча́ємия жи́зні Пода́тельнице.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ А́нгельськаго преви́шшая яви́лася єси́, Преблага́я Ма́ти, ті́мже на Небесі́ прехва́льно і́м'я Твоє́, і на землі́ блажа́ть Тя всі роди́. Ми же грі́шними уста́ми дерза́єм возвеличившему Тя Бо́гу взива́ти о Тебі́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть по достоя́нію восхвали́ти преди́вная чудеса́, от святи́я іко́ни Твоєя́ Новоникитськия явля́ємая; сего́ ра́ди, вся чудеса́ от нея́ бива́ємая ви́дяще, при́сно ублажа́єм Тя похвала́ми си́ми:","Ра́дуйся, за христия́ни Си́ну Твоєму́ усе́рдно моля́щаяся.","Ра́дуйся, гра́ду Ни́кополю іко́ну Твою́, я́ко зало́г Твоєго́ благоволе́нія, дарова́вшая.","Ра́дуйся, всім скорб'я́щим і обремене́нним утіше́ніє і ра́дость принося́щая.","Ра́дуйся, в час сме́ртний єди́ная на́ша наде́жда, отра́да і утіше́ніє.","Ра́дуйся, А́нгельських сил непрестаю́щеє ликова́ніє.","Ра́дуйся, притека́ющих к Тебі́ непости́дноє упова́ніє.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ вся́каго челові́ка, Син Твой і Бог наш ми́лостиво приє́млеть вся моли́тви Твоя́ о нас; ті́мже всі ві́рнії в біда́х і ско́рбіх прибіга́ють к ско́рому заступле́нію Твоєму́, Преблагослове́нная Ді́во, і благода́рственно вопію́ть о Тебі́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і огражде́ніє бу́ди нам, Всеми́лостивая Влади́чице, ізнемога́ющим от скорбе́й і болі́зней, покри́й покро́вом Твої́м святи́м с ві́рою покланя́ющихся Тебі́ пред чудотво́рним Твої́м о́бразом і с любо́вію вопію́щих такова́я:","Ра́дуйся, ри́зою Твоє́ю честно́ю нас защища́ющая.","Ра́дуйся, от бу́рі іскуше́ній і бід нас огражда́ющая.","Ра́дуйся, ві́рних от ві́чния поги́белі спаса́ющая.","Ра́дуйся, помишле́нія на́ша освяща́ющая.","Ра́дуйся, серде́ць на́ших очище́ніє і обновле́ніє.","Ра́дуйся, цві́те ві́ри неув'яда́ємий.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє воспіва́єм Ті, Богороди́тельнице, я́ко моли́твами Твої́ми к Си́ну Твоєму́ і Бо́гу на́шему гра́ди і ве́сі от злих обстоя́ній сохраня́єши, мир і вся блага́я в жи́зні всім чту́щим Тя подає́ши, на путь спасе́нія наставля́єши і всіх вразумля́єши воспіва́ти Милосе́рдному Человіколю́бцю Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рними луча́ми чуде́с іко́на Твоя́, Влади́чице, немерца́ємо сія́єть і страну́ на́шу правосла́вную благода́тно озаря́єть, прогоня́я си́лою Бо́жиєю вся́коє ді́йство вра́жиє, і побужда́я нас Тебі́, Богоізбра́нная Отрокови́це, хвале́бная пі́нія возноси́ти:","Ра́дуйся, во сла́ві присідя́щая Престо́лу Боже́ственнаго Си́на Твоєго́ і та́мо нас воспомина́ющая.","Ра́дуйся, с Сино́м Твої́м і Бо́гом на́шим ві́чно ца́рствующая і о нас пред Ним хода́тайствующая.","Ра́дуйся, теплото́ю благода́ті Твоєя́ хла́дния сердця́ на́ша согріва́ющая.","Ра́дуйся, ми́сленная очеса́ на́ша ко го́рнім оби́телем направля́ющая.","Ра́дуйся, уповающим на Тя жи́зні коне́ць непости́ден да́рующая.","Ра́дуйся, безболі́зненную і ми́рную кончи́ну ві́рним устроя́ющая.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пниця."]},{"h":"Кондак 12","ps":["Благода́ть ве́лія дана́ Ті от Бо́га, Преблагослове́нная Ма́ти Бо́жия, убо́гія назира́ти, боля́щия ісціля́ти, бедствующим помога́ти, скорб'я́щия утіша́ти і всіх заблужда́ющихся на путь спасе́нія обраща́ти; ті́мже всі тружда́ющіїся і обремене́ннії неізлаго́ланния ми́лості Твоя́ приє́мля, уми́льно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́, ї́миже явля́єши нам любо́в Твою́ і милосе́рдіє, восхваля́єм Тя, Влади́чице, і, предстоя́ще пречи́стому о́бразу Твоєму́, мо́лим Тя: утоли́ на́ша печа́лі і ізба́ви нас от вся́каго зла, да всегда́ в любві́ Твоє́й пребива́юще, во умиле́нії серде́чнім зове́м Ті:","Ра́дуйся, честні́йшая Херуви́м.","Ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, А́нгельських чино́в пресла́вная Цари́це.","Ра́дуйся, Небе́сних і земни́х Влади́чице.","Ра́дуйся, в час недоумі́ній нас вразумляющая.","Ра́дуйся, о́чі духо́вния на́ша отверза́ющая.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Цари́це Небе́сная, ро́ждшая Христа́ Бо́га на́шего, прийми́ сіє́ от всего́ се́рдця на́шего приноси́моє Тебі́ моле́ніє, і всеси́льним Твої́м предста́тельством сохрани́ нас от вся́ких бід і напа́стей в жи́зні сей, і сподо́би в блаже́нстві ві́чном со всі́ми святи́ми хвалу́ Бо́гу воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов чи́ни благогові́йно Тебі́ слу́жать і вся Небе́сния Си́ли немо́лчними гла́си Тя, Пресвята́я Ді́во, воспіва́ють, я́ко ро́ждшую Царя́ Небе́снаго. Ми же, предстоя́ пред чудотво́рним о́бразом Твої́м, со умиле́нієм поє́м Ті такова́я:","Ра́дуйся, благода́ть у Бо́га обрі́тшая.","Ра́дуйся, па́че А́нгел возвели́ченная.","Ра́дуйся, Арха́нгельським благові́стієм обра́дованная.","Ра́дуйся, две́рі ра́йськія нам отве́рзшая.","Ра́дуйся, смире́нная Рабо́ Госпо́дня.","Ра́дуйся, от всіх родо́в ублажа́ємая.","Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Преблагослове́нній Ді́ві Богоро́диці похва́льноє прино́сим пі́ніє; Ти же, я́ко іму́щая держа́ву непобіди́мую і милосе́рдіє неізрече́нноє, от вся́ких нас бід і скорбе́й свободи́ і от наві́тов вра́жиїх защити́, да зове́м Ті: Ра́дуйся, Пресвята́я Влади́чице, ми́лостивая пред Бо́гом о нас Засту́пнице."]},{"h":"Молитва","ps":["Ко кому́ воззову́, Влади́чице, ко кому́ прибі́гну в печа́лі моє́й? Ко кому́ принесу́ сле́зи і воздиха́нія моя́, а́ще не к Тебі́, Цари́це Небесе́ і землі́? Кто істо́ргнеть м'я от ти́ни гріхо́в і беззако́ній, а́ще не Ти, о Ма́ти Живота́, Засту́пнице і Прибі́жище ро́да челові́чеськаго? Усли́ши стена́ніє моє́, уті́ши м'я і поми́луй в го́ресті моє́й, защити́ в біда́х і напа́стіх, ізба́ви от озлобле́ній і скорбе́й, неду́гов і болі́зней і от враг ви́димих і неви́димих; умири́ вражду́ стужа́ющих мні, да ізба́влен бу́ду от клевети́ і зло́би челові́чеськія; та́кожде от своєя́ мі пло́ті гну́сних оби́чаєв свободи́ м'я. Укри́й м'я под сі́нію ми́лости Твоєя́, да обря́щу поко́й і ра́дость і от гріхо́в очище́ніє. Твоєму́ ма́тернему заступле́нію себі́ вруча́ю: бу́ди мні Ма́ти і наде́жда, покро́в і по́мощ, ра́дость і утіше́ніє і ско́рая во всем Помо́щниця. О чу́дная Влади́чице! Всяк, притека́яй к Тебі́, без Твоєя́ всеси́льния по́мощі не отхо́дить. Сего́ ра́ди і аз, недосто́йний, к Тебі́ прибіга́ю, да ізба́влен бу́ду от внеза́пния і лю́тия сме́рті, скре́жета зу́бнаго і ві́чнаго муче́нія, Небе́сноє же Ца́рствіє получи́ти сподо́блюся і Тебі́ во умиле́нії се́рдця реку́: Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, грі́шнії і смире́ннії, і припаде́м, в покая́нії зову́ще із глубини́ душі́: Влади́чице, помози́ на ни милосе́рдовавши, потщи́ся, погиба́єм от мно́жества прегріше́ній, не отврати́ Твоя́ раби́ тщи, Тя бо і єди́ну наде́жду і́мами."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Влади́чице, Ти нам помози́: на Тебі́ наді́ємся і Тобо́ю хва́лимся, Твої́ бо єсьми́ раби́, да не постиді́мся."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Геронтісса»","e":"Akathist to the Theotokos before her icon “Gerontissa”","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в Цари́це і Влади́чице, ро́да христия́нськаго при́сноє спасе́ніє от бід вся́чеських, по́моще на́ша і заступле́ніє, в напа́стіх і печа́ліх ди́вноє утіше́ніє, ли́ками чудотво́рних іко́н весь світ осіява́єши, ми же Тебі́ си́це воспіва́єм:","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Ікос 1","ps":["А́нгелов і Арха́нгелов преви́сшая, честні́йшая Херуви́м і Серафи́м сла́внійшая, я́ко Купина́ неопа́льно Бо́га прия́вшая, ро́ждшая ми́ру Спаси́теля, млеко́м Свої́м Младе́нця пита́вшая, матероде́вственною чистото́ю світ осіява́єши, ми́лости неоску́дния нам істоча́єши, Тебі́ кла́няємся, Тебі́ благодари́м, із глубини́ душі́ та́ко воспіва́єм:","Ра́дуйся, Благода́тноє Не́бо – із Тебе́ возсія́ Со́лнце Христо́с Бог наш.","Ра́дуйся, Вмісти́лище Ду́ха Свята́го.","Ра́дуйся, Ма́ти Ді́вственная.","Ра́дуйся, Цві́те Неув'яда́ємий Чистоти́.","Ра́дуйся, Ми́лующая грі́шников.","Ра́дуйся, Ціли́тельнице душ і тіле́с на́ших.","Ра́дуйся, Ми́лостивая засту́пнице всіх ка́ющихся.","Ра́дуйся, моли́тви те́плиє приє́млющая.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 2","ps":["Я́ко небосві́тлая звізда́, просія́ла єси́ іко́на твоя́ Богома́ти, в Афо́нстій оби́телі Пантокра́тор. Моля́ся пред не́ю бра́тія оби́телі іспроси́ла єси́ благослове́ніє у Пречи́стой, і ізбра́ла єси́ мі́сто оби́телі сей, і начала́ єси́ стро́іти ю. Іко́на же Ма́тері Бо́жієй трикра́ти ісходи́ла єси́ с мі́ста, ізбра́ннаго бра́тієй, в мі́сто і́но. І та́ко узрі́ бра́тія во́лю Твою́, Богоро́дице, би́ти оби́телі сей в мі́сті‚ ізбра́ннім Тобо́ю, Влади́чице, і ра́достно возопи́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Благода́ті струї́ от іко́ни іспуща́єши, мона́хов Покрови́тельнице, к по́двигу терпі́нія і смире́нія призива́єши, безмо́лвія Сопу́тнице, А́нгельськаго пі́нія Споспі́шнице, в моли́тві сле́зной неусипа́ющая Помо́щнице, оби́телі святі́й і всей землі́ Афо́нстій блага́я засту́пнице, бра́тії мона́шеськой Покро́ве і Путеводи́тельнице. Тебі́ благода́рними усти́ си́це воспіва́єм:","Ра́дуйся, Стіно́ і́ночеському чи́ну.","Ра́дуйся, Свече́ неугаса́ємая, мона́шеський путь освіща́ющая.","Ра́дуйся, моли́твеннице і спаси́тельнице душ ка́ющихся.","Ра́дуйся, ми́лостиво на мона́шеськия труди́ взира́ющая.","Ра́дуйся, сле́зи покая́нія приє́млющая.","Ра́дуйся, сокруше́нних серде́ць грі́шников утіше́ніє.","Ра́дуйся, в терпі́нії і смире́нії мона́шествующих укріпля́ющая.","Ра́дуйся, Ігу́менія свято́й гори́ Афо́нстій.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 3","ps":["Ста́рець ігу́мен на сме́ртном о́дре пребива́я, уві́дів ско́роє отше́ствіє своє́ от жи́зні сей, возжела́л єси́ Пречи́стих Христо́вих Та́їн вкуси́ти і напу́тіє к Жи́зні Ві́чній получи́ти, іспроси́ служа́щаго свяще́нника Та́їнство сіє́ соверши́ти. Но тще́тно ста́рець жа́ждал свято́й Трапе́зи, поне́же не внял свяще́нник проше́нію ста́рця. Тогда́ от свято́й іко́ни Бо́жієй Ма́тері в олтарі́ ізше́л гро́зний глас: «Іспо́лни проше́ніє ігу́мена, і не ме́дли!» І вшел єси́ свяще́нник к одру́ сме́ртному і дал єси́ напу́тіє Святи́ми Та́йнами ста́рцю-ігу́мену. І той, вкуси́в Їх, отше́л ми́рно ко Го́споду. Ми же, ра́дуяся попече́нію Бо́жієй Ма́тері о ста́рці почи́вшем, Го́спода сла́вим: Аллилу́я."]},{"h":"Ікос 3","ps":["Ста́рець-ігу́мен сподо́бился єси́ причасти́тися Святи́х Христо́вих Та́їн і отше́л єси́ в Жизнь Ві́чную – Небе́сною трапе́зою с небе́сними жи́телі ві́чно наслажда́тися, ви́дяще Бо́жию Ма́тер і всіх Святи́х і вся Небе́сния А́нгельськия ли́ки, при́сно воспіва́ющи Тро́йцю Єди́ную і Неразді́льную. І мно́гим ста́рцям і ста́рицям, стра́ждущим на одрі́ сме́ртнім, явля́ла ми́лость Свою́ Богоро́дице, к Си́ну Своєму́ ру́ці простира́ющи і моля́щи о призре́нії на нас, грі́шних і немощни́х. Та́ко і ми, моля́щи Пречи́стую Бо́жию Ма́тер о ми́лості і заступле́нії із глубини́ душі́ зове́м: «Ма́ти Бо́жия, помози́ і нам сподо́битися Прича́стія на сме́ртнім о́дре». І си́це Тебі́ воспіва́єм:","Ра́дуйся, ско́роє вспоможе́ніє подаю́щая.","Ра́дуйся, оста́вленних врача́ми в ру́ці Свої́ приє́млющая.","Ра́дуйся, милосе́рдная Уті́шительнице всіх скорб'я́щих і стра́ждущих.","Ра́дуйся, неду́ги і я́зви душе́вния врачу́ющая.","Ра́дуйся, Спору́чнице грі́шних к Си́ну Твоєму́.","Ра́дуйся, при́сная за нас Хода́тайце.","Ра́дуйся, Влади́чице, живо́т наш просвіща́ющая.","Ра́дуйся, Наде́ждо на́ше і спасе́ніє.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 4","ps":["Ма́тернії страда́нія претерпі́ла єси́ Богоро́дице, єгда́ ору́жіє про́йде се́рдце Твоє́, ви́дящи Си́на Твоєго́ ви́сяща на Кресті́ і стра́ждуща нас ра́ди грі́шних. Я́ко разбо́йник на Кресті́, мо́лим Го́спода: не лиши́ нас Свята́го Прича́стія і Ца́рствія Небе́снаго не затвори́. Тебі́, Ма́ти Бо́жия, про́сим: умоли́ Си́на Твоєго́ дарова́ти нам ми́лость сію́ і пре́жде конця́ покая́ніє. Со стра́хом Бо́жиїм і тре́петом Дар сей приє́млющи, Бо́гу воспої́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Глаго́леть Син Твой ви́дя милосе́рдіє Твоє́ к лю́дем: «Проси́, Ма́ти Моя́, зане́ не отвращу́ся от Тебе́, но іспо́лню вся проше́нія Твоя́». Я́ко на бра́ці в Ка́ні Галиле́йстій іспроси́ша у Си́на Твоєго́ по́мощі брачу́ющимся, і Син Твой сотвори́л чу́до претворе́нія води́ во вино́, та́ко і ни́ні про́сиши о нас, грі́шних. Го́споди, Си́не Бо́жий, в утіше́ніє стра́нствія на́шего земна́го, моли́твами Пречи́стия Твоєя́ Ма́тері, поми́луй нас, і сотвори́ чу́до претворе́нія душ на́ших в чисті́йшия сосу́ди, приє́млющия Ду́ха Свята́го. Ми же ра́дуяся попече́нію Ма́тері Твоєя́ Пречи́стой о нас, грі́шних і немощни́х, та́ко воспої́м:","Ра́дуйся, Обра́дованная, Госпо́дь с Тобо́ю.","Ра́дуйся, о ми́лості Си́на Твоєго́ нам, ко грі́шним, умоля́ющая.","Ра́дуйся, єди́на Наде́ждо, всіх отча́янних.","Ра́дуйся, Взиска́ніє нас, погиба́ющих во грісі́х.","Ра́дуйся, в ско́рбіх і печа́ліх Утіше́ніє.","Ра́дуйся, в неможе́нії на́шем нас утвержда́ющая.","Ра́дуйся, ра́дость неча́янную подаю́щая.","Ра́дуйся, Покро́в, промишле́ніє і защи́то на́ша.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х ви́ну іму́щая."]},{"h":"Кондак 5","ps":["Доко́лі на землі́ су́щи, не оти́дем в моли́тві от Тебе́, Богоро́дице. Не оста́ви нас, грі́шних, Свої́м попече́нієм. Я́ко к Ма́ти люби́мей, припаде́м ко о́бразу Твоєму́, і не іму́щи сил глаго́лати ра́дость свою́, про́сим Тя, Пречи́стую: «Не оставля́й нас, ми бу́дем Твої́ послу́шния ча́да». І ві́дущи ми́лости Си́на Твоєго́, всіх нас при Кресті́ Тебі́ всинови́вшаго, Бо́гу благода́рно вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Єгда́ глад ве́лій пости́г оби́тель Пантокра́тор, бра́тія нача́ша покида́ти ю. Ігу́мен же оби́телі сія́ сле́зно моля́щеся к неусипа́ємой Засту́пнице, Ігу́меніє гори́ Афо́нстій, призва́ бра́тію к моли́тві і упова́нію на Ма́тер Бо́жию. І не посрами́ла єси́ Ма́тер Бо́жия упова́нія і моли́тви: умно́жися єле́й в сосу́дах скуде́льних, дото́лі пусти́х, і, чрез край лія́ся, речи́цей істе́кл єси́ под две́рі, ізві́ствова о ми́лості Пречи́стой. Ми же дивля́хуся чу́ду сію́, ра́достно вопіє́м:","Ра́дуйся, ско́рая Усли́шательнице моли́тв на́ших.","Ра́дуйся, Ізба́вительнице от бід многоразли́чних.","Ра́дуйся, от гла́да тіле́снаго і духо́внаго ізбавля́ющая.","Ра́дуйся, істоча́ющая нам неоску́дния ми́лості.","Ра́дуйся, єле́єм ми́лости Твоєя́ нас утіша́ющая.","Ра́дуйся, многотеку́щая ріко́ Боже́ственной благода́ті.","Ра́дуйся, на́шу скве́рну чистото́ю Твоє́ю очища́ющая.","Ра́дуйся, ма́терніми щедро́тами нас посіща́ющая.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 6","ps":["Гла́да тіле́снаго ізбіга́я, духо́внаго гла́да ізбі́гнем ли? Помина́я слова́ Си́на Бо́жия: «А́лчущия і жа́ждущия пра́вди – ті́ї наси́тяться» і «Іму́щия ві́ру в Меня́ – і́муть живо́т ві́чний», ру́ці свої́ ко Го́споду простре́м. Я́ко разбо́йник на кресті́, сле́зно мо́лим Єго́ неотсту́пно: «Да́руй і нам Живо́т Ві́чний, дай нам іспи́ти Живо́й води́, теку́щей в Жизнь Ві́чную», і я́ко самаряни́ня, уві́дівши Тя, возопії́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Ми́лость Бо́жієй Ма́тері оби́тель спасла́ єси́ от гла́да – сосу́ди єле́єм запо́лнила єси́. Та́ко ми́лость Бо́жієй Ма́тері і нам, грі́шним, преізоби́льно ізлива́ється, і по́мощ Єя́ нам ско́ро бива́єть. Ми же о ми́лості той ві́дая, не престає́м проси́ть Цари́цю Небе́сную: єле́єм ми́лости Твоєя́ і нас уті́ши, освяти́, от скве́рни ізба́ви. Упова́ніє на Бо́жию Ма́тер іму́щи, та́ко воспої́м:","Ра́дуйся, Живоно́сний Істо́чниче, ду́ші заблу́дшия оживля́ющий.","Ра́дуйся, печа́лі і ско́рби в ра́дость претворя́ющая.","Ра́дуйся, то́нущих в мо́рі жите́йстім на брег Жи́зні Ві́чной ізвлача́ющая.","Ра́дуйся, Скоропослу́шнице, по́мощ отча́янним посила́ющая.","Ра́дуйся, млеко́м любві́ Боже́ственния нас напоя́ющая.","Ра́дуйся, Блага́я Врата́рнице, две́рі ра́йськія нам отверза́ющая.","Ра́дуйся, милосе́рдіє к па́дшим явля́ющая.","Ра́дуйся, Ма́тер щедро́т і утіше́нія.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 7","ps":["Милосе́рдіє Твоє́ на нас ізлива́ющая ви́ну, к Си́ну Твоєму́ ру́ці простира́єши, я́ко зане́ не отврати́ться от Тебе́, но іспо́лнить вся проше́нія Твоя́. Ми же, ра́дуяся заступле́нію Твоєму́, і обітова́нія Си́на Твоєго́ зна́ющи, Бо́гу воспіва́єм: Аллилу́я."]},{"h":"Ікос 7","ps":["Грі́шних ми́луєши, стра́ждущим по́мощ посила́єши, ху́лящих Тя і іко́ни Твоя́ стро́го наказу́єши. Сараци́на із ста́на вра́жия, проти́ву оби́телі стоя́вшаго і хотя́щаго де́рзостно оскверни́ти іко́ну Твою́, слепото́й наказа́ла єси́. Ми же ві́дущи сіє́, та́ко воспіва́єм:","Ра́дуйся, Ра́досте на́ша.","Ра́дуйся, Враго́в одолі́ніє.","Ра́дуйся, нечту́щих Тя посрамле́ніє.","Ра́дуйся, враго́в де́рзости разоря́ющая.","Ра́дуйся, нечести́вих наказу́ющая.","Ра́дуйся, ху́льников вразумля́ющая.","Ра́дуйся, при́сноє спасе́ніє оби́димим.","Ра́дуйся, купі́ль, в ней же вся ско́рбі на́ша погружа́ються.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 8","ps":["Споспі́шники сараци́на незря́щаго, ви́дяще таково́є наказа́ніє, устраши́лися єси́. Святи́й о́браз Бо́жієй Ма́тері вве́ргли в кла́дезь глубо́кий в скри́ша на дне єго́. І о́смдесят літ іко́на свята́я почива́ша в кла́дезі сем, сокри́тая от оче́с бра́тії, оба́че незри́мо храня́ще оби́тель сію́. Я́ко не можа́ше свіщу́ держа́ти под спу́дом, но то́кмо на сві́щниці, та́ко і іко́ни Бо́жієй Ма́тері не можа́ху би́ти сокри́ти от лю́б'ящих Єя́, но бива́ють явле́ни грі́шним і немощни́м во утіше́ніє. Ві́дая сіє́, ра́достно воспої́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Сліпи́й сараци́н сме́ртний час свой зря́ще, пока́ялся єси́ і сро́дником свої́м інове́рцям завіща́л єси́ Святи́й Афо́н посіти́ти, в кла́дезі о́браз Влади́чиці сиска́ти і бра́тії святи́ню верну́ти. Обріто́ша о́браз сокри́тий, бра́тія воздала́ єси́ благодаре́ніє Го́споду во воссла́вила єси́ Ма́тер Бо́жию песносло́віями і моле́ньми мно́гими. І по сей день ми́лости Бо́жієй Ма́тері на оби́тель сію́ ізоби́льно ізлива́ються, і ка́ко єле́й во дні гла́да – кувши́н преіспо́лнил єси́, та́ко і ми́лость Цари́ці Небе́сній ніколи́же не ісся́кнеть єси́. Ми же ра́дуяся, си́це воспої́м:","Ра́дуйся, ум'ягча́ющая зли́я се́рдця.","Ра́дуйся, ми́лостивоє проще́ніє ка́ющихся.","Ра́дуйся, єди́ная Наде́ждо отча́янних.","Ра́дуйся, язв душе́вних і тіле́сних врачева́ніє.","Ра́дуйся, не отверга́ющая всіх презрі́нних і отве́рженних.","Ра́дуйся, єле́єм ми́лости Твоєя́ на́ші гріхи́ омива́ющая.","Ра́дуйся, на стезю́ покая́нія прему́дре наставля́ющая.","Ра́дуйся, Ма́ти ві́чной Люби́ і Утіше́нія.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 9","ps":["Благода́рственноє пі́ніє прино́сим Ті, Богоро́дице, о явле́нії чу́дния Твоєя́ іко́ни, я́ко рекла́ єси́ первонапи́санній іко́ні Своє́й: «с тобо́ю моя́ благода́ть і си́ла». Упова́єм та́кожде і с се́ю іко́ною Твоє́ю благода́ть ви́ну. Лобиза́єм іко́ну Твою́, поклоня́ємся єй, я́ко Тебі́ самі́й су́щей. От іко́ни Твоєя́ зна́менія і чудеса́ содіва́ються всім с ві́рою притека́ющим к Тебі́ і к Бо́гу вопію́щим: Аллилу́я."]},{"h":"Ікос 9","ps":["Із Афо́нстій оби́телі іко́на свята́я сія́ во мно́гія гра́ди і ве́сі гре́чеськия яви́лась єси́, то́ки чуде́сной по́мощі ізоби́льно ізлива́ющи: боля́щия ісціля́хуся, безча́дния ча́да обріта́ху в моли́тві пред іко́ной сей, рожда́ющим Помо́щницей в ро́дах яви́лась єси́, тружда́ющимся і уча́щимся по́мощ посила́ла єси́. Ми же о ми́лостіх Бо́жия Ма́тері ві́дая, благода́рними усти́ воспіва́єм:","Ра́дуйся, Ра́досте на́ша, в труда́х і уче́нії по́мощ посила́ющая.","Ра́дуйся, Всецари́це, неду́ги тя́жкия ісціля́ющая.","Ра́дуйся, в ско́рбіх утоле́ніє печа́лей.","Ра́дуйся, нося́щим во чре́ві і родя́щим єди́ная по́моще.","Ра́дуйся, уча́щимся і всім нам прибавле́ніє ума́ да́рующая.","Ра́дуйся, безча́дних по моли́тві рожде́нієм чад благословля́ющая.","Ра́дуйся, ско́рбних ма́терей утіше́ніє.","Ра́дуйся, лю́б'ящим Тя Стіно́ і огражде́ніє.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 10","ps":["Ро́ждшая ми́ру Спаси́теля, Си́на Бо́жия, Роди́тельниця Ві́чнаго Царя́, на руку́ Своє́ю Христа́ Младе́нця носи́ла єси́, Світи́льником, озаря́ющим путь спасе́нія, яви́лась єси́. Не́бо і вся земля́ сла́в'ять Тя, Богоро́дице. Ми же, припа́дающе к о́бразу твоєму́, Си́на твоєго́ і Го́спода восхваля́єм і с тре́петом вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Ра́дость всему́ ми́ру родила́ єси́ Ді́во неіскусобра́чная, Невмісти́маго вмісти́вшая. Блаже́нно чре́во Твоє́, Бо́га носи́вшеє. І ни́ні іму́щая дерзнове́ніє ко Го́споду, присномоля́щая Си́на Твоєго́, умилосе́рдися на лю́ди грі́шния і безпомо́щния, не оста́ви нас, Боже́ственний покро́в душа́м на́шим. Ми же припа́даєм ко о́бразу Твоєму́, поклоня́ємся Тебі́, Богоро́дице, і си́це воспіва́єм:","Ра́дуйся, ми́лостивая пред Бо́гом Предста́тельнице.","Ра́дуйся, Отра́до і Утіше́ніє.","Ра́дуйся, скорб'я́щих Ра́досте.","Ра́дуйся, благода́тним єле́єм ми́лости Твоєя́ нас, грі́шних, от скве́рни ізбавля́ющая.","Ра́дуйся, преблагослове́нная Влади́чице Не́ба і землі́.","Ра́дуйся, єле́єм ми́лости Твоєя́ нас, грі́шних освяща́ющая.","Ра́дуйся, коєму́ждо по вся́кой потре́бі прося́щим поле́зная да́рующая.","Ра́дуйся, сує́тниє ра́дости ми́ра сего́ презира́ти нас науча́ющая.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х ви́ну іму́щая."]},{"h":"Кондак 11","ps":["Єгда́ ста́рцю-ігу́мену оби́телі Пантокра́тор на одрі́ сме́ртнім причасти́тися Святи́х Та́їн помогла́ єси́, стро́го вразуми́в свяще́нника, о́браз твой наре́клся єси́ «Геронти́сса», покрови́тельнице ста́рчества. І мно́гая по́мощ ста́рцям оби́телі умира́ющим Тобо́ю, я́ко єле́й ми́лости, істоча́лась єси́. Та́кожде і всім ста́рцям і ста́рицям, об ісхо́ді із жи́зні сей помищля́ющим, мно́гажди помога́ла єси́. Дивля́хуся ско́рой по́мощі сей, с упова́нієм на ми́лость Бо́жию вопіє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Єди́ная Наде́ждо всіх отча́янних, си́рих і немощни́х попече́ніє, жен похвало́, дів велича́ніє, вдов заступле́ніє, ни́щим пита́тельнице, наги́х одія́ніє, скорб'я́щих Отра́до і увеселе́ніє, ма́терніми щедро́тами согріва́ющая, не́мощ на́шу посіти́. Ми же умиле́нним се́рдцем си́це воспої́м:","Ра́дуйся, ста́рцев Утіше́ніє.","Ра́дуйся, отра́до в день сме́рті.","Ра́дуйся, єди́ная Наде́ждо по сме́рті.","Ра́дуйся, болі́зней врачевство́ ско́роє і безме́здноє.","Ра́дуйся, от гла́да і напра́сния сме́рті ізбавля́ющая.","Ра́дуйся, престарі́лих роди́телей дітьми́ свої́ми оста́вленних под свой честни́й покро́в приє́млющая.","Ра́дуйся, жесто́ких чад, небрегу́щих о ста́рціх свої́х гро́зно вразумля́ющая.","Ра́дуйся, милосе́рдная всіх Ма́ти.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 12","ps":["Каки́ми пі́сньми і похвали́ просла́вим Тя, Богоро́дице? Кі́ї благодаре́нія принесе́м Ті, грі́шнії? Ти єси́ Стіно́ Неруши́мая ро́ду христия́нському. Ти Огра́до і Покро́ве ді́вства і чистоти́. Ти скоропомо́щная усли́шательнице нас, грі́шних і немощни́х, Засту́пнице на́ша пред Сино́м Твої́м, наде́ждо і защище́ніє на Стра́шнім Суді́ Си́на Твоєго́. Ти неоскудіва́ємий сосу́де ми́лості і милосе́рдія істо́чниче. О Тебі́ ра́дується весь челові́чеський род. І ми, почита́я Тя, благодари́м Си́на Твоєго́, да́вшаго нам наде́жду на спасе́ніє. І Тебі́, Одиги́трії ро́да челові́чеськаго, при́сно воспіва́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Я́ко Крин Небе́сний среди́ те́рній гріхо́в челові́чеських процвіла́ єси́ Богоотрокови́це на землі́. Бо́гом Отце́м ізбра́нная, Ду́хом Святи́м осіне́нная, Си́на Бо́жия, Спаси́теля ми́ру ро́ждшая, вінце́м Небе́сним Тро́йцею Святі́й увінча́нная. До Рождества́, в Рождестві́ і по Рождестві́ Присноді́вою велича́ємая. Ти благоуха́єши вся́кою чистото́ю, із Тебе́ проісше́л Госпо́дь. Тебі́, Чи́стую, сла́вим і уми́льно та́ко воспої́м:","Ра́дуйся, чисті́йший о́браз цілому́дрія.","Ра́дуйся, на́шу скве́рну Твоє́ю чистото́ю очища́ющая.","Ра́дуйся, чистоти́ і цілому́дрія ревни́тельнице.","Ра́дуйся, благоуха́нний Цві́те, світя́щийся благоуха́нієм чистоти́.","Ра́дуйся, Цві́те Неув'яда́ємий присноде́вственний.","Ра́дуйся, Боже́ственний Покро́в душа́м на́шим.","Ра́дуйся, спаси́тельний єле́й, умаща́ющий гріхо́вния ра́ни ка́ющихся.","Ра́дуйся, Ма́ти Бо́жия, Не́бо і вся земля́ сла́в'ять Тя.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 13","ps":["О, Ма́ти Ді́во чи́стая, усли́ши глас моле́нія нас грі́шних і немощни́х. Ви́шняя сочета́вшая с ни́зшими, ро́ждшая нам Спа́са, Си́на Твоєго́, воспіва́єм твою́ ма́тернюю любо́в, преклоня́ємся пред Твоє́ю чудотво́рною іко́ною. Ти єси́ луча́ми чуде́с нас просвіща́єши, гріхо́в оставле́ніє нам да́руєши і ра́дости ісціле́нія сподобля́єши. О, Преблагослове́нная, Ти єси́ сліпи́х прозрі́ніє, грі́шников благода́тная наста́внице. Ти єси́ Ма́ти цілому́дрія, Ти єси́ ба́не, омива́ющая со́вість. Кто, кромі́ Тебе́, сле́зи на́ші осуши́ть, ско́рби серде́чниє ути́шить, вся́ких бід ізба́вить і утіше́ніє да́руєть? Ка́мо гряде́м? То́кмо к Тебі́, Пречи́стая Ді́во Ма́ти. Благослове́н плод чре́ва Твоєго́. Ти єси́ Ра́дость всему́ ми́ру ро́ждшая, іму́щая дерзнове́ніє ко Го́споду, прийми́ ма́лоє моле́ніє на́ше, умилосе́рдися на лю́ди безпомо́щния. Ми же, припа́дая к Твоє́й цільбоно́сній іко́ні, Го́спода сла́вим і так вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і Арха́нгелов преви́сшая, честні́йшая Херуви́м і Серафи́м сла́внійшая, я́ко Купина́ неопа́льно Бо́га прия́вшая, ро́ждшая ми́ру Спаси́теля, млеко́м Свої́м Младе́нця пита́вшая, матероде́вственною чистото́ю світ осіява́єши, ми́лости неоску́дния нам істоча́єши, Тебі́ кла́няємся, Тебі́ благодари́м, із глубини́ душі́ та́ко воспіва́єм:","Ра́дуйся, Благода́тноє Не́бо – із Тебе́ возсія́ Со́лнце Христо́с Бог наш.","Ра́дуйся, Вмісти́лище Ду́ха Свята́го.","Ра́дуйся, Ма́ти Ді́вственная.","Ра́дуйся, Цві́те Неув'яда́ємий Чистоти́.","Ра́дуйся, Ми́лующая грі́шников.","Ра́дуйся, Ціли́тельнице душ і тіле́с на́ших.","Ра́дуйся, Ми́лостивая засту́пнице всіх ка́ющихся.","Ра́дуйся, моли́тви те́плиє приє́млющая.","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в Цари́це і Влади́чице, ро́да христия́нськаго при́сноє спасе́ніє от бід вся́чеських, по́моще на́ша і заступле́ніє, в напа́стіх і печа́ліх ди́вноє утіше́ніє, ли́ками чудотво́рних іко́н весь світ осіява́єши, ми же Тебі́ си́це воспіва́єм:","Ра́дуйся, Пречи́стая, попече́ніє о нас, грі́шних і немощни́х, ви́ну іму́щая."]},{"h":"Молитва","ps":["О Всепі́тая Ма́ти, ра́досте на́ша і утіше́ніє, в ско́рбіх ско́рая помо́щнице, в біда́х і отча́янії єди́ная Наде́ждо. Ми́лости Свої́, я́ко єле́й благода́тний, ізоби́льно на нас ізлива́єши, к Си́ну Своєму́ і Бо́гу на́шему неуси́пно о нас мо́лишися, при́зри на смире́ніє рабо́в Твої́х. Єгда́ преклони́ться к ве́черу день жи́зні на́шея, в час сме́ртний, усли́ши нас, умоли́ Си́на Твоєго́ дарова́ти нам Свято́є Прича́стіє і напу́тіє в Жизнь Ві́чную. Помози́ ізбі́гнути го́рких мита́рств і му́ки сме́ртния утиши́, не оставля́я нас, чад Твої́х, при Кресті́ Си́на Твоєго́ Тебі́ всиновле́нних, да́руй твої́ми моли́твами наде́жду і спасе́ніє. Не оставля́й нас, си́рих і немощни́х. Преклоня́ємся пред Пречи́стим о́бразом Твої́м, зна́юще обітова́ніє Твоє́ «Не прийдо́х храни́ма би́ти от вас, но да бу́ду Аз Храни́тельниця ва́ша в настоя́щем ві́ці і бу́дущем». Та́ко і нас сохрани́ от бід і напа́стей, боля́щия ісціли́, скорб'я́щия уті́ши, заблу́дшия вразуми́, охрани́ младе́нці, нося́щим во чре́ві помози́ благополу́чно разріши́тися от бре́мені, ю́них воспита́й і научи́, супру́гов наста́ви, поддержи́ і согрі́й ста́рия, жесто́ких чад, небрегу́щих о ста́рціх свої́х, гро́зно вразуми́. На Тебі́ наді́ємся, Тобо́ю хва́лимся, на Тя упова́єм і прекло́ньше колі́на душ на́ших при́сно прославля́єм Отця́, Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко пресві́тлая звізда́, / просія́ Боже́ственними чудеси́ / святи́й о́браз Твой, Ізба́вительнице, / луча́ми благода́ті і милосе́рдія Твоєго́ / озари́во в но́щі скорбе́й су́щих. / Пода́ждь у́бо і нам, Всеблага́я Ді́во, / ізбавле́ніє от бід, / ісціле́ніє неду́гов душе́вних і тіле́сних, / спасе́ніє і ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Ко іко́ні Твоє́й, Пресвята́я Госпоже́, бі́дствоваше с ві́рою прите́кше, заступле́нієм Твої́м ізба́вишася от злих, но я́ко Ма́тер Христа́ Бо́га і нас свободи́ от лю́тих обстоя́ній, вре́менних і ві́чних, да зове́м Ті: ра́дуйся Ізба́вительнице на́ша от всіх бід."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Корсунська»","e":"Akathist to the Theotokos before her icon “Korsun”","secs":[{"h":"Кондак 1","ps":["Возбра́нная от рождества́ Своєго́ Ді́во і по тихом успе́нії Своє́м в небе́сная вознесе́нная пресла́вно, служи́тельнице ізбавле́нія ми́ра смиреннейшая, в се́рдці своє́м о лю́діх печа́ль імеющая, близькая други́ня і уті́шительнице всіх оби́димих, тружда́ющихся і обремене́нним опоро неруши́мая, — Тебі́ ни́ні хвале́бная пі́нія по си́лі прино́сим, поне́же яви́ла єси́ от о́браза Своєго́ ми́лости преди́вния людям ізборським, да взива́єм Тебі́ немо́лчно:","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Ікос 1","ps":["А́нгельстії собо́ри, воплоще́нія та́йні чудя́щеся і Вседержи́телю о Ней немолчниє хвали́ всегда́ принося́ще, велича́нія прино́сять і Ді́ві ізбра́нній, Богома́тері Пречи́стій, із Нея́ же на спасе́ніє всім Бог воплоти́ся; сего́ ра́ди, небожителем подража́я, да подви́жеться всяк земноро́дний і, іспо́лнь ду́ха ра́дованія, да почита́єть он сві́тло свяще́нноє торжество́ Ді́ви і Ма́тере, взива́я Єй та́ко:","Ра́дуйся, жи́зні нестарі́ющей весно́ благоуха́нная.","Ра́дуйся, луча́ вознесенного цвіт красні́йшій.","Ра́дуйся, я́ко от Тебе́ всего́ ми́ра обновле́ніє ізи́де.","Ра́дуйся, гріхи́ і скве́рни всего́ ми́ра омива́ющая.","Ра́дуйся, таїнственного дне жи́зні блаже́нной заря́ пресві́тлая.","Ра́дуйся, всім, совершающим путь спасе́нія, неви́димая сопутнице.","Ра́дуйся, душ чи́стих ни́во небе́сная.","Ра́дуйся, па́житей духо́вних росо́ плодоно́сная.","Ра́дуйся, Тебі́ бо земля́ да́рствуєть цві́ти преди́внії.","Ра́дуйся, Тебі́ бо днесь тщі́мся прино́сіте пі́сні ізбранниє.","Ра́дуйся, благода́ть моли́тви, я́ко диха́ніє то́нкоє, в душа́х возгревающая.","Ра́дуйся, Светоче моле́нія на́шего ти́хий.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 2","ps":["Безгла́сен бисть ні́когда ієре́й Заха́рія, єгда́ усумні́ся глаголанному от а́нгела, я́ко, стар сий, проро́ка великого оте́ць бу́деть, і нем бі, до́ндеже сби́сться рече́нноє а́нгелом. Та́кожде і ми, безмолвнії би́вши зрі́нієм чудесного зна́менія от о́браза Пречи́стия Богома́тере, ни́ні дерзнове́нно отверза́єм уста́ своя́ творя́щему нам ми́лости вели́кия, вопія́ єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Вість приє́мше лю́діє Ізборстії, я́ко уби́йством і пожа́ром ідя́ху, іноплеменнії і уже́ пожго́ша посад Печерстій, стра́хом одержи́ми би́ша. Іщущим же їм спасе́нія у до́ма святи́теля Никола́я, с ви́шніх призрі́ на обурева́ємих напа́стьми Пречи́стая і от о́браза Своєго́, є́же бисть у вдови́ Євдокі́ї, яви́ зна́меніє сострада́нія горю людсько́му, ізлія́ сле́зи. Тогда́, ра́дости іспо́лнені, лю́ди ізборстії умиле́нно взива́ху Богоро́дице:","Ра́дуйся, внеза́пу ми́лость лю́дем Твої́м от о́браза Твоєго́ я́вльшая.","Ра́дуйся, го́рестей на́шим сле́зи свої́ми для всіх зри́мо сострадавша.","Ра́дуйся, Твоя́ бо любо́в на нас, а́ки дождь, ниспадаєть.","Ра́дуйся, я́ко Ти под'ємлеши на Себі́ яре́м спасе́нія на́шего.","Ра́дуйся, всему́ ми́ру врачевство́ духо́вноє.","Ра́дуйся, вся́кому ді́лу благо́му пособнице усе́рдная.","Ра́дуйся, ізима́ющая от сіте́й кори́сти і буєсло́вія.","Ра́дуйся, дово́льство житіє́м ти́хим в душа́х укріпля́ющая.","Ра́дуйся, держа́вная засту́пнице всего́ ми́ра християнського.","Ра́дуйся, град наш соблюда́ющая от обдержа́нія вра́жия.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 3","ps":["Гавриї́л Благові́стник странниє глаго́ли рече́ Ді́ві Марі́ї, я́ко смути́тися Єй зіло́, поне́же благовісти́ Єй рожде́ніє Си́на без му́жа. Покорна же бі во́лі Бо́жієй ізбра́нная раба́ Госпо́дня, смире́ніє вели́коє показа́, вдах Себі́ всю в ру́ці Бо́жії, да научи́ть і нас, приосененних Богома́тернім заступле́нієм, возглаша́ти неуста́нно Ви́шнему, путі́ на́ші ди́вно устроящему: Аллилу́я."]},{"h":"Ікос 3","ps":["Досто́їть муже́м найпа́че охрану домо́в і ве́сей імі́ти, зане́ си́лою і крі́постію облада́ють. Сего́ ра́ди і возста́ша, я́коже єди́н, всі му́жіє ізборстії, внегда́ услишаху бряцяніє бра́нем і ше́ствіє лютого врага́, разоряющего до́ми, — і єгда́ помишля́ху, ка́ко врагу́ противоста́ти і огражде́ніє ві́си своєя́ сотвори́ти, внеза́пу Жена́ вели́кая при́йде і зна́меніє от о́браза своєго́ яви́, да покро́ву Богома́тере ра́дующеся, вознесу́ть єй всі му́жіє велича́нія такова́я:","Ра́дуйся, опоро люде́й Твої́х неруши́мая.","Ра́дуйся, всім ослабевающим укріпле́ніє тве́рдоє.","Ра́дуйся, мо́ря жите́йського ко́рмчий ві́рний.","Ра́дуйся, всім обурева́ємим оти́шія при́стань.","Ра́дуйся, бу́рю страсте́й гріхо́вних умиряющая.","Ра́дуйся, от дія́ній бесчестних і злих удерживающая.","Ра́дуйся, на землі́ в по́ті трудящимся бодреніє і си́ло.","Ра́дуйся, ді́лателю нелицемі́рному отдохновеніє і отра́до.","Ра́дуйся, гру́бость серде́ць людськи́х ум'ягча́ющая.","Ра́дуйся, под'ємлющая їх от землі́ на не́бо.","Ра́дуйся, забве́ніє несу́щая діл су́єтних і ло́жних.","Ра́дуйся, си́ли подаю́щая к отвраще́нію от путе́й лука́вствія.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 4","ps":["Єще́ в земні́м житії́ Своє́м, смире́нієм вели́ким богаті́я, преіспо́лнена бисть труда́ і забот обрученная ста́рцю Ді́ва-Ма́ти, о до́мі і о Си́ні Своє́м возлю́бленнім попече́ніє всегда́ імі́я. І по днесь, єгда́ кре́стною сме́ртію увінча́ мир дія́нія Іскупи́теля не забива́єть Богома́ти, уже́ в сла́ві небе́сній пребива́я, грешного ми́ра люде́й си́рих і обремене́нних, не преставая о них перед Сино́м моле́нія твори́ти да вопію́ть спасаємиє Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Жизнь дарствуя лю́дем і ра́достную ю творя́ще, в земні́м служе́нії Своє́м ні́когда при́зван бисть Ісу́с со ученики́ Свої́ми на брак в Ка́ну Галиле́йськую, да благослови́ть люде́й прости́х і бі́дних. Недоста́вшу же вина́ пирующим, болі́знова Ма́ти Пречи́стая, зане́ любля́ше люде́й і ра́дости їх любля́ше, і приступи́ к Си́ну і проси́ зна́меніє сотвори́ти Любо́ві Ма́терней помоществу́я, претвори́ Ісу́с во́ду во вино́, нача́ток зна́менієм Свої́м полага́я. Ми же, сіє́ на па́м'ять приводя́, Богоматернєє сорадованіє нам всегда́ велича́юще, да вопіє́м Єй та́ко:","Ра́дуйся, із со́нма жен ізбра́нная чу́дно.","Ра́дуйся, любве́ вели́кия сві́те, го́ре вознесе́нний.","Ра́дуйся, Бо́га родшая на спасе́ніє на́ше.","Ра́дуйся, всеми́рноє ізбавле́ніє Собо́ю наченшая.","Ра́дуйся, Сі́ятеля чистоти́ в ми́рі Єдиного Ма́ти.","Ра́дуйся, дарова́нії духо́вними сві́тло озаре́нная.","Ра́дуйся, Же́но єди́ная, болі́зней чадорожденія не позна́вшая.","Ра́дуйся, вмісти́лищем Невместимого соделавшаяся.","Ра́дуйся, Собо́ю вся наполняющего Ма́ти.","Ра́дуйся, мир і согла́сіє семи наблюдающая.","Ра́дуйся, напрасни творя́щая ухищре́нія люде́й противумирних і же́стоких.","Ра́дуйся, в Себі́ сочета́вшая жи́зні терпі́ніє і Бо́гу служе́ніє.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 5","ps":["Зіло́ расширила єси́ покро́во всеобдержния ми́лости Твоєя́ Богоро́дице, і, бив цві́том ізбра́нним всіх жен, сія́ющим доброді́тельми многоразли́чними, показа́ ми́ру чу́до, і небожителем стра́нноє: земна́я би́вши к Царю́ небе́с приблизилася єси́ ті́сно, людські́я страда́нія і сле́зи к престо́лу Ви́шняго принесла́ єси́ охо́тно і та́ко дала́ єси́ лю́дем си́лу к Отцю́ всіх взива́ти хвале́бно: Аллилу́я."]},{"h":"Ікос 5","ps":["Земна́я зло́ба неістовствова, і ору́жіє про́йде Твоє́ се́рдце, Богома́ти, єгда́ узрі́ла єси́ Си́на на Кресті́ ра́сп'ята. Муче́нії го́ркими одержи́ма бисть душа́ Твоя́, і ве́лій плач принесла́ єси́, глаго́люще: «стра́нним і ди́вним Рождество́м Твої́м, Си́не Мой, возвели́чена бисть пред всі́ми матерями; но го́ре Мні, утро́ба Моя́ раздира́ється, єгда́ ви́жу Тя на Дре́ві». Сі́ї страда́нія безмі́рними да укріп'я́ться всі ма́тері і да принесу́ть ни́ні Бо́жієй Ма́тері славосло́вія сицева́я:","Ра́дуйся, се́рдця матернего, страда́нії Си́на, я́ко мече́м пронзенного досто́йний о́браз подража́нія.","Ра́дуйся, ма́терем го́рестним і душе́ю ізраненним наде́жноє укріпле́ніє.","Ра́дуйся, Ма́ти всю жизнь содержащего.","Ра́дуйся, ско́рбний путь матери́нства го́рці уведевшая.","Ра́дуйся, муки́ чадорожденія утишающая.","Ра́дуйся, ма́терей печа́ль безисходную веянієм любві́ рассеєвающая.","Ра́дуйся, роди́ бо всі Тебі́ при́сно чудя́ться.","Ра́дуйся, я́ко па́че го́рніх сил превоснеслася, ро́ждши неприступного Бо́га.","Ра́дуйся, рожде́нієм із Себе́ Си́на предві́чнаго чадоро́діє благослови́вшая.","Ра́дуйся, многочадним матерям си́ли неслишно подаю́щая.","Ра́дуйся, сле́зи ма́терей благода́тно осушающая.","Ра́дуйся, по́двиг жи́зні їх до́брий сві́том утіше́нія озаря́ющая.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 6","ps":["Із бе́здни адовой всі си́ли тьми возликоваша, єгда́ на Голго́фі ве́черу заходя́щу єдинственного дне, на Кресті́ распинаємоє Сло́во жи́зні в человечестнем єстестві́ своє́м прибли́зися к сме́рті. Тогда́ ско́рби неісцельниє іспо́лнися се́рдце Богома́тере, зря́ще страда́нія Божественного Си́на; любо́вію же ма́тернею ко Кресту́ припадала єсть ку́пно со ученико́м возлю́бленним Си́на Своєго́, ча́юще утіше́нія болі́знующей душе́ Своє́й, до́ндеже не усли́шала єсть со Креста́ словесе́ Синовнего утіше́нія і не воззвала́ со ученико́м сло́ва Всемогу́щему: Аллилу́я."]},{"h":"Ікос 6","ps":["Ієрусали́м свої́ми во́льними страда́нії освяти́л єсть Цар ца́рствующих, і при вхожде́нії в онь, єгда́ гряде на страсть, ликова́нія діте́й прия́л єсть Син Твой, Богома́ти, я́коже і пре́жде сего́ любо́вно благослови́ їх, ре́кши: «а́ще не бу́дете я́ко ді́ти, не вни́діте в Ца́рство Небе́сноє»: тім же, любо́ві Си́на к ді́тем соревну́я, понине явля́єшися, Богоро́дице, опорою ді́тем чи́стим і кро́тким, немощни́м і убо́гим, си́рим і оста́вленним, да вопію́ть они́ детськими усти́ вели́кия Тебі́ хвале́нія:","Ра́дуйся, ді́тем непоро́чним ра́дость Собо́ю низводящая.","Ра́дуйся, повсю́ду храня́щая їх от бід і скорбе́й.","Ра́дуйся, ра́зум діте́й к позна́нію Бо́га і жи́зні руководящая.","Ра́дуйся, путі́ стро́потни к ше́ствію младе́нцев ісправля́ющая.","Ра́дуйся, раю́ детскиє сла́дости.","Ра́дуйся, сокро́вище жи́зні неоскудіва́ємоє.","Ра́дуйся, із уст младе́нцев моле́нія нехитростная приє́млющая.","Ра́дуйся, вся́ко благо́є от Бо́га дая́ніє їм посила́ющая.","Ра́дуйся, обраща́ющая се́рдця к роди́телям.","Ра́дуйся, умиряющая надме́ніє ю́них.","Ра́дуйся, от си́ли в си́лу возводя́щая.","Ра́дуйся, красоту́ і прему́дрость Бо́жия ми́ра ді́тем указу́ющая.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 7","ps":["Конце́во всея́ земле́ лю́діє, із ві́ка во вік прино́сять превели́кая і немо́лчная хвале́нія Тебі́, Богоізбра́нная Ді́во, зане́ не то́кмо сла́ву приє́млеши, но і єди́на імі́єши от Ви́шняго ісполня́ти вся́коє благо́є люде́й проше́ніє, чего́ ра́ди і числа́ не і́муть явленниє і цельбоносниє Твоя́ іко́ни, я́вно зримия зна́менія любве́ Твоєя́, всепомоществующей всім ві́рующим взивающим Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Любве́ престарі́лих роди́телей плод красні́йшій, вручена́ бисть ста́рцю Іо́сифу Марі́я, да сбу́деться вся, рече́нная проро́ки. Послушива бисть старейшим во всем, Ді́ва благоуві́тлива яви́ся їм, я́ко жезл ста́рости до́брий. Та́кожде і до сего́ дне всі ста́рці і ста́риці, тече́ніє жи́зні в труді́х і по́двизіх соверша́юще, неду́зі тіле́сниє і душевниє мо́щно превозмогають, подкріпля́ємі Твої́м Присноді́во, явле́нієм і по́мощію, чесо́ ра́ди і ни́ні, притека́юще к Тебі́, сія́ющему сві́ту заходящия жи́зні, благода́рственно глаголять та́ко:","Ра́дуйся, престарі́лих роди́телей ра́дость неізрече́нная.","Ра́дуйся, ста́рость їх благоче́стієм украси́вшая.","Ра́дуйся, ста́рости угасающая Сві́те ти́хий.","Ра́дуйся, сокро́вище жи́зні неістощи́моє.","Ра́дуйся, жизнь наполняющая дія́ньми святи́ми.","Ра́дуйся, му́дрость даю́щая, не в числі́ літ ісчисляєму.","Ра́дуйся, отверза́ющая врата́ Ієрусали́ма вечного, іді́же скончава́ється люде́й стра́нствіє.","Ра́дуйся, Прия́телище всего́ ми́ра прему́дрости несозданной.","Ра́дуйся, в ма́лом удержавающая, да не сотвори́м гріхо́в бо́льших.","Ра́дуйся, руководящая к упова́нію єди́ному жи́зні всея́.","Ра́дуйся, до́брі пожившим ми́рную кончи́ну уготовля́ющая.","Ра́дуйся, расширяющая дом душі́ на́шея для вхожде́нія Госпо́дня.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 8","ps":["Марі́я — друга́я, сі́дши ні́когда при но́гу Ісу́сову, слушала сло́во Божественного уче́нія і пита́ющая ду́шу благода́ті, я́ко заби́ти єй вся земна́я і вре́менная і, Боже́ственному Учи́телю послі́дующе, воспарити ду́хом в небе́сная і ві́чная, іді́же жизнь соверше́нная і ду́си в Госпо́днем поко́ї пребива́ють. Та́ко і Цари́ця Небе́сная, всегда́ предстоя́ престо́лу Бо́га і Си́на, любо́вію под'єм літ нас ко Вседержи́телю і ца́рствію Єго́ да возноси́м Єму́ при́сно: Аллилу́я."]},{"h":"Ікос 8","ps":["Недоумі́єть ум і бессилен бива́єть єгда́ тщи́ться уразумі́ти вселе́нськоє чу́до явле́нія в мир Богома́тере, зане́ преви́ше плотянаго ума́ сочета́ніє в єди́ній ді́вства Ма́тере і діторожде́нія Ді́ви. І ни́ні се́рдцем чи́стії і кро́тції, осіянниє смире́нія благода́тію, да предста́нуть о́бразу Цари́ці душ ді́вственних і, от Нея́ приявшії си́лу і бо́дрость на по́двиг жи́зні своєя́, да славосло́в'ять Ю си́це:","Ра́дуйся, сві́том цілому́дрія осія́нная.","Ра́дуйся, ді́вство вмісти́лищем Бо́га воплоти́вшася соді́лавшая.","Ра́дуйся, чудесе́ ве́лія і єдиного: Ді́ви рождающей без му́жа явле́ніє.","Ра́дуйся, ми́ра чуждого і хладного Засту́пнице те́плая.","Ра́дуйся, моле́нія за люде́й свіща́ неугаси́мая.","Ра́дуйся, стіно́, крі́пкая всім, по́двигом ді́вства подвизающимся.","Ра́дуйся, Неві́сто-красительнице душ ді́вственних і святи́х.","Ра́дуйся, та́йну промишле́нія Бо́жия о лю́діх я́вльшая.","Ра́дуйся, дости́гшая конця́ челові́чеських вожделі́ній.","Ра́дуйся, обоже́нію єстества́ человечеського ді́вством Свої́м послужи́вшая.","Ра́дуйся, Бо́га нисшедшего к лю́дем оби́тель свята́я.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 9","ps":["О́браз матернего служе́нія великого, благослови́ла єси́ жен чадоро́діє, Си́на Бо́жия су́щи Ма́ти єди́ная, да на Тебі́ взира́юще, си́лу воспри́ймуть всі немощству́ющії жени́ і сиротствующиє ді́ви, їх же і в Небе́сних оби́теліх не забива́єши при́сно, я́ко і сподо́битися їм пе́рвим свиді́тельници би́ти во Ізборскі явле́нія от о́браза Твоєго́ і о сем возноси́ти Го́споду немо́лчно: Аллилу́я."]},{"h":"Ікос 9","ps":["Пречи́стия Богоро́диці о́бразу явле́нному зіло́ возра́довахуся лю́діє ізборстії, ріка́ бо яви́ся неоскудеваємая заступле́ній Владичних. Ра́дости же люде́й ізборських поревнова́в, повелі́ Псковський архієре́й Мака́рій ізнести́ Корсунськую іко́ну Бо́жия Ма́тере во град Псков, і ту дві седьми́ці приє́м Пречи́стая поклоне́ніє Своєму́ о́бразу, єгда́ всі псковичі, припа́дающе благоче́стно взива́ху си́це:","Ра́дуйся, дре́вній град Ізборск зна́менієм от іко́ни Твоєя́ возвели́чившая.","Ра́дуйся, Бо́жиє благоволе́ніє к лю́дем низведшая.","Ра́дуйся, люде́й ізборських де́рзостная похвало́.","Ра́дуйся, Тебі́ благочести́во сретшим поми́лованіє уготовля́ющая.","Ра́дуйся, ізше́дшая от Ізборська во Псков на ми́лость і заступле́ніє.","Ра́дуйся, во Пско́ві двою́ седьми́цею поклоне́ніє о́бразу Твоєму́ приє́мшая.","Ра́дуйся, всея́ землі́ пско́вськия щит і ору́жіє.","Ра́дуйся, о всіх і за вся блага́я побо́рнице ско́рая.","Ра́дуйся, благода́ті бо Твоє́й осіня́ємій, стра́хом ісчеза́ють темниє си́ли.","Ра́дуйся, я́ко враго́в шата́нія, я́же на нас дви́жимая, разоря́єши.","Ра́дуйся, непра́ведно злосло́в'ящих нас к молча́нію приводя́щая.","Ра́дуйся, Тебі́ бо уста́ отверза́єм, вознося́ще благодаре́нія пі́сні.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 10","ps":["Ро́ду челові́чеському іскупле́ніє творя́, не імі́ Син челові́чеський, в Своє́м служе́нії на землі́, іді́же главу́ Свою́ подклони́ти: Ти же ре́вностно следовала Єму́, любвеоби́льная Ма́ти, опорою і утіше́нієм в Єго́ шествії із гра́да в град, із ві́си во весь всегда́ бива́я і Свої́м проше́нієм низводя́ на люде́й милосе́рдіє Своєго́ Си́на. І ни́ні род челові́чеський во вре́м'я вся́коє і день ка́ждий в Тебі́, любве́ Ма́ти, і́мать ско́рую по́мощ і непреобори́мую защи́ту, чесо́ ра́ди і вопіє́ть о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Си́ли неоскудеваємиє любо́во всеобдержная вхожде́нієм в мир Богоро́диці яви́ся чу́дно: ність взивающего, Єго́ же не усли́шала би любве́ Ма́ти, ність в моли́тві вопрошающего, Єму́ же утіше́ніє не дарова́ла би Засту́пниця, ність падающего под ярмом жи́зні скорбниє, Єму́ же Пречи́стая по́мощі не упроси́. Ізнемога́єть всяк глаго́л вознести́ Уті́шительнице ми́ра досто́йная хвале́нія, но і молча́ти уста́ на́ша не мо́гуть, со смире́нієм взива́я Богоро́дице:","Ра́дуйся, любве́ кла́дезь глубо́кий і неісчерпа́ємий.","Ра́дуйся, всіх любо́вно содержа́щая в се́рдці Своє́м.","Ра́дуйся, милосе́рдіє Ви́шняго на люде́й низводящая.","Ра́дуйся, всемі́рно взиску́ющая спасе́ніє па́дших.","Ра́дуйся, духо́в мра́ка і зло́би дале́че от нас отгоня́ющая.","Ра́дуйся, побіжда́ющая їх всемо́щною си́лою кро́тости Своє́й.","Ра́дуйся, вся́кому творе́нію Бо́жию к блаже́нной жи́зні спутешествующая.","Ра́дуйся, ми́ра го́рняго і до́льняго мо́сте преди́вний.","Ра́дуйся, ца́рству любве́ в лю́діх путь пра́вий уготовля́ющая.","Ра́дуйся, сокруша́ющая тім держа́ву вла́сті те́мния.","Ра́дуйся, всіх по́двигом жи́зні до́брі подвиза́ющихся неомраченноє весе́ліє.","Ра́дуйся, Тобо́ю бо в домі́х і во граді́х благоде́нствіє почива́єть.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 11","ps":["Труда́ тяжкого і болі́зней єсть житіє́ челові́ка на землі́, біди́ і лише́нія обдержа́ть єго́ всю́ду, приходящим їм, отону́дуже не ча́єть і борющим єго́ си́лою, проти́ву Єя́ же не мо́жеть крі́пко ста́ти. І та́ко преіспо́лнен би бил скорбе́й і стена́ніє всяк путь жи́зні, а́ще би не Ти Свої́м предста́тельством, ра́досте незаходи́мия Ма́ти, о Тебі́ же вопіє́м Бо́гу. Аллилу́я."]},{"h":"Ікос 11","ps":["У Го́спода вели́чіє обрі́тшая і бив по вся дні земни́я жи́зні Своєя́ други́ня си́рих і обездо́ленних, пресла́вно вознесе́на Сино́м в Небесниі кро́ви в честні́м Успе́нії Своє́м. І ни́ні преукраше́нная боже́ственними лі́потами, при́сно призира́єши на люде́й, озло́бленних гріхи́ мно́гими, да противустоять они́ тве́рдо по́мощію Твоє́ю всім скорбе́м і напа́стем сея́ многотру́дния жи́зні і, Цари́цю Небе́сную сла́в'яще, тща́ніє і́муть всегда́ восхваля́ти Ю та́ко:","Ра́дуйся, в Ца́рствії Си́на Твоєго́ сла́вою вінча́нная.","Ра́дуйся, с висо́т сла́ви Небе́сния в душі́ убо́гих нисходящая.","Ра́дуйся, вели́чієм вознесе́нная по Успе́нії Своє́м.","Ра́дуйся, люде́й стра́ждущих при́сно покрива́ющая омофо́ром Свої́м.","Ра́дуйся, други́ня ві́рная душ си́рих і оста́вленних.","Ра́дуйся, ра́досте всякіє тва́рі живу́щия.","Ра́дуйся, ца́рство благода́ті Сино́м Свої́м лю́дем дарова́вшая.","Ра́дуйся, обита́лище в домі́х ни́щих Себі́ сотво́ршая.","Ра́дуйся, приє́млющая немо́лчноє хвале́ніє А́нгельських сил.","Ра́дуйся, Богома́тере вели́чіє і Присноді́ви смире́ніє в Себі́ сочета́вшая.","Ра́дуйся, я́ко Тебі́ от кра́я і до кра́я землі́ многоустниє хвали́ ві́рних прино́сяться.","Ра́дуйся, ні єди́ния же душі́ недугующей і в томле́нії су́щей, Своє́ю помощю не оставля́ющая.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 12","ps":["Круг жи́зні моєя́ проходя́, страда́ніє і го́ре уві́дів, неду́ги ті́ла і ду́ха в себі́ побора́я і о всей ра́дости жи́зні Творця́ прославля́я, дерза́ю к Тебі́, Ма́тері Сві́та, принести́ моя́ піснопі́нія; Ти же ми́лостиво прийми́ їх, зане́ явля́єшися ріка́ вели́кая, точа́щая оби́ліє щедро́т, їх же преісполнені всі лю́ди, да соберу́ться ни́ні со мно́ю ку́пно, вопію́ще Бо́гу єди́ними усти́ і се́рдцем єди́ним: Аллилу́я."]},{"h":"Ікос 12","ps":["Цар сла́ви Христо́с благоволи́ роди́тися от Неіскусому́жния, па́че ми́ра Ю удобри́в, і вели́кия ми́лости на люде́й ізлива́я, Сію́ дарова́ помо́щницю лю́дем Свої́м стро́їти і покрива́ти от вся́кия біди́ раби́ Своя́, є́же і всім ви́димо бисть в чуде́снім зна́менії во гра́ді на́шем от Пречестни́я іко́ни Богома́тере, да не преста́нем Пречи́стій на вся́ко лі́то о сем слу́жбу твори́ти, со благодаре́нієм глаго́ля:","Ра́дуйся, покрове́ніє гра́да на́шего.","Ра́дуйся, неотсту́пная Предста́тельнице о впа́дших в напа́сть.","Ра́дуйся, с ви́шніх призира́ющая на смире́нних.","Ра́дуйся, го́рдим і завистним указу́ющая путь ісправле́нія.","Ра́дуйся, Тобо́ю бо труд землепашця освяща́ється.","Ра́дуйся, в Тебі́ бо си́лу є́млють в труді́ ослабльшії.","Ра́дуйся, нам к Тебі́ руки́ моли́твою воздевающим, жизнь творя́щая бога́тно.","Ра́дуйся, грози гибельниє, град і бездо́ждіє от землі́ на́шея отгоня́щая.","Ра́дуйся, нив і сел Ізборських незри́мая Охрано.","Ра́дуйся, от неістовств наше́ствія іноплеме́нних огражде́ніє на́ше.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 13","ps":["О, Ма́ти Єди́ная, любо́вію весь мир содержа́щая в се́рдці Своє́м і перед Сино́м Свої́м за Него́ хода́тайствующая немо́лчно. Сві́тло внемли́ хваленіям на́шим. Тебі́ із глубини́ душ смире́нних і благода́рних приноси́мим: прийми́ і моле́нія на́ша, не отніми Покро́ва заступле́нія Твоєго́ от ми́ра греховного, зане́ преступле́нія і гріхи́ на́ші всегда́ пред на́ми, Твої́м предста́тельством умно́жи си́ли на́ші стезю́ гріха́ минова́ти, поборов пре́лести і іскуше́нія путі́ блазненного і пространного, не оста́ви нас си́рими в жи́зні на́шей, єя́ же дні труда́ і лише́ній іспо́лнени, — да к Тебі́ в моленіях при́сно приліпля́яся, вся дні жи́зні на́шея тве́рдо, ра́достно і благоче́стно про́йдем, поне́же Ти і́маши си́лу низводити на нас, недосто́йних, благослове́ніє Влади́ки жи́зні і любве́, Єму́ же ни́ні со умиле́нієм вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельстії собо́ри, воплоще́нія та́йні чудя́щеся і Вседержи́телю о Ней немолчниє хвали́ всегда́ принося́ще, велича́нія прино́сять і Ді́ві ізбра́нній, Богома́тері Пречи́стій, із Нея́ же на спасе́ніє всім Бог воплоти́ся; сего́ ра́ди, небожителем подража́я, да подви́жеться всяк земноро́дний і, іспо́лнь ду́ха ра́дованія, да почита́єть он сві́тло свяще́нноє торжество́ Ді́ви і Ма́тере, взива́я Єй та́ко:","Ра́дуйся, жи́зні нестарі́ющей весно́ благоуха́нная.","Ра́дуйся, луча́ вознесенного цвіт красні́йшій.","Ра́дуйся, я́ко от Тебе́ всего́ ми́ра обновле́ніє ізи́де.","Ра́дуйся, гріхи́ і скве́рни всего́ ми́ра омива́ющая.","Ра́дуйся, таїнственного дне жи́зні блаже́нной заря́ пресві́тлая.","Ра́дуйся, всім, совершающим путь спасе́нія, неви́димая сопутнице.","Ра́дуйся, душ чи́стих ни́во небе́сная.","Ра́дуйся, па́житей духо́вних росо́ плодоно́сная.","Ра́дуйся, Тебі́ бо земля́ да́рствуєть цві́ти преди́внії.","Ра́дуйся, Тебі́ бо днесь тщі́мся прино́сіте пі́сні ізбранниє.","Ра́дуйся, благода́ть моли́тви, я́ко диха́ніє то́нкоє, в душа́х возгревающая.","Ра́дуйся, Светоче моле́нія на́шего ти́хий.","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Кондак 1","ps":["Возбра́нная от рождества́ Своєго́ Ді́во і по тихом успе́нії Своє́м в небе́сная вознесе́нная пресла́вно, служи́тельнице ізбавле́нія ми́ра смиреннейшая, в се́рдці своє́м о лю́діх печа́ль імеющая, близькая други́ня і уті́шительнице всіх оби́димих, тружда́ющихся і обремене́нним опоро неруши́мая, — Тебі́ ни́ні хвале́бная пі́нія по си́лі прино́сим, поне́же яви́ла єси́ от о́браза Своєго́ ми́лости преди́вния людям ізборським, да взива́єм Тебі́ немо́лчно:","Ра́дуйся, Богома́ти, в напа́стіх помо́щнице ско́рая."]},{"h":"Молитва","ps":["О, Всеми́лостивая Госпоже́, Пресвята́я Ді́во, Ма́ти Го́спода Ви́шніх Сил, Небесе́ і землі́ Цари́це, гра́да на́шего всемо́щная Засту́пнице. С ві́рою і любо́вію припа́даєм і поклоня́ємся Тебі́ пред Свято́ю і пречи́стою Твоє́ю чудотво́рною іко́ною, Є́ю же дивниє і пресла́вниє чудеса́ содіва́єши. О, Всеми́лостивая на́ша Засту́пнице і непости́дноє на́ше упова́ніє, благодари́м Тя о всіх благодія́ніїх от Тебе́, би́вших на нас от дре́вніх време́н і до ни́ні.","І ни́ні ми грі́шнії, воспомина́юще, ди́вноє зна́меніє Твоєго́ заступле́нія гра́да на́шего Ізборська, явле́нноє, во дні ра́тнаго на сей град наше́ствія, смире́нно мо́лим Тя: я́ко же дре́вле отце́м на́шим на по́мощ тогда́ ускори́ла єси́ і лю́ди ізборськия от бід спасла́ єси́ і мно́гіє зна́менія і чудеса́ явля́ла єси́, так і ни́ні, Преблагослове́нная Влади́чице при́зри на нас немощни́х і грі́шних раб Свої́х. Сподо́би Твоєго́ Матернего заступле́нія і благопопече́нія, о є́же ізба́витися нам от всякого зла.","Но, о, Пресвята́я Госпоже́ Влади́чице Богоро́дице! Со стра́хом, ві́рою і любо́вію припа́даєм пред Честно́ю іко́ною Твоє́ю і умиле́нною душе́ю і сокруше́нним се́рдцем со слеза́ми мо́лим Тя: отврати́ от нас, Всеми́лостивая на́ша Помо́щнице і Засту́пнице, пра́ведний гнів Бо́жий на ни дви́жимий і ізба́ви, нас, от гла́да, гра́да, огня́, меча́, наше́ствія іноплеме́нников і междоусобниє бра́ні. Храм і град сей до́брі сохрани́ і ві́рою живу́щих зді в ми́рі соблюди́. Бу́ди нам Засту́пнице і Хода́тайце пред Престо́лом Всевишнего, іді́же предстої́ши. Ко кому́ у́бо прибі́гнем, а́ще не к Тебі́, Пресвята́я Ма́ти Ді́во! Не і́мами бо іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Цари́це і Влади́чице! Под Твой Покро́в притека́єм. Моли́твами Твої́ми ниспосли́ Оте́честву на́шему мир, лю́дем здра́віє і землі́ плодоно́сіє, возду́ху благорастворе́ніє. Ізба́ви нас от паде́ній гріхо́вних, от наві́та злих челові́к, скорбе́й, бід і внеза́пния сме́рті. Вразуми́ нас, о, Всеми́лостивая Засту́пнице, ка́ко безгрі́шно прейти́ путь земного сего́ житія́. Ти бо ві́си не́мощі на́ша, ві́си і согріше́нія на́ша, но і ві́ру зри́ши і упова́ніє ви́диши.","Да́руй же нам дух сокруше́нія, смире́ніє се́рдця, чистоту́ помишле́ній, ісправле́ніє гріхо́вной жи́зні і оставле́ніє прегріше́ній. Укріпи́ в нас Правосла́вную ві́ру, вложи́ в се́рдця на́ша дух стра́ха Бо́жия, дух благоче́стія, дух кро́тости і смире́нія, дух любві́ і терпі́нія, в до́брих діла́х преуспі́яніє.","В Стра́шний же день суда́ Бо́жия, Твої́м моли́твенним хода́тайством і заступле́нієм, о, Пречи́стая Влади́чице, сподо́би нас стать одесну́ю Си́на Твоєго́, Христа́ Бо́га на́шего. Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє ни́ні і при́сно і в бесконечниі ві́ки. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Тучна Гора»","e":"Akathist to the Theotokos before her icon “Fertile Mountain”","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в людстих, Пресвята́я Богоро́дице, сосу́де чи́стий, Невмещаємаго вмісти́вшая, Горо́, єя́же преді́ли до Ца́рствія Бо́жия достига́ють і ко Христу́ возво́дять зову́щих Ті:","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Ікос 1","ps":["А́нгели со арха́нгели див'яхуся дре́внему провиденію Бо́жию о Тебі́, а́ще у́бо цар Дави́д прорече́ Тя псало́мсті а́ки Го́ру Ту́чную, я́ко зря уді́л Твой земни́й, го́ру Афо́нськую, ю́же ту́чі покрива́ша во дне Твоєго́ прише́ствія на ню, ми же покланя́яся ни́ні всечестні́й іко́ні Твоє́й славосло́вим Тя си́це:","Ра́дуйся, Ді́ва Пречи́стая, па́че всіх дів арха́нгелом обра́дованная;","Ра́дуйся, Же́но, Єя́же утро́ба ширше о́блак ту́чних.","Ра́дуйся, звіздо́, явля́ющая Со́лнце;","Ра́дуйся, сі́м'я проізрастившеє Дре́во живота́ ві́чнаго.","Ра́дуйся, две́ре непроходи́мая є́юже про́йде Созда́вший вся;","Ра́дуйся, попече́ніє о лю́діх неустанноє.","Ра́дуйся, Є́юже раї́ обновля́ється;","Ра́дуйся, Єя́же моли́тва непристанно возно́ситься к Бо́гу.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 2","ps":["Ви́дя под покро́вом твої́м Го́ру святу́ю Афо́нськую, і́стинний раб Бо́жий Савва́тіє, напечатле в душе́ своє́й о́браз Твой святи́й с горо́ю в ру́ці, Церковю на ней і благословляющим ю Богомладе́нцем, Спаси́телем на́шим, Єму́же піснь воспіва́єм при́сно: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́я глубину́ духовнаю сего́ о́браза і возвратяся в зе́млю о́тчую богому́дре о́тче наш Савва́тіє научи́ іноцев Воршина монастиря́ ка́ко на святі́й іко́ні Твоє́й ізобрази́ти Тя, чудотворящую ви́ну, всего́ ангельського о́браза Засту́пницю і во бденієх полнощних чи́стим се́рдцем воспіва́ти Ті сицева́я:","Ра́дуйся, ігу́менов пра́во устрояющих оби́телі Бо́жия при́сная Похвало́;","Ра́дуйся, іноцев смире́нних і пречестни́х Отра́до.","Ра́дуйся, цілому́дрія учи́лище благо́є;","Ра́дуйся, нестяжавих земниє бла́га небе́сноє ди́вноє наслі́діє.","Ра́дуйся, послуша́ніє до конця́ іспо́лнивших преві́чная Сла́во;","Ра́дуйся, незло́бивих і кро́тких ізвечноє обетованноє Блаже́нство.","Ра́дуйся, ми́лующих Ми́лость, се́рдця ві́рних согріва́ющая;","Ра́дуйся, не то́кмо іноцев но і миря́н Заступа́ющая.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 3","ps":["Си́ла ви́шняго осіня́єть всякого с ві́рою і благогові́нієм припа́дающаго к честно́му о́бразу Твоєму́, покланя́яся Первообразу і Бо́гу Сло́ву, я́ко Цві́ту благоуха́нному на усиренной почве Тучной Гори́ процветшему, Єму́же со умиле́нієм вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще благо́є намі́реніє порабо́тати во сла́ву Госпо́дню і ра́ди Пречи́стой Єго́ Ма́тері благочести́вий тферитянин Косма́ потруди́ся па́че уговора с ігу́меном Воршинським на устроє́нії собо́рній це́ркві в честь Вознесе́нія Бо́жия. Той же ігу́мен до́брий ви́дя єго́ рве́ніє і благодаря́ тру́дника сего́ рекл єси́: ізбери́ себі́ в мзду любую іко́ну, я́же зря́ше во святі́й оби́телі сей. Тру́дник же до́брий ізбра́ позабитий братієй на кли́росі о́браз Богоро́диці і обрі́тши єго́ возопи́л с весе́лієм к Тебі́ сицева́я:","Ра́дуйся, забве́нних святи́нь обрі́теніє;","Ра́дуйся, благочести́вим і трудящимся вспоможе́ніє.","Ра́дуйся, с Не́юже сора́дуються а́нгели;","Ра́дуйся, о Не́йже непреста́нно трепе́щуть де́мони.","Ра́дуйся, я́ко в сла́ві ві́чной пребива́єши;","Ра́дуйся, я́ко во сві́ті любве́ О́тчей с Присносущим Сино́м Свої́м сретилася єси́.","Ра́дуйся, во движе́ніях Ду́ха Бо́жия Благода́ті іспо́лнилася єси́;","Ра́дуйся, Тро́їчеськаго благослове́нія в Рождестві́ Своє́м сподо́билася єси́.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 4","ps":["Бу́рю злих прило́гов потопля́я в благода́ті серде́чній любві́ Твоє́й к ро́ду челові́чеському, і́ноці проводи́ша святу́ю іко́ну Твою́. Благочести́вий же Косма́, іспроси́ша благослове́нія Твоєго́ в путь оти́де в дом свой, ра́достно воспіва́я за сей многоці́нний дар Преві́чному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша о вели́ких ми́лостях Бо́жієй Ма́тері но не уразумі́ша нічесо́же і повину́яся оби́чаям лука́вим потомки Косьми́ небреженни ко святі́й Твоє́й іко́ні би́ша, і предаде́ забве́нію ю в грязном чулане, ми же ви́дя і в себі́ мно́жество небреженій, но понуждаємії Тобо́ю ісправить нрав свой к благоче́стію благода́рно вопіє́м Ті си́це:","Ра́дуйся, неумолчний Істо́чниче моли́тв о нас к Бо́гу Ви́шнему;","Ра́дуйся, Ра́досте сві́тлая па́че вся́кия земни́я ра́дости.","Ра́дуйся, ко благо́му нас направля́ющая;","Ра́дуйся, при́сноє попече́ніє і о ча́діх на́ших явля́ющая.","Ра́дуйся, си́рих усиновле́ніє;","Ра́дуйся, вдови́ць наде́жноє заступле́ніє.","Ра́дуйся, душ теплохладних по Бо́зі разгоряченіє;","Ра́дуйся, небреженних ко святи́ні нелицеприятноє осужде́ніє.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 5","ps":["Я́ко боготе́чній звізді́ покланя́ємся ни́ні пречестні́й іко́ні Твоє́й зря́ще ю істо́чником мно́гих ісціле́ній і кладезем всемо́щния по́мощі Твоєя́ супроти́в си́ли бісо́вськия, возстающия на ві́рних чад Це́ркві Бо́жієй, ї́хже восприя́ла єси́ в синовство́ вку́пі со святи́м апо́столом Іоа́нном, єгда́ Син Твой Боже́ственний вися́й на Дре́ві Кре́стнім рекл єси́: «Же́но, се син Твой». Ми же благода́рні за Ма́тер такову́ю ро́да на́шего вопіє́м Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще му́ку серде́чную молодой жени́ от мужнего зла́го бу́йства, я́ко та не мо́же претерпі́ти бо́ле і гото́ва согріши́ти несмиваємим гріхо́м самоубієнія, Присноді́ва посла́ єди́наго свята́го от ли́ка преподо́бних. Сей і́нок ди́вний предста́ пред отчаянной і рекл єси́ к ней «Ку́да ти грядеш, безу́мная?» І повелі́ єй обря́щи на чердакі всечестни́й і сла́вний о́браз Влади́чиці імену́ємий Ту́чная Горо́ і помоли́тися пред ним і бу́де осла́ба єй і ра́дость ве́лія. І посе́м і́нок ізчезе. Та же жена́ соблюла́ бі рече́нноє і іспо́лниша вся і вся бі та́ко. Ми же див'я́щеся чу́ду сему́ благода́рно вопіє́м Ті:","Ра́дуйся, домо́в християнстих от бур житейстих наде́жноє защище́ніє;","Ра́дуйся, бра́ков правосла́вних до́броє благослове́ніє.","Ра́дуйся, роди́телей о ма́лих ча́діх при́сная Ра́досте;","Ра́дуйся, ча́дом убедительноє поуче́ніє.","Ра́дуйся, Попечительная о мудрой і умащенной ста́рости;","Ра́дуйся, радостной і целомудренной ю́ности Наста́внице.","Ра́дуйся, же́стоких і зло́бних муже́й умиротвореніє;","Ра́дуйся, бу́їїх жен тиша́йшеє упокоє́ніє.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 6","ps":["Пропові́да чу́до ве́ліє от святі́й іко́ни Твоє́й ко всім жителям гра́да Тве́рі, і ви́дя я́ко див'яхуся і ра́довася христия́ни благочести́вия, зря́ше во святі́й іко́ні Твоє́й гото́воє заступле́ніє о гра́ді сем, і о всей землі́ Ру́ськой, установися пра́здник о чуді Богоро́диці і ми лику́я о сем благодарі́м Го́спода поя́ Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ сла́ва ве́лія о чуде́сних зна́меніях би́вших при святі́й іко́ні Твоє́й, і привлекла́ єси́ к ней мнозих богомо́льцев, ча́ющих получи́ти от неісче́тних щедро́т Твої́х, і ми ни́ні по́мощі от Теб'я́ тре́буя восхваля́єм Ті си́це:","Ра́дуйся, град Твой Твер от вся́кия напраслини ізбавля́ющая;","Ра́дуйся, і вся іни́я гра́ди украї́нськіє охраня́ющая.","Ра́дуйся, Є́юже храни́мі і ве́сі всі;","Ра́дуйся, Єя́же покро́в покрива́єть всяк язи́к правосла́вний.","Ра́дуйся, умаляющая ве́ліїх;","Ра́дуйся, удобряющая ма́лих.","Ра́дуйся, с Не́юже при́сно ра́дуємся о гряду́щем спасе́нії;","Ра́дуйся, с Не́юже го́рці пла́чем о грісі́х і паденієх на́ших.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 7","ps":["Хотя́щу яви́ти любо́в свою́ вся́кому челові́ку гряду́щему в мир Человіколю́бець Бог дарова́л єси́ нам Пречи́стую Свою́ Ма́тер я́ко ще́друю Моли́твенницю о не́мощіх на́ших, ми же от нея́ науча́ємся до́брим на́виком моли́тви і пі́нія Си́ну Єя́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая показа́ся ра́дость по Бо́зі, во терпі́нії і любве́, позна́єм єя́ благі́є плоди́ от моли́тв і бді́ній пред іко́ною Твоє́ю проводимих. Но что пра́ведному бре́м'я ле́гкоє, то для грі́шнаго і́го нестерпи́моє, та́ко і ни́ні не все на пир Божіій зва́ннії обріта́ються а́ки ізбра́нії, оба́че Ти і по тім та́кожде печалуєшся і молиш боже́ственнаго своєго́ Си́на, да дасть осла́бу і по́мощ малоду́шним і маловерам, ї́хже Он со святи́ми свої́ми ку́пно іскупи́ Кро́вію Своє́ю. Ми же ві́дая Твоє́ о нас многогрі́шних попече́ніє мо́лим тя ви́ну:","Ра́дуйся, грі́шних от гріха́ воззва́ніє;","Ра́дуйся, ско́рбних ко смире́нію наставле́ніє.","Ра́дуйся, кающимся полноє проще́ніє;","Ра́дуйся, го́рдим строгоє запреще́ніє.","Ра́дуйся, воїнам Христо́вим тве́рдость ду́ха і отвагу подаю́щая;","Ра́дуйся, злочести́вих враго́в обраща́ющая в страх і тре́петь.","Ра́дуйся, уставших от трудо́в ослабо;","Ра́дуйся, отча́янних от го́ря утіше́ніє.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до в Тебі́ показа́ Госпо́дь, я́ко Ді́ва бі і по Рождестві́ Ді́ва пребива́єши. Не то́чію во успе́нії пребила́ єси́ і во гро́бі, но і от землі́ тіле́сно вознесе́на бя́ше Сино́м Твої́м, а́ще і в Небесі́х ни́ні су́ща, херуви́мов честні́йши і серафи́мов сла́внійши, оба́че не обрі́те Тя отці́ богови́дці та́мо, поне́же Ти а́біє снизшла́ єси́ в по́мощ лю́дем, науча́я їх пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся бі во ви́шніх но і о ни́жніх при́сно неотступноє попече́ніє і́маши. Ми же во о́бразі Ту́чній Гори́ видем весь сонм глаго́лов Бо́жиїх к челові́честву: Го́ру Сина́йськую, та́мо Зако́н Мойсе́ю даде́ся; Го́ру Сіонськую, та́мо обрі́те наро́д ізбра́нний святи́ню себі́; Го́ру Фаво́рськую, та́мо откри́ся апо́столом в Си́ні Твоє́м ма́лая часть Си́ли і Сла́ви Єго́, Го́ру Єлео́нськую от нея́ же Вознесе́ся Христо́с, Го́ру Афо́нськую, та́мо Ти при́сно со іноцями до сконча́нія ві́ка, яка і с на́ми зді. Ми же ви́дя в сем о́бразе заві́т между́ на́ми і Тобо́ю Влади́чице воспіва́єм Тя си́це:","Ра́дуйся, правосла́вную ві́ру ісповедивать всіх науча́ющая;","Ра́дуйся, зла́го єрети́чества біжа́ти призива́ющая.","Ра́дуйся, Бо́жиїх глаго́лов ві́рноє толкова́ніє сообщающая;","Ра́дуйся, пре́жде проглаголанная проро́ки.","Ра́дуйся, па́стирям в проповедях висо́коє вдохнове́ніє;","Ра́дуйся, богословам в труда́х благо́є вспоможе́ніє.","Ра́дуйся, архієре́ом благосердечним му́драя Учи́тельнице;","Ра́дуйся, ієре́ом моли́твенним висо́кая Вдохновительнице.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ недоуміва́ша о чу́дній про́повіді о Тебі́, єгда́ рече́ дре́вній проро́к Заха́рія «Кто ти єси́ Горо́ вели́кая, пред лице́м Зорова́веля», той же основа́ша втори́й Храм во Ієрусали́мі, ти же єси́ основа́ всій Це́ркві Бо́жієй, пита́вшая млеко́м Питающего всіх свої́м Ті́лом і Кро́вію, єму́ же піснь воспіва́єм: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния я́ко юроди гугнивия жалким лепетом не возмо́гуть прорещи́ речей вразумительних і о ма́лой толике от безчи́сленних чуде́с при іко́ні Твоє́й явля́ємих, ми же с любовю і ві́рою припа́даєм і лобиза́єм ю і с серде́чним тре́петом воспіва́єм Ті сицева́я:","Ра́дуйся, любо́вію па́че зла́та і би́сера укра́шенная;","Ра́дуйся, Кри́не благоуха́нний благода́ті Бо́жієй.","Ра́дуйся, Ста́мно іспо́лненная чуде́с я́ко боже́ственной ма́нни;","Ра́дуйся, Киво́те в не́мже отобразися о́браз Бо́жий.","Ра́дуйся, слеза́ми омива́ющая гріхи́ чту́щих Тя;","Ра́дуйся, Сосу́де драгоці́нний в себі́ вселе́нную Сотво́ршаго імі́вшая.","Ра́дуйся, на́ша Наде́жда несумні́нная;","Ра́дуйся, на́ша Броня́ і Покро́ве.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й ма́терей мно́гих от гріха́ отчаяннія, от гріха́ сме́ртнаго, Ти яви́ла єси́ от іко́ни Твоєя́ імену́ємой Ту́чная Горо́ ско́роє вспоможе́ніє ча́дам їх ма́лим от многоразли́чних скорбе́й і болі́зней, ра́дуя і отце́в ку́пно ра́достію ве́лієй, да воспою́ть со всі́ми чтущими іко́ну Твою́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая била́ єси́ всім к Тебі́ прибегающим Влади́чице по проше́ствіє време́н возжела́ла єси́ Пречи́стая для чудотво́рной іко́ни Твоє́й імі́ти свой престо́л в честь нея́, і побудила єси́ древляго ста́рця Коняєва, вистроіть о́ний в хра́мі в честь смоле́нськой іко́ни Твоє́й. Ми же ви́дя на́шего пра́отця таково́є благо́є попече́ніє, возглаша́єм Ті си́це:","Ра́дуйся, ста́рцев благи́х ти́хая ра́досте;","Ра́дуйся, строї́телем хра́мов Бо́жиїх неоскудеваємая по́моще.","Ра́дуйся, ісполняющих За́повіді Бо́жії небе́сная наградо;","Ра́дуйся, ра́зві Тебе́ іни́я по Бо́зі по́мощі такови́я не і́мами.","Ра́дуйся, преподо́бних блага́я предводи́тельнице;","Ра́дуйся, му́чеников вінця́ми украсительнице.","Ра́дуйся, святи́телей собо́р на небесі́ вінча́ющая;","Ра́дуйся, безме́здних добродеятелей Сла́во.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 11","ps":["Пі́ніє вознося́ Тебі́ внесо́ша святу́ю іко́ну Твою́ во храм Смоле́нський ста́рець рече́ ра́достно: «Ни́ні отпуща́єши Влади́ко», преосвяще́нний же єпи́скоп Андре́й прия́л єси́ іко́ну сію́ чудотво́рную і водрузи́ ю в іконоста́с хра́мовий. Ми же див'я́шеся о Про́мислі Бо́жиєм і́же бі храм той на висо́цій го́ре, і́де спасася наро́д во дні високого ізлія́нія волжських вод, я́ко ни́ні же гора́ сія́ ста́ла воі́стину горо́ю Бо́жієй, горо́ю Ту́чною. Па́м'ятуя сіє́ воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприїмную свіщу́ собо́ю явля́єши да́руя скорб'я́щим очеса́м облегче́ніє і полноє ісціле́ніє, лю́діє же увозя в дальніє преді́ли тверськи́я землі́ благу́ю вість о сем чуде возвіща́ють, я́ко ціле́бний єле́й от іко́ни Твоє́й явля́єть благода́ть всемо́щную. Ми же ви́дя сіє́ с ті́ми воспіва́єм Ті си́це:","Ра́дуйся, да́же сліпи́м о́чі отверза́ющая;","Ра́дуйся, безстидним їх на до́лго закривающая.","Ра́дуйся, глухи́м до́броє сли́шаніє;","Ра́дуйся, наушников злих глухота́.","Ра́дуйся, німи́м уста́ глаго́лов благи́х ісполня́ющая;","Ра́дуйся, злосло́вія істо́чники во ві́ки затворяющая.","Ра́дуйся, хроми́х хожде́ніє;","Ра́дуйся, расслабенних возста́ніє.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 12","ps":["Благода́ть Твоя́ подає́ться всім ві́рующим во Христа́ Бо́га, злим же і безу́мним безбожником не зна́ємо да́же сло́во сіє́, а не то́кмо ді́йствіє благода́ті сей в челові́ціх. Так і єгда́ богомерзкіє і богоборниє вла́сті безумствуя лю́ті заливаше кро́вію христия́нстій град Твер і низве́рже храм святи́й, і́же бі іко́на Твоя́ «Ту́чная Горо́», нача́ убива́ти друг дру́га і не зна́ша ні поко́я, не ра́дости при́сно і́бо не вім я́ко пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Тя і сла́в'яще дивниє Твоя́ о ро́ді челові́чеськом ми́лости верниє раби́ Бо́жії хотя́ внов обрісти́ многомощную себі́ засту́пницю, до́брі постя́ся і моля́ся, ізобрази́ вно́ві о́браз Твой Богоро́дице Ту́чная Горо́ і я́коже дре́вле той бі во святі́й собо́рній це́ркве Вознесе́нія Воршинськой оби́телі, та́ко і ни́ні во Вознесенстем хра́мі гра́да Тве́рі возобновися сего́ о́браза почита́ніє, ми же ви́дяще Бо́жию ми́лость о сих гра́де і хра́мі честні́м воспіва́єм Ті сицева́я:","Ра́дуйся, от Вознесе́нія к Вознесе́нію прише́дшая;","Ра́дуйся, ві́рних себі́ сино́в і дще́рей та́мо наше́дшая.","Ра́дуйся, к Тебі́ приходя́щих Ра́досте;","Ра́дуйся, Тебі́ покланя́ющихся Отра́до.","Ра́дуйся, до́брих іконопи́сцев бла́го твори́ти управля́ющая;","Ра́дуйся, честни́х дия́конов і ієре́єв спаса́ющая.","Ра́дуйся, і певчим пі́ти помога́ющая;","Ра́дуйся, і предстоя́щих, і моля́щихся Тебі́ от бід оберегающая.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 13","ps":["О всепі́тая Ма́ти і Засту́пнице ро́да христия́нськаго. При́зри на тяготи́ і ско́рби і біди́ нас отяготившия, ни́ні колі́на на́ша прекло́нше мо́лим Тя во умиле́нії серде́чнім, прийми́ сіє́ ма́лоє моле́ніє і ниспосли́ і нам рабо́м от Тебе́ ро́ждшагося Бо́га (імена́) по́мощ, утвержде́ніє і вразумле́ніє, і сохрани́ на́ші семи в ми́рі, отжени́ вся́кую на́шу болі́знь і тяготу́, обрати́ всп'ять всякого врага́ і супоста́та, привлеци́ к Себі́ і соєдені в Бо́зі всіх вопію́щих Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели со арха́нгели див'яхуся дре́внему провиденію Бо́жию о Тебі́, а́ще у́бо цар Дави́д прорече́ Тя псало́мсті а́ки Го́ру Ту́чную, я́ко зря уді́л Твой земни́й, го́ру Афо́нськую, ю́же ту́чі покрива́ша во дне Твоєго́ прише́ствія на ню, ми же покланя́яся ни́ні всечестні́й іко́ні Твоє́й славосло́вим Тя си́це:","Ра́дуйся, Ді́ва Пречи́стая, па́че всіх дів арха́нгелом обра́дованная;","Ра́дуйся, Же́но, Єя́же утро́ба ширше о́блак ту́чних.","Ра́дуйся, звіздо́, явля́ющая Со́лнце;","Ра́дуйся, сі́м'я проізрастившеє Дре́во живота́ ві́чнаго.","Ра́дуйся, две́ре непроходи́мая є́юже про́йде Созда́вший вся;","Ра́дуйся, попече́ніє о лю́діх неустанноє.","Ра́дуйся, Є́юже раї́ обновля́ється;","Ра́дуйся, Єя́же моли́тва непристанно возно́ситься к Бо́гу.","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в людстих, Пресвята́я Богоро́дице, сосу́де чи́стий, Невмещаємаго вмісти́вшая, Горо́, єя́же преді́ли до Ца́рствія Бо́жия достига́ють і ко Христу́ возво́дять зову́щих Ті:","Ра́дуйся, Цари́це Небе́сная, Горо́ Ту́чная, Є́юже к человецем сни́де Бог."]},{"h":"Молитва","ps":["О, всеми́лостивая Влади́чице на́ша Пресвята́я Богоро́дице Марі́є! При́зри на ни погибающия раби́ Твоя́, бі́хом бо ми ме́рзькия, бі́хом бо ми блу́дния, бі́хом бо ми злоречивия, а па́че всего́ го́рдия, ни́ні же ви́діхом всю ме́рзость на́шу пред очеса́ми Го́спода і уже́ нісьм досто́йни предста́ти пред лице́м Єго́, і то́кмо Тя Влади́чице, я́ко Многомилостивую себі́ Засту́пницю призива́єм. О Ма́ти Бо́жия, во грісі́х су́щих не оста́ви нас. Наде́ждо на́ша несумні́нная, обнови́ нас в покая́нії, возста́ви к ісполне́нію за́повідей Бо́жиїх, учини́ нас в Це́ркве Святі́й і сотвори́ досто́йними Свята́го Прича́стія Животворя́щим і Боже́ственним і Стра́шним Та́йнам; Ти бо при́сно мо́лиши за ни Си́на Своєго́ і Бо́га, ві́ми я́ко мно́го бо мо́жеть моле́ніє ма́тернєє. І да іспроси́ у Христа́ Бо́га здра́вія нам телесного, і я́ко Ми́лостивая, облагодати́ душі́ на́ша, посли́ мир і благо́є поспіше́ніє всім бли́жнім на́шим, при́зри на град наш храни́мий покро́вом Твої́м, єму́же яви́ ско́роє заступле́ніє от чудотво́рния і благолі́пния святи́я Твоєя́ іко́ни, ю́же ни́ні благода́рні лобиза́єм, і сохрани́ єго́ і вся іні́ї гра́ди і ві́си і весь род правосла́вний от вся́ких напра́сних бі́дствій; і отрази́ єресе́й наше́ствіє от язи́к іноплеме́нних на нас находя́щия, раско́ли разори́, ра́спри і іни́я разділе́нія в Це́ркві Бо́жієй, я́ко єле́єм Твої́м ціле́бним, любо́вію нелицемерной умастив, наде́жно упра́ви, да ми́рноє і благочести́воє житіє́ бу́деть в уді́л нам, і да сподо́бимся до́брия глаго́ли от Си́на Твоєго́ і Судії́ на́шего сли́шати под Судо́м Єго́ пра́вим, Єму́ же сла́ва і честь і поклоне́ніє со безнача́льним Єго́ Отце́м і Всеблагодатним Єго́ Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["К Тебі́, Влади́чице, пред іко́ною Твоє́ю, во умиле́нії преклони́во ви́ю свою́ го́рдую, взива́ю: Се аз, грі́шний, от несущего к су́щему воззва́н бих, но ско́ро за моя́ безчисления і ме́рзькия согріше́нія внов в несущеє во а́дових бе́зднах обраще́н бу́ду; но із тьми зловонния гріхо́в мої́х молю́ся Ті, Преблага́я: спаси́ м'я, умоли́ Си́на Твоєго́ пожда́ти па́ки, да не пожре́ть м'я днесь напра́сния смерть, і да по вели́цій ми́лості Єго́ і при благоприятной Твоє́й, Пречи́стая, по́мощі, обращу́ся от тьми к Сві́ту, от самолю́бія к боголю́бію, от неві́рія к ві́рі, от зла ко бла́гу, от богомерзости гріха́ к преподо́бію; а́ще бо что челові́ку невозмо́жно бисть, то Бо́гу возмо́жно, і да отнині послужу́ ко прославле́нію Си́на Твоєго́, предадя ся всеблаго́й во́лі Єго́, даби́ і мні прийдти по стра́шнім суди́щі Христо́вом ко благи́м і возлю́бленним овця́м па́жити Єго́ в ра́дость при́сную і жизнь ві́чную. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Економісса» (Домобудівниця)","e":"Akathist to the Theotokos before her icon “Oikonomissa” (Housekeeper)","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от сложе́нія ми́ра Пресвяті́й Ді́ві Марі́ї Богоро́дице, воі́стину пло́тію ро́ждшей Ісу́са Христа́, Спа́са і Бо́га на́шего, Влади́чице всея́ вселе́нния, зіло́ возлюбившей род преподо́бних Христа́ і вземшей под Свой держа́вний покро́в їх святи́я оби́телі, похва́льноє прино́сим пі́ніє. Ти же, о Всечестна́я на́ша Ма́ти Ігу́меніє, храни́ і спаса́й нас от всіх враго́во ви́димих і неви́димих, да зове́м Ті:","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Ікос 1","ps":["А́нгели пло́тію су́ще всі преподо́бнії отці́ і ма́тері, ю́ноши і ді́ви, от ві́ка просія́вшії во святи́х, і ни́ні правосла́вно ше́ствующії в небе́сния селе́нія под сія́нієм Честна́го і Животворя́щаго Креста́ Христо́ва, на земно́м по́прище, во юдо́лі пла́ча і скорбе́й, под держа́вним покровительством Ма́тере Христа́ Бо́га на́шего, Всечестнейшия Ігуме́нії правосла́внаго мона́шеськаго житія́, Єя́же ми́лостивому заступле́нію ра́достно взива́єм си́це:","Ра́дуйся, Всечестнейшая на́ша Ма́ти Ігу́меніє;","ра́дуйся, наде́ждо на́шего спасе́нія.","Ра́дуйся, Святи́я Гори́ Афо́нськия Храни́тельнице;","ра́дуйся, та́мо живу́щих і́ноков спаси́тельнице.","Ра́дуйся, весе́ліє і сла́во Христо́вих подви́жников;","ра́дуйся, отра́до Боже́ственная святи́х пустинников.","Ра́дуйся, я́ко Тобо́ю всі святі́ї спаса́ються;","ра́дуйся, я́ко вся вселе́нная Тобо́ю украша́ється.","Ра́дуйся, ми́ра ви́димаго і неви́димаго о Бо́зі Влади́чице;","ра́дуйся, в селе́нія рая́ небе́снаго Руководи́тельнице.","Ра́дуйся, благо́є нача́ло і сла́вний коне́ць всіх святи́х житія́;","ра́дуйся, святи́я ра́дости Боже́ственния струя́.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 2","ps":["Ви́дя ско́рбний путь спасе́нія для всіх преподо́бних Свої́х, Госпо́дь наш Ісу́с Христо́с благоволи́ Ма́тері Своє́й, Всечестні́й Ді́ві Богоро́дице, да простре́ть Она́ Свой Боже́ственний покро́в ігу́менства над всі́ми святи́ми обителями Святи́я Афо́нськия Гори́ і всея́ вселе́нния правосла́внаго мона́шеськаго спасе́нія, да всі спаса́ющіїся в преподо́бії і свя́тості, ві́рою ви́дяще сіє́, взива́ють непреста́нно Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум іму́ще Боже́ственний всі преподо́бнії отці́ і ма́тері, от всея́ душі́ возлюби́ша сла́ву небе́сную, мир же со всі́ми єго́ пре́лестьми возненави́дівше і нога́ми попра́ша, ше́ствоваху в по́двизіх святи́х за Христо́м в ми́рі житія́ своєго́, безбі́дно руководимії Своє́ю Приснодевственною небе́сною Ігуменією, Єя́же ві́рою зря́ще в ли́ці Єя́ іко́н святи́х, уми́льно взива́ють та́ко:","Ра́дуйся, на́шего спасе́нія глави́зно;","ра́дуйся, ра́досте на́ша в сей і в бу́дущей жи́зні.","Ра́дуйся, ди́вная Строїтельнице на́ших святи́х оби́телей;","ра́дуйся, Єкономисса милосе́рдая і́ночеських общежи́тій.","Ра́дуйся, цві́те Боже́ственнаго прозябе́нія;","ра́дуйся, ра́досте всеми́рнаго воскресе́нія.","Ра́дуйся, всіх святи́х Боже́ственноє весе́ліє;","ра́дуйся, правосла́внаго мона́шества украше́ніє.","Ра́дуйся, і́стинная Ма́ти на́шего Спаси́теля;","ра́дуйся, я́ко пло́тію родила́ єси́ а́да Побіди́теля.","Ра́дуйся, я́ко на Афо́ні духо́вний сад насади́ла єси́;","ра́дуйся, я́ко та́мо живу́щих в преподо́бії в рай руководила єси́.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́єть всіх в преподо́бії і свя́тості і в пра́вді живу́щих, і́же возненави́діша суєту́ ми́ра сего́ і біжа́ша во святи́я мона́шеськия оби́телі і та́мо во о́бразі а́нгельськом, взе́мше на ся благо́є і́го Христо́во, свя́то подвиза́ющеся, чрез все житіє́ своє́ взива́ють непреста́нно ко Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 3","ps":["Всі собо́ри преподо́бних: просія́вшії во святи́х от ві́ка і ни́ні, іму́щії пла́менноє жела́ніє спасе́нія, по́двиги спасе́нія соверша́ющії во оби́теліх і́ночеськаго житія́, в лаврах, монастирі́х, скитіх, киновіях, ке́лліях і на вся́цім мі́сті всея́ вселе́нния, імі́я ди́вний щит спасе́нія, боже́ственноє ігу́менство Ма́тері Бо́жієй, хвале́бно Єй песнопоють:","Ра́дуйся, собирательнице на́ша среди́ ми́ра гріхо́внаго;","ра́дуйся, строїтельнице на́шего спасе́нія духо́внаго.","Ра́дуйся, спа́сшая весь род Ада́ма па́дшаго;","ра́дуйся, пло́тію ро́ждшая неізрече́нно Спа́са і Бо́га на́шего.","Ра́дуйся, Всечестнейшая Монахине, о́бразе спасающимся;","ра́дуйся, пра́ведная Ігу́меніє всіх нас, подвиза́ющихся.","Ра́дуйся, ві́ри правосла́вния Воєво́до непобіди́мая;","ра́дуйся, боже́ственная крі́посте всеси́льная.","Ра́дуйся, Ма́ти Госпо́дня і на́ша Благода́тная;","ра́дуйся, всім святи́м благоприя́тная.","Ра́дуйся, две́ре милосе́рдія ка́ющихся;","ра́дуйся, упова́ніє о Бо́зі подвиза́ющихся.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 4","ps":["Бу́рю сомні́ній гріхолюби́вих оста́вльше отці́ преподо́бния і ма́тері, возлюби́ша терни́стий путь спасе́нія, живу́ще посреді́ скорбе́й і лише́ній, Ца́рствія ра́ди Небе́снаго, украси́ша свої́м Богоуго́дним житіє́м премно́гая мі́ста вселе́нния, іді́же основа́ша святи́я оби́телі і́ночеськаго спасе́нія, в ни́хже спаса́ющіїся при́сно пою́ть А́нгельськую піснь Христу́ Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше святи́я глаго́ли Христо́ва Єва́нгелія ізбра́нници небе́снії, вся презрі́ша су́єтная ми́ра сего́ і в путь святи́й поідо́ша, нося́ще благо́є і́го Спа́са на́шего, житіє́м свої́м во пло́ті А́нгелом святи́м уподо́бишася, іму́ще преди́вную Ігуме́нію над всі́ми їх святи́ми обителями, по всей вселе́нній, я́ко зві́зди небе́сния, сія́ющими, к Не́йже вопію́ть всегда́:","Ра́дуйся, прему́драя Ігу́меніє мона́шества правосла́внаго;","ра́дуйся, спасе́ніє наро́да Богоізбра́ннаго.","Ра́дуйся, сто́лпе ді́вства і окея́не милосе́рдія;","ра́дуйся, ві́чная отра́до ра́йськаго весе́лія.","Ра́дуйся, прибі́жище кающимся грі́шником;","ра́дуйся, сокро́вище убо́гим подви́жником.","Ра́дуйся, всю вселе́нную любо́вію покрива́ющая;","ра́дуйся, сла́вою небе́сною сатану́ во ад низвергающая.","Ра́дуйся, Боже́ственная ра́досте А́нгелов і челові́ков;","ра́дуйся, я́ко плач принесла́ єси́ де́моном во ві́ки.","Ра́дуйся, єди́ная наде́ждо ві́ри правосла́вния;","ра́дуйся, Ма́ти Госпо́дня і на́ша Всесла́вная.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 5","ps":["Боготе́чную жизнь пра́ведници пройдо́ша і Небе́снаго Оте́чества с ра́достію достиго́ша, веселя́ться о Го́споді со А́нгели святи́ми во вся ві́ки; ми же, їх собратія, подвиза́ємся во святи́х оби́теліх, пою́ще хвале́бния пі́сні Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша ізбра́нници Госпо́дні скоропреходящую сла́ву ми́ра сего́: бога́тство непостоя́нно, счастье скороте́чно, ско́рби же, печа́лі і отча́яніє і вся́кия злоключе́нія при́снії спу́тници жи́зні сея́ єсть, в конці́ же смерть тіле́сная всім лю́дем неізбежна, свято́ю же ві́рою ві́чния селе́нія созерцаху, возлюби́ша ті́сний і приско́рбний путь мона́шеськаго житія́, іді́же Пресвята́я Ма́тер Самаго́ Го́спода ігуменствуєть, руководя́ спасающимися духо́вними ча́дами Єя́, хвале́бно к Ней взивающими:","Ра́дуйся, єди́ноє спасе́ніє душ на́ших;","ра́дуйся, ра́йськоє утіше́ніє всіх скорб'я́щих.","Ра́дуйся, Святи́я Гори́ Афо́нськия Просвіти́тельнице;","ра́дуйся, всея́ вселе́нния Покрови́тельнице.","Ра́дуйся, наде́жноє прибі́жище всім кающимся;","ра́дуйся, ти́хоє приста́нище от бід спасающимся.","Ра́дуйся, Ла́ври Пече́рськия Строїтельнице;","ра́дуйся, Поча́євськия оби́телі Защи́тнице.","Ра́дуйся, Єкономиссо Ла́ври Афана́сія Афо́нськаго;","ра́дуйся, кни́го Христо́ва Заві́та новосіонськаго.","Ра́дуйся, всіх святи́х во єди́но собра́вшая;","ра́дуйся, христия́ном правосла́вним путь в рай указавшая.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 6","ps":["Пропові́дници благода́тнаго равноа́нгельськаго житія́ во пло́ті яви́шася отці́ преподо́бнії: Анто́ній Вели́кий, Пахо́мій, Мака́рій, Феодо́сій і про́чії преподо́бнії отці́ і ма́тері, ї́хже житію́ со́нми послі́доваша всіх преподо́бних, наслі́дници би́вше ра́йських оби́телей со всі́ми святи́ми, і ми, їм ни́ні подража́юще, во А́нгельстім чи́ні живу́ще, воспіва́єм Спаси́телю ми́ра хвале́бния гла́си: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ о́браз житія́ равноа́нгельськаго для всіх, і́щущих спасе́нія вдали от всіх сує́ть мирськи́х, приме́ром Самаго́ Христа́ і Бо́га на́шего і Єго́ Пречи́стия Ма́тере Присноді́ви Марі́ї Богоро́диці, Предте́чі Госпо́дня Іоа́нна і премно́гих святи́х уго́дников, ї́хже житію́ подража́ють всі преподо́бнії, под держа́вним води́тельством Влади́чиці вселе́нния, Всечестнейшия Ігуме́нії правосла́вних мона́шеських оби́телей, Марі́ї Богоро́диці, хвалимой от всіх святи́х преди́вними похвала́ми си́це:","Ра́дуйся, правосла́внаго мона́шества Ма́ти Ігу́меніє;","ра́дуйся, їх а́нгельськаго житія́ ві́чноє спасе́ніє.","Ра́дуйся, блага́я Наста́внице на путь небе́сния жи́зні;","ра́дуйся, Настоя́тельниці мона́шеськия отчизни.","Ра́дуйся, ско́рая защи́то сиро́тствующих;","ра́дуйся, я́ко подви́жником святи́м вінці́ всегда́ гото́виши.","Ра́дуйся, всіх пра́ведников лю́б'ящая;","ра́дуйся, ка́ющихся грі́шников ми́лующая.","Ра́дуйся, я́ко Твоя́ люби́ Бо́жієй любві́ уподобля́ється;","ра́дуйся, я́ко Тобо́ю вся́кая твар о Го́споді спаса́ється.","Ра́дуйся, ра́досте боже́ственнаго весе́лія;","ра́дуйся, всего́ ми́ра покро́ве і спасе́ніє.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 7","ps":["Хотя́щу ско́рбний путь к небесі́ благоустро́іти, Госпо́дь наш Ісу́с Христо́с благоволи́ Ма́тері Своє́й, да ігуменствуєть над всі́ми правосла́вними і́ночеськими оби́тельми, по всей вселе́нній су́щими, руководя́ в селе́нія небе́снаго рая́ со́нми ізбранников, і́щущих спасе́нія і пою́щих Ізба́вителю Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую жизнь о́бразом а́нгельськаго житія́ показа́ша отці́ преподо́бнії і ма́тері, зане́, вся оста́вльше сла́дости ми́ра гріхо́внаго і возлюби́ша ше́ствовати к Небесі́ путе́м Царя́ Сла́ви Христа́ Бо́га на́шего, скорбми́ і страда́ньми, і би́ша му́ченици без кро́ве, терп'я́ще вся зла́я Ца́рствія ра́ди Бо́жия, є́же і получи́ша, і ни́ні со́нми преподо́бних ше́ствують такови́м путе́м, води́мії Ма́терію Бо́жиєю, я́ко Всечестнейшею Ігуменією їх преподо́бнаго житія́, превозносимою от них хвала́ми:","Ра́дуйся, Ма́ти Го́спода, Судії́ Всеправеднаго;","ра́дуйся, во Ігуме́нію от ві́ка предизбранная.","Ра́дуйся, чистото́ю тілесі́ твар превозше́дшая;","ра́дуйся, свя́тостію душі́ Своєя́ Небеса́ украси́вшая.","Ра́дуйся, благові́стіє Небе́снаго Оте́чества;","ра́дуйся, духо́вний кри́не правосла́внаго мона́шества.","Ра́дуйся, усе́рдная моли́твеннице о всіх правосла́вних;","ра́дуйся, блага́я строїтельнице для святи́х ізбра́нних.","Ра́дуйся, ти́хоє приста́нище всім странствующим;","ра́дуйся, поко́їще блаже́нния ста́рости.","Ра́дуйся, Неві́сто Неневі́стная.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 8","ps":["Стра́нноє житіє́ іму́ще Христо́ви ізбра́нници, оста́вльше тіле́сния стра́сті і уті́хи, возлюби́ша путь скорбе́й і страда́ній: в пусти́нях, на о́стровіх, в разсі́линах скал, в дубра́віх со звірми́ живу́ще равноа́нгельно, іді́же устро́їша Бо́жиєю во́лею святи́я оби́телі, в ни́хже воспіва́ху чрез все житіє́ своє́ херуви́мськи ко Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бив Всемогу́щий Бог во умі́х і сердця́х ізбра́нних Свої́х уго́дников, по рече́нному: \"Ди́вен Бог во святи́х Свої́х\", прославля́ше святи́я Своя́, собира́я із среди́ ми́ра гріхо́внаго, водворяя во святи́я оби́телі, да хва́литься і́ми свято́є і́м'я Єго́ со святи́ми А́нгели во ві́ки, і Влади́чиця Богоро́диця, Всеблага́я Ма́тер Госпо́дня прему́дро ігуменствуєть, спаса́я от бід і скорбе́й смире́нно восхваля́ющих ми́лости Єя́:","Ра́дуйся, Честні́йшая всея́ тва́рі і всея́ вселе́нния;","ра́дуйся, сладча́йшая, я́ко Бо́жиє селе́ніє.","Ра́дуйся, свято́й покро́ве жи́зні на́шея;","ра́дуйся, Боже́ственний істо́чниче сла́дости сладча́йшия.","Ра́дуйся, вся на́ша наде́ждо спасе́нія і поко́й;","ра́дуйся, по Бо́зі все на́ше упова́ніє в жи́зні земно́й.","Ра́дуйся, я́ко воскре́се Син Твой і Госпо́дь;","ра́дуйся, я́ко воскреси́ть Той вся́ку плоть.","Ра́дуйся, Ю́же воспіва́ють Небе́сная Во́їнства;","ра́дуйся, хвали́мая от всіх святи́х по досто́їнству.","Ра́дуйся, вели́кая ра́досте моєго́ спасе́нія;","ра́дуйся, всего́ ми́ра Боже́ственноє утіше́ніє.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 9","ps":["Вся́коє мудрова́ніє земно́є презрі́вше святі́ї уго́дниці, я́ко юро́диви Христа́ ра́ди яви́шася, бі́гающе і стра́нствующе на землі́, не іму́ще нігді́ тіле́снаго поко́я, Ца́рствія ра́ди Небе́снаго, є́же получи́ша, і ми, їм подража́юще житіє́м, по́двигами і любо́вію ко Го́споду, Єго́же і восхваля́єм, а́нгельськи пою́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї прему́дрости Госпо́дней яви́шася отці́ преподо́бнії: Пахо́мій Вели́кий, Анто́ній Вели́кий, Мака́рій Єги́петський і всіх правосла́вних і́ноков нача́льниці, просія́вшії во святи́х, і́бо свої́м святи́м житіє́м равноа́нгельським на землі́ і словеси́ спасе́нія спасо́ша премно́гия со́нми ученико́в, і́стинних рабо́в Христо́вих по всей вселе́нній, воленієм Пресвяти́я Тро́йці, под держа́вним ігу́менством Влади́чиці Богоро́диці, Ю́же от всея́ душі́ всегда́ хвалиша та́ко:","Ра́дуйся, Держа́вная Влади́чице вселе́нния;","ра́дуйся, Ігу́меніє на́шего спасе́нія.","Ра́дуйся, Бо́га Отця́ Дщи вселюбе́зная;","ра́дуйся, Ма́терію Си́на Бо́жия би́ти сподо́билася єси́ за свя́тость і смире́ніє.","Ра́дуйся, Бо́га Ду́ха Свята́го прекра́сная Пала́то;","ра́дуйся, на Небесі́ і на землі́ любо́вію Всебога́тая.","Ра́дуйся, іноки́не, честні́йшая Херуви́м;","ра́дуйся, Ма́ти Бо́га, преви́сшая Серафи́м.","Ра́дуйся, Апо́столов Христо́вих всему́дроє уче́ніє;","ра́дуйся, святи́х му́чеников преди́вноє терпі́ніє.","Ра́дуйся, всіх святи́х оправда́ніє;","ра́дуйся по́моще на́ша в земни́х страда́ніях.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський, Госпо́дь наш Ісу́с Христо́с сни́де с Небесе́ во юдо́ль пла́ча і скорбе́й і Свої́ми страда́ньми Боже́ственнаго житія́ подаде́ примі́р всім святи́м, желающим дости́гнути небе́снаго ві́чнаго поко́я, в преподо́бії і пра́вді хва́лящим Єго́ а́нгельськими гла́си: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пости Боже́ственния яви́лася єси́, на́ша Всечестна́я Ма́ти Ігу́меніє, охраняя, спаса́я, покрива́я вся святи́я оби́телі і́ночеськия жи́зні во Святі́й Горі́ Афо́нстій і по всей вселе́нній, от зари́ ві́ри христия́нськия і до дне Стра́шнаго Суда́ Христо́ва, спаса́я Боже́ственною ми́лостію преподо́бния Своя́, при́сно хвалящия Єя́ щедро́ти си́ми словеси́:","Ра́дуйся, Пресвята́я Ма́ти Ігу́меніє;","ра́дуйся, істо́чниче духо́внаго воскресе́нія.","Ра́дуйся, всю вселе́нную покрива́ющая;","ра́дуйся, святу́ю Це́рков Христо́ву увеселя́ющая.","Ра́дуйся, проро́чеськая сла́во і ві́нче;","ра́дуйся, і моєя́ жи́зні блаже́нний коне́ць.","Ра́дуйся, красні́йши не́ба єси́ і сладши рая́;","ра́дуйся, о́бразе свята́го житія́.","Ра́дуйся, лю́б'ящая Свой жре́бій Афо́н;","ра́дуйся, украша́ющая Ієрусали́м і Сіо́н.","Ра́дуйся, Ма́ти Милосе́рдаго Судії́;","ра́дуйся, пролива́ющая о ми́рі Своя́ сле́зния струї́.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сять всі святі́ї в небе́сних селе́ніїх ра́йських, со святи́ми А́нгели хва́ляще і превознося́ще Пресвяту́ю Тро́йцю: \"Свят, Свят, Свят\" вопію́ть, і ми, правосла́внії і́ноці, ві́рою сіє́ зря́ще, вопіє́м непреста́нно к Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ правосла́внаго житія́ приє́мше собо́ри преподо́бних, просія́вшії от ві́ка і ни́ні в путь небе́сний ше́ствующії, іму́ще Всемогу́щую о Го́споді Влади́чицю, Ма́тер Еммануїлову, с ра́достію вопію́ть к Ней похвала́ми си́це:","Ра́дуйся, подаю́щая нам о́браз смире́нія;","ра́дуйся, Собирательнице на́ша во оби́телі спасе́нія.","Ра́дуйся, Ігу́меніє святи́я Афо́нськия гори́;","ра́дуйся, Настоя́тельниці всіх святи́х монастире́й.","Ра́дуйся, монахине, житіє́м всечестнейшая;","ра́дуйся, Воєво́до, во бра́ніх всеси́льнійшая.","Ра́дуйся, чад церко́вних храни́тельнице;","ра́дуйся, живи́х і ме́ртвих Спаси́тельнице.","Ра́дуйся, сиро́тствующих Ма́ти благода́тная;","ра́дуйся, в ско́рбі су́щих отра́до прия́тная.","Ра́дуйся, спасе́ніє правосла́вних христия́н;","ра́дуйся, святи́х щедро́т Боже́ственний океян.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 12","ps":["Благода́ть подає́ть всегда́ Пресла́дкий Спаси́тель наш всім рабо́м Свої́м, в преподо́бії і свя́тості подвизающимся на по́прищі земна́го житія́; уже́ бо со́нми святи́х просла́вленних Правосла́вною Це́рковію, в ра́йських селе́ніїх воспіва́ють Пресвяту́ю Тро́йцю со всі́ми Небе́сними си́лами, і ми, їм подража́юще, вопіє́м ди́вному во святи́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще вся ми́лости Госпо́дні і щедро́ти к нам, недосто́йним і́ноком, при́сно ниспосилаємия, і всечестно́є ігу́менство над всі́ми на́шими обителями на́шея Всеблагодатния Влади́чиці Богоро́диці, ра́дуємся боже́ственне і веселі́мся, я́ко сподо́бившіїся спасе́ніє соверша́ти в тіх оби́теліх, іді́же уже́ премно́зі со́нми преподо́бних подви́жников достиго́ша Небе́снаго Ца́рствія, ї́хже святи́ми моли́твами по ми́лості Бо́жієй і под святи́м Покро́вом на́шея Небе́сния Ма́тере Ігуме́нії дости́гнем і ми ра́йських селе́ній за труди́ спасе́нія похва́льная, воспіва́я си́це словеса́:","Ра́дуйся, Пресвята́я Богоро́дице Ді́во;","ра́дуйся, спасе́нія на́шего Помо́щнице.","Ра́дуйся, Ігу́меніє всіх Всеще́драя;","ра́дуйся, в преподо́бії Ти єси́ пе́рвая.","Ра́дуйся, покро́вом ми́лости весь мир покрива́ющая;","ра́дуйся, сиро́т стра́нних пита́ющая.","Ра́дуйся, ю́ним цілому́дрія наста́внице;","ра́дуйся, о всіх лю́діх блага́я печальнице.","Ра́дуйся, ро́да пра́отця Ада́ма весе́ліє;","ра́дуйся, ти́хоє приста́нище спасе́нія.","Ра́дуйся, Всеще́драя на́ша Ма́ти Ігу́меніє;","ра́дуйся, благо́є нача́ло і коне́ць на́шего піснопі́нія.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 13","ps":["О Всепі́тая на́ша Ма́ти Ігу́меніє, Пресла́вная Влади́чице Богоро́дице! Прийми́ сія́ моле́нія на́ша, от всея́ душі́ Тебі́ ни́ні на́ми возноси́мая, і сподо́би нас в чи́ні а́нгельськом дости́гнути Небе́снаго Ца́рствія, іді́же всі святі́ї А́нгели воспіва́ють непреста́нними гла́си хвалу́ Пресвяті́й Тро́йці Бо́гу на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели пло́тію су́ще всі преподо́бнії отці́ і ма́тері, ю́ноши і ді́ви, от ві́ка просія́вшії во святи́х, і ни́ні правосла́вно ше́ствующії в небе́сния селе́нія под сія́нієм Честна́го і Животворя́щаго Креста́ Христо́ва, на земно́м по́прище, во юдо́лі пла́ча і скорбе́й, под держа́вним покровительством Ма́тере Христа́ Бо́га на́шего, Всечестнейшия Ігуме́нії правосла́внаго мона́шеськаго житія́, Єя́же ми́лостивому заступле́нію ра́достно взива́єм си́це:","Ра́дуйся, Всечестнейшая на́ша Ма́ти Ігу́меніє;","ра́дуйся, наде́ждо на́шего спасе́нія.","Ра́дуйся, Святи́я Гори́ Афо́нськия Храни́тельнице;","ра́дуйся, та́мо живу́щих і́ноков спаси́тельнице.","Ра́дуйся, весе́ліє і сла́во Христо́вих подви́жников;","ра́дуйся, отра́до Боже́ственная святи́х пустинников.","Ра́дуйся, я́ко Тобо́ю всі святі́ї спаса́ються;","ра́дуйся, я́ко вся вселе́нная Тобо́ю украша́ється.","Ра́дуйся, ми́ра ви́димаго і неви́димаго о Бо́зі Влади́чице;","ра́дуйся, в селе́нія рая́ небе́снаго Руководи́тельнице.","Ра́дуйся, благо́є нача́ло і сла́вний коне́ць всіх святи́х житія́;","ра́дуйся, святи́я ра́дости Боже́ственния струя́.","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Кондак 1","ps":["Ізбра́нній от сложе́нія ми́ра Пресвяті́й Ді́ві Марі́ї Богоро́дице, воі́стину пло́тію ро́ждшей Ісу́са Христа́, Спа́са і Бо́га на́шего, Влади́чице всея́ вселе́нния, зіло́ возлюбившей род преподо́бних Христа́ і вземшей под Свой держа́вний покро́в їх святи́я оби́телі, похва́льноє прино́сим пі́ніє. Ти же, о Всечестна́я на́ша Ма́ти Ігу́меніє, храни́ і спаса́й нас от всіх враго́во ви́димих і неви́димих, да зове́м Ті:","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Святи́я Гори́ Афо́на і всея́ вселе́нния правосла́вних оби́телей Всечестна́я Ігу́меніє."]},{"h":"Молитва","ps":["О Пречи́стая Влади́чице Богоро́дице, Всечестнейшая на́ша Ма́ти Ігу́меніє всіх правосла́вних святи́х оби́телей і́ночеськаго житія́, во Святі́й Горі́ Афо́нстій і по всей вселе́нній су́щих! Прийми́ смире́нная моле́нія на́ша і принеси́ я ко всеще́дрому Бо́гу на́шему, да спасе́ть душі́ на́ша Своє́ю благода́тію. Воззри́ на ни милосе́рдним Твої́м о́ком і соверши́ Сама́ о Го́споді на́ше спасе́ніє, поне́же без ми́лости Спа́са на́шего і Твоєго́ свята́го о нас хода́тайства не возмо́жем окая́ннії соверши́ти своєго́ спасе́нія, я́ко окаляхом житіє́ на́ше в суєтах мирськи́х, і́бо вре́м'я прибли́жися жа́тви Христо́ви і день Стра́шнаго Суда́ приспі́. Ми же, окая́ннії, погиба́єм в бе́здні гріхо́вній нераде́нія ра́ди на́шего, по рече́нному от святи́х отце́в, первонача́льников а́нгельськаго во пло́ті житія́, я́ко послі́днії мона́си нераді́нієм житія́ своєго́ уподо́б'яться мирськи́м челові́ком, є́же і сбисться днесь, і́бо послі́днєє і́ночество на́ше плаваєть житіє́м свої́м в мо́рі жите́йськом, посреді́ вели́кия бу́ри і непогоди, і́бо на́ша святи́я оби́телі во пра́сі пребива́ють, гріхо́в бо ра́ди на́ших всепра́ведний Судія́ Госпо́дь наш Ісу́с Христо́с та́ко благоволи́, ми же, недосто́йнії, не і́мами, гді глави́ подклони́ти.","О сладча́йшая на́ша Ма́ти Ігу́меніє! Собери́ ни, разсеянноє ста́до Христо́во, воєди́но і спаси́ правосла́вноє монашество послі́дняго ві́ка сего́, і всіх правосла́вних христия́н сподо́би ра́йськия жи́зні со а́нгели і всі́ми святи́ми во Ца́рствії Христа́ Бо́га на́шего, Єму́же честь і сла́ва, со Безнача́льним Єго́ Отце́м і со Пресвяти́м, Благи́м і Животворя́щим Єго́ Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Предста́тельство стра́шноє і непости́дноє, / не пре́зри, Блага́я, моли́тв на́ших, / Всепі́тая Богоро́дице, Ми́лостивая ві́рних Домострої́тельнице, / утверди́ правосла́вних жи́тельство, / спаси́ страну́ на́шу / і всіх правосла́вно живу́щих в ней защити́, // зане́ родила́ єси́ Бо́га, Єди́на Благослове́нная."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, хода́тайство ко Творцю́ непрело́жноє, не пре́зри грі́шних моле́ній гла́си, но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті; ускори́ на моли́тву і потщи́ся на умоле́ніє, предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже болі́зні на́ша врачу́єши і душі́ на́ша к Бо́гу возво́диши."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Валаамська»","e":"Akathist to the Theotokos before her icon “Valaam”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, благода́рственноє прино́сим пі́ніє о дарова́нії чу́дния Єя́ іко́ни Валаа́мськия. Ти же, Всеми́лостивая Цари́це, я́ко іму́щая держа́ву непобіди́мую і милосе́рдіє неізрече́нноє, от вся́ких зол і бід нас свободи́, да зове́м Ті:","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, прославле́нієм іко́ни Своєя́ святи́я всю страну́ Украї́нськую благода́тію озари́ла єси́, ті́мже ві́рнії лю́діє с любо́вію припа́дающе к ди́вному о́бразу Твоєму́ Валаа́мському, прино́сять похвали́ сія́:","Ра́дуйся, Отця́ Небе́снаго Чи́стая А́гнице;","ра́дуйся, Ма́ти Го́спода Ви́шняго.","Ра́дуйся, Це́ркве непоколеби́мий Сто́лпе;","ра́дуйся, Ца́рствія Неруши́мая Стіно́.","Ра́дуйся, зе́млю Ру́ськую в уді́л Себе́ ізбра́вшая;","ра́дуйся, іко́ни Твоя́ чудотво́рния, я́ко зві́зди, в ней умно́жившая.","Ра́дуйся, страни́ Украї́нськия Цари́це і Влади́чице;","ра́дуйся, я́ко Тобо́ю лю́діє правосла́внії соблюда́ються.","Ра́дуйся, всю вселе́нную луча́ми Твоєя́ благода́ті озаря́ющая;","ра́дуйся, сві́том ра́дости ду́ші на́ша просвіща́ющая.","Ра́дуйся, непобіди́мая Воєво́до царе́й і во́їнов правосла́вних;","ра́дуйся, враго́в на́ших ви́димих і неви́димих побіжда́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 2","ps":["Ві́дий гряду́щую сла́ву мі́ста сего́, благослови́ Госпо́дь Ма́тер Свою́ простре́ти Покро́в Єя́ над о́стровом Валаа́мом, сим Афо́ном сі́верним, да всі спаса́ющіїся на нем от літ дре́вніх, ни́ні і до ві́ка взива́ють непреста́нно Спаси́телю і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум іму́ще Боже́ственний, преподо́бнії отці́ на́ші Се́ргій і Ге́рман прийдо́ша в зе́млі сі́верния во є́же Го́споду невозбра́нно послужи́ти, і дости́гше о́строва Валаа́ма, оби́тель і́ночеськую та́мо устро́їша. Ти же, Пресвята́я Ді́во, сохрани́ всіх в ней подвиза́ющихся, єди́нім се́рдцем і єди́ними усти́ воспіва́ющих Ті:","Ра́дуйся, от младе́нства Бо́гу посвяще́нная;","ра́дуйся, в хра́мі Ієрусали́мськом воспита́нная.","Ра́дуйся, я́ко житіє́ Твоє́ при хра́мі проо́браз житія́ мона́шеськаго яви́ся;","ра́дуйся, і́ноков чадолюби́вая Ма́ти.","Ра́дуйся, о́стров Валаа́м явле́нієм благода́ті Твоєя́ освяти́вшая;","ра́дуйся, зе́млю Каре́льськую благоуха́нієм свя́тости іспо́лнившая.","Ра́дуйся, оби́тель Валаа́мськую, я́ко сі́верний Афо́н, просла́вившая;","ра́дуйся, хра́ми і ски́ти єя́ сла́вою чуде́с Твої́х осія́вшая.","Ра́дуйся, моли́тви преподо́бних Се́ргия і Ге́рмана к Своє́й присовокупи́вшая;","ра́дуйся, ми́лостію Твоє́ю на о́строві Валаа́мі ди́вний сад духо́вний насади́вшая.","Ра́дуйся, святи́я оби́телі Валаа́мськия Всечестна́я Ігу́менія;","ра́дуйся, Наста́внице і́ноков на путь Небе́сния жи́зні.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ ізо́графа, во оби́тель Валаа́мськую прите́кшаго і а́нгельський о́браз та́мо восприї́мшаго, і в честь свята́го іконопи́сця Пече́рськаго Али́пія нарече́ннаго. І дарова́ся єму́ благода́ть святи́я іко́ни писа́ти і хра́ми оби́телі ди́вно украша́ти, воспіва́я Творцю́ і Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи любо́в ко оби́телі Твоє́й ізбра́нній, Преблагослове́нная, сподо́била єси́ ізо́графа о́наго созда́ти іко́ну Твою́ честну́ю, є́йже си́лу чудотво́рную дарова́ла єси́ во ісціле́ніє і спасе́ніє всіх с ві́рою і наде́ждою притека́ющих к ней, да ви́дяще явля́ємую Тобо́ю ми́лость, вопію́ть со умиле́нієм такова́я:","Ра́дуйся, свяще́ннаго іконописа́нія Покрови́тельнице;","ра́дуйся, почита́нія святи́х іко́н утвержде́ніє.","Ра́дуйся, іко́ни Твоя́ на моли́твенноє обще́ніє нам дарова́вшая;","ра́дуйся, чрез них благода́тную си́лу істоча́ющая.","Ра́дуйся, образо́в списа́телем благогові́йним любо́в Твою́ святу́ю явля́ющая;","ра́дуйся, в по́двизіх і́ночеських їх наставля́вшая.","Ра́дуйся, в труді́х іконописа́нія Али́пія укріпи́вшая;","ра́дуйся, іко́ну Твою́ ди́вную созда́ти благослови́вшая.","Ра́дуйся, на іко́ні сей с Си́ном і Бо́гом Твої́м ізображе́нная;","ра́дуйся, мно́гими чудеси́ ю просла́вившая.","Ра́дуйся, я́ко моли́твою пред не́ю приє́млем душе́вноє утіше́ніє;","ра́дуйся, я́ко іко́ною Твоє́ю Сама́ среди́ нас пребива́єши.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 4","ps":["Бу́ря смуще́ній, воздвиза́ємая враго́м спасе́нія, поколеба́ кора́бль смире́нія і́нока Али́пія, і пону́ди єго́ оста́вити оби́тель Валаа́мськую. Оба́че моли́твами Твої́ми, Пречи́стая Богоро́дице, па́ки во оби́тель возврати́ся, і со слеза́ми к стопа́м ігу́мена припа́д, вся ко́зні сопроти́внаго попра́ і всего́ себе́ Бо́гові предаде́. Ті́мже в поще́нії, моли́твах і труді́х мно́гих во оби́телі жизнь препроводи́в, сподо́бися в день А́нгела своєго́ пресели́тися во оби́телі Небе́сния, іді́же с ли́ком А́нгельським поє́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь скорб жени́, двана́десять літ обурева́ємия тя́жкою болі́знію, дарова́ єй по́мощ благода́тную Богома́тере, Я́же яви́ся боля́щей в со́ннім виді́нії і повелі́ єй напра́вити стопи́ своя́ на Валаа́м, да просла́виться та́мо іко́на Єя́ чу́дная, дото́лі в небреже́нії пребива́вшая, от нея́же мно́зі обрету́ть ра́дость духо́вную і ісціле́ніє, вопію́ще Преблагослове́нній:","Ра́дуйся, моли́тву серде́чную боля́щия раби́ Бо́жия усли́шавшая;","ра́дуйся, в со́ннім виді́нії троєкра́тно єй яви́вшаяся.","Ра́дуйся, неду́жную ста́рицю со одра́ болі́зні воздви́гшая;","ра́дуйся, во оби́тель Валаа́мськую ю напра́вившая.","Ра́дуйся, чудотво́рную си́лу іко́ни Твоєя́ откри́вшая;","ра́дуйся, іко́ну Твою́ ди́вную во оби́телі показа́вшая.","Ра́дуйся, прославле́ніє іко́ни Твоєя́ ісціле́нієм тя́жко боля́щия жени́ знаменова́вшая;","ра́дуйся, сердца́ правосла́вних неізрече́нною ра́достію іспо́лнившая.","Ра́дуйся, іко́ною Твоє́ю в землі́ полу́нощній, я́ко со́лнце, просія́вшая;","ра́дуйся, сію́ я́ко сокро́вище безці́нноє нам оста́вившая.","Ра́дуйся, я́ко пред не́ю ві́рнії благогові́йно покланя́ються;","ра́дуйся, я́ко моля́щимся пред не́ю ісціле́нія подаю́ться.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бна яви́ся всечестна́я іко́на Твоя́, Влади́чице, ю́же я́ко дар небе́сний восприї́мше, і́ноці оби́телі Валаа́мськия поста́виша в собо́рнім хра́мі Преображе́нія Госпо́дня, благода́рственно взива́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше чу́до ісціле́нія боля́щия от іко́ни Твоєя́, Пресвята́я Ді́во, бра́тія оби́телі ра́дости іспо́лнишася і пречи́стому Твоєму́ о́бразу с любо́вію і благогові́нієм поклони́шася. Ми же грі́шнії, зря́ще і ни́ні во оби́телі сла́вній ізображе́нную на іко́ні Ма́тер Го́спода, ру́ці к ней простира́єм і умиле́нно зове́м:","Ра́дуйся, о́стров Валаа́м благослове́нієм Твої́м осіни́вшая;","ра́дуйся, оби́телі Валаа́мськия сокро́вище неоску́дноє.","Ра́дуйся, любо́в Твою́ ко оби́телі показа́вшая;","ра́дуйся, благо́є промишле́ніє о ней яви́вшая.","Ра́дуйся, оби́тель сію́ ми́лостію Твоє́ю посіти́вшая;","ра́дуйся, в зало́г любве́ іко́ну Твою́ чу́дную єй дарова́вшая.","Ра́дуйся, во оби́телі дре́вней просла́вленная;","ра́дуйся, і́ноков валаа́мських Покрови́тельнице.","Ра́дуйся, подвиза́ющимся в ней наде́жноє заступле́ніє;","ра́дуйся, приходя́щим в ню на поклоне́ніє блага́я Предста́тельнице.","Ра́дуйся, і́ноков оби́телі на служе́ніє Го́споду собира́ющая;","ра́дуйся, в служе́нії сем путь показу́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 6","ps":["Пропові́дниця благода́тния по́мощі Влади́чиці яви́ся ісцеле́нная раба́ Бо́жия, і о чудеси́, на ней би́вшем, с ра́достію і благогові́нієм всім пові́да. Є́йже подража́юще, і ми прославля́єм ми́лості Твоя́, Ді́во Пречи́стая, от іко́ни ізлива́ємия, я́ко гра́ди і ве́сі огражда́єши, оби́телі і́ночеськия защища́єши, неду́жния ісціля́єши і вся блага́я низпосила́єши всім лю́б'ящим Тя і пою́щим Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ на о́строві Валаа́мі о́браз равноа́нгельнаго житія́ всім і́щущим спасе́нія дале́че от суєти́ мирськи́я под держа́вним Покро́вом Богома́тере, Єя́же іко́на во оби́телі я́ко зна́меніє попече́нія Пречи́стия о всіх нас зри́ться. Ми же, гріхми́ помраче́ннії, толи́кую ми́лость ві́дуще, воспої́м Преблагослове́нній:","Ра́дуйся, Благода́тная, оби́тель святу́ю осіни́вшая пречи́стим Твої́м о́бразом;","ра́дуйся, я́ко па́че би́сер слеза́ми ра́дости іко́на Твоя́ украша́ється.","Ра́дуйся, си́лу Твою́ благода́тную в сей іко́ні оби́льно яви́вшая;","ра́дуйся, во всем ми́рі істо́чник ісціле́ній от святи́х іко́н Твої́х подаю́щая.","Ра́дуйся, покланя́ющимся іко́ні Твоє́й в печа́ліх і біда́х ско́ро помога́ющая;","ра́дуйся, і нас грі́шних ко спасе́нію наставля́ющая.","Ра́дуйся, о всіх чту́щих о́браз Твой промишля́ющая;","ра́дуйся, чудеси́ от него́ ві́ру і́стинную в лю́діх утвержда́ющая.","Ра́дуйся, Бо́гом дарова́нная отра́до стра́ждущим;","ра́дуйся, сокро́вище благода́ті неоскудіва́ємоє.","Ра́дуйся, ру́ці Твої́ к Бо́гу о нас простира́ющая;","ра́дуйся, ві́чною ра́достію нас одіва́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 7","ps":["Хотя́ вели́кий князь Никола́й благода́рственная принести́ Тебі́, Богоро́дице, повелі́ в годи́ну бра́ні всеми́рния устро́їти храм во і́м'я Твоє́, да всі і́ноці оби́телі помина́ють вожде́й і во́їнов за ві́ру, царя́ і Оте́чество живо́т свой положи́вших, во вся дні пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до показа́ Госпо́дь, єгда́ ста́рець Валаа́мський Бори́с во виді́нії узрі́ преподо́бних Се́ргия і Ге́рмана, іко́ні Богома́тере предстоя́щих і моля́щихся во увіре́ніє пребива́нія їх во оби́телі со бра́тією. Ми же ублажа́юще сих уго́дников Бо́жиїх мо́лимся, о є́же сподо́битися нам, вку́пі с ни́ми досто́йно воспі́ти Всесвяту́ю Ма́тер Го́спода:","Ра́дуйся, Афо́н сі́верний с преподо́бними Се́ргиєм і Ге́рманом охраня́ющая;","ра́дуйся, ста́рця валаа́мськаго виді́ній сподо́бившая.","Ра́дуйся, Оте́чества на́шего Печа́льнице;","ра́дуйся, держа́вная Покрови́тельнице на́ша во дні тя́жких іспита́ній.","Ра́дуйся, во дні бра́ні ско́рая на враги́ Помо́щнице;","ра́дуйся, во дні ми́ра ко благоче́стію Наста́внице.","Ра́дуйся, во́їнов правосла́вних на по́двиг ра́тний укріпля́ющая;","ра́дуйся, му́жество неодоли́моє їм да́рующая.","Ра́дуйся, си́лу ду́ха їх возвиша́ющая;","ра́дуйся, до́брим страти́гом і ра́тником вінці́ уготовля́ющая.","Ра́дуйся, со Архистрати́гом враги́ на́ша поража́ющая;","ра́дуйся, моли́твами Твої́ми весь мир спаса́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 8","ps":["Стра́нноє і ди́вноє виді́ніє дарова́ Госпо́дь ста́рцю Бори́су в преддве́рії низпроверже́нія Ца́рства Украї́нськаго: ви́ді пра́ведник Тя, Ма́тер Бо́жию, пред Си́ном Твої́м і Го́сподем те́плі Єго́ умоля́вшую со слеза́ми, да отве́рзеть две́рі милосе́рдія Своєго́ страні́ на́шей і лю́дем єя́. Ті́мже у́бо воспла́чемся і ми о грісі́х свої́х і с наде́ждою возопії́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся страна́ Украї́нськая в страх і тре́петь приї́де, єгда́ восхоті́ враг ро́да челові́чеськаго ві́ру Христо́ву в ней істреби́ти. Ти же, Всеми́лостивая, во дні лихолі́тія сохрани́ла єси́ зе́млю Ру́ськую от поги́белі і ві́ру правосла́вную от істребле́нія спасла́ єси́. Помози́ у́бо нам, Влади́чице, с терпі́нієм і благодаре́нієм вся́кия ско́рби і біди́ претерпіва́ти і взива́ти Тебі́ ра́достно:","Ра́дуйся, ізбра́нним Твої́м виді́нія небе́сная открива́ющая;","ра́дуйся, ди́вная зна́менія іко́ною Твоє́ю соверша́ющая.","Ра́дуйся, люде́й правосла́вних благода́тноє утвержде́ніє;","ра́дуйся, в годи́ну іспита́ній держа́вною Твоє́ю руко́ю от поги́белі нас спа́сшая.","Ра́дуйся, Це́рков Ру́ськую во дні гоне́ній омофо́ром Твої́м покрива́ющая;","ра́дуйся, в страда́ніїх за Христа́ му́чеников і іспові́дников ві́ри укріпля́ющая.","Ра́дуйся, во́їнствующих на Це́рков Бо́жию вразумля́ющая;","ра́дуйся, зло́бу і кова́рство їх посрамля́ющая.","Ра́дуйся, вражду́ і не́нависть ми́ром і любо́вію побіжда́ющая;","ра́дуйся, сле́зи чад Твої́х отира́ющая.","Ра́дуйся, луча́ми Боже́ственними тьму вра́жию попаля́ющая;","ра́дуйся, во ору́жіє сві́та нас облека́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 9","ps":["Всіх в разсі́янії су́щих люде́й ру́ських уті́шила єси́, Ма́ти Бо́жия, іко́ною Твоє́ю Валаа́мською. І́ноці бо оби́телі вку́пі с ві́рними ча́ди Це́ркве Правосла́вния ско́рби разлуче́нія с Оте́чеством со смире́нієм приє́млюще, к чудотво́рному о́бразу Влади́чиці притека́ху, в єдиноми́слії воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії челові́честії недоумі́ють разумі́ти та́йну спасе́нія Оте́чества на́шего во дні вели́каго наше́ствія іноплеме́нник, єгда́ смерть і у́жас по лицю́ землі́ Ру́ськия пройдо́ша, плач і стена́ніє ю огласи́ша. Тогда́ у́бо всі на Тя, Пречи́стая, упова́ніє возложи́вшії і от Тебе́ Єди́ния спасе́нія ча́ющії, поя́ху со слеза́ми:","Ра́дуйся, Засту́пнице на́ша усе́рдная;","ра́дуйся, от всіх враго́в Ізбавле́ніє.","Ра́дуйся, на по́двиги бра́ні во́їнськия і духо́вния нас вдохновля́ющая;","ра́дуйся, го́рдих си́лою Твоє́ю со стидо́м всп'ять возвраща́ющая.","Ра́дуйся, я́ко Тобо́ю милосе́рдіє Бо́жиє улуча́єм;","ра́дуйся, я́ко мно́го мо́жеть моли́тва Твоя́ пред Си́ном Твої́м і Бо́гом на́шим.","Ра́дуйся, іко́ну Твою́ святу́ю в біда́х і іспита́ніїх невреди́мо сохрани́вшая;","ра́дуйся, ру́ських люде́й в разсі́янії су́щих є́ю утеша́вшая.","Ра́дуйся, всіх разсі́янних воєди́но собира́ющая;","ра́дуйся, раздо́ри і нестроє́нія умиря́ющая.","Ра́дуйся, Наде́ждо і Прибі́жище на́ше;","ра́дуйся, Непобіди́мая Побі́до.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи стра́ждущую страну́ на́шу, яви́лася єси́, Пречи́стая, во виді́нії ста́рцю Валаа́мському Михаї́лу, я́ко Предста́тельниця на́ша пред Бо́гом і Засту́пниця, і в гро́зний час біди́ враго́м противоста́ла єси́, крі́пость во́їном подала́ єси́, полки́ іноплеме́нних всп'ять обраща́ющи, і побі́ду украї́нському во́їнству дарова́ла єси́, да всі лю́діє страни́ на́шея пою́ть Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і істо́чник чуде́с іко́на Твоя́ свята́я яви́ся, Богоро́дице Ді́во, не то́кмо оби́телі Валаа́мськой, но і всей страні́ на́шей, зе́млю на́шу огражда́ющая і в Русі́ Святі́й благогові́йні чти́мая. Спаси́ і поми́луй нас, припа́дающих ко о́бразу Твоєму́ чудотво́рному, да сподо́бимся вся́каго утіше́нія, воспіва́юще Тебі́:","Ра́дуйся, в со́ніїх і виді́ніїх рабо́в Твої́х посіща́ющая;","ра́дуйся, та́йни промишле́нія Бо́жия о страні́ на́шей їм открива́ющая.","Ра́дуйся, ста́рцю Михаї́лу зна́меніє Твоєго́ милосе́рдія к наро́ду на́шему яви́вшая;","ра́дуйся, держа́ву Украї́нськую па́ки сла́вою Твоє́ю осія́вшая.","Ра́дуйся, пред Го́сподем дерзнове́нная на́ша Предста́тельнице;","ра́дуйся, гнів Єго́ пра́ведний, на ни дви́жимий, на ми́лость прелага́ющая.","Ра́дуйся, проти́ву слуг сатани́нських ратобо́рствующая;","ра́дуйся, несокруши́мий щі́те во́їнов украї́нських.","Ра́дуйся, во́їнство врага́ порази́вшая;","ра́дуйся, от преді́л землі́ на́шея єго́ отгна́вшая.","Ра́дуйся, во́їном Украї́ни на по́ли бра́ні побі́ду дарова́вшая;","ра́дуйся, страну́ на́шу от наше́ствія іноплеме́нних преди́вно ізба́вившая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє с любо́вію прино́сять бра́тія оби́телі Тебі́, о Всеблага́я Ма́ти, во хра́мі в честь іко́ни Твоєя́ освяще́ннім. Усли́ши і нас, моля́щихся пред пречи́стим о́бразом Твої́м, і сохрани́ жизнь на́шу в чистоті́, от гріхо́в ізба́витися помози́, утоли́ болі́зні і печа́лі, на спасе́нія стезі́ наста́ви і научи́ воспіва́ти Человіколю́бцю Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тло сія́єть ди́вная іко́на Твоя́, Ма́ти Бо́жия, і Украї́нськую страну́ на́шу благода́тію озаря́єть. Сего́ ра́ди гряду́ть во оби́тель Валаа́мськую на поклоне́ніє правосла́вних собо́ри, умиле́нно воспіва́юще із глубини́ душі́ пред пречи́стим о́бразом Твої́м такова́я:","Ра́дуйся, о́стров Валаа́м сві́том святи́ні озари́вшая;","ра́дуйся, оби́тель Валаа́мськую благода́тію Твоє́ю возроди́вшая.","Ра́дуйся, Домострої́тельнице, жизнь оби́телі до́брі устроя́ющая;","ра́дуйся, от всіх конце́в землі́ во оби́тель люде́й правосла́вних призива́ющая.","Ра́дуйся, пало́мников благочести́вих непости́дноє упова́ніє;","ра́дуйся, і́ноков валаа́мських при́сноє ра́дованіє.","Ра́дуйся, о́бразом Твої́м честни́м оби́тель і ни́ні освяща́ющая;","ра́дуйся, сві́том Боже́ственним от іко́ни Твоєя́ тьму неві́рія прогоня́ющая.","Ра́дуйся, Ма́ти Сві́та, ду́ші ві́рних просвіща́ющая;","ра́дуйся, к Сві́ту і́стини нас возводя́щая.","Ра́дуйся, Огнь Божества́ в Себі́ вмісти́вшая;","ра́дуйся, любве́ Боже́ственния світи́льниче неугаси́мий.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 12","ps":["Благода́тноє утіше́ніє дарова́ла єси́ нам, Пресвята́я Ді́во, прославле́нієм о́браза Твоєго́ Валаа́мськаго в зна́меніє ми́лости ко Оте́честву на́шему, в защи́ту от враго́во ви́димих і неви́димих. Да́руй Покро́в Твой, Благода́тная, на всіх путеіх жи́зні на́шея, да уразумі́єм, я́ко с на́ми Бог, Єму́же с любо́вію да поє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Тя, Преблагослове́нная, преклоня́єм колі́на пред чудотво́рним Твої́м о́бразом Валаа́мським і, моля́щеся пред ним, ві́руєм і іспові́дуєм, я́ко Ти єси́ воі́стину Держа́вная Влади́чиця страни́ на́шея і Засту́пниця усе́рдная ро́да христия́нськаго. Ті́мже мо́лим Тя, пода́ждь Оте́честву на́шему мир, тишину́, благоустроє́ніє, і не оста́ви ві́рния лю́ди Твоя́, во умиле́нії серде́ць принося́щия Ті похвали́ сія́:","Ра́дуйся, іко́ну Твою́ Валаа́мськую ди́вно просла́вившая;","ра́дуйся, но́воє зна́меніє благода́ті в Це́ркві Правосла́вній тім показа́вшая.","Ра́дуйся, я́ко от іко́ни Твоєя́ зна́менія і чудеса́ соверша́ються;","ра́дуйся, я́ко сердца́ благочести́вих люде́й ра́достію ісполня́ються.","Ра́дуйся, страни́ Украї́нськия несокруши́моє Огражде́ніє;","ра́дуйся, ни́нішняго ско́рбнаго ві́ка Утіше́ніє.","Ра́дуйся, святи́х печа́льников землі́ Украї́нськия возрасти́вшая;","ра́дуйся, ізнемога́ющих под тя́жестію креста́ укріпля́ющая.","Ра́дуйся, страх і уни́ніє прогоня́ющая;","ра́дуйся, скорб на́шу в ра́дость претворя́ющая.","Ра́дуйся, стоя́ти за ві́ру правосла́вную нас науча́ющая;","ра́дуйся, две́рі ра́йськія ві́рним отверза́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Украї́нськия страни́ ди́вная Засту́пнице, ми́лостивно прийми́ сіє́ ма́лоє моле́ніє, пред чудотво́рним Твої́м о́бразом возноси́моє. Сохрани́ Оте́чество на́ше, ві́ру правосла́вную в лю́діх укріпи́, ізба́ви нас от вся́ких бід, скорбе́й і напа́стей, і сподо́би чи́стим се́рдцем зді і в бу́дущем ві́ці воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, прославле́нієм іко́ни Своєя́ святи́я всю страну́ Украї́нськую благода́тію озари́ла єси́, ті́мже ві́рнії лю́діє с любо́вію припа́дающе к ди́вному о́бразу Твоєму́ Валаа́мському, прино́сять похвали́ сія́:","Ра́дуйся, Отця́ Небе́снаго Чи́стая А́гнице;","ра́дуйся, Ма́ти Го́спода Ви́шняго.","Ра́дуйся, Це́ркве непоколеби́мий Сто́лпе;","ра́дуйся, Ца́рствія Неруши́мая Стіно́.","Ра́дуйся, зе́млю Ру́ськую в уді́л Себе́ ізбра́вшая;","ра́дуйся, іко́ни Твоя́ чудотво́рния, я́ко зві́зди, в ней умно́жившая.","Ра́дуйся, страни́ Украї́нськия Цари́це і Влади́чице;","ра́дуйся, я́ко Тобо́ю лю́діє правосла́внії соблюда́ються.","Ра́дуйся, всю вселе́нную луча́ми Твоєя́ благода́ті озаря́ющая;","ра́дуйся, сві́том ра́дости ду́ші на́ша просвіща́ющая.","Ра́дуйся, непобіди́мая Воєво́до царе́й і во́їнов правосла́вних;","ра́дуйся, враго́в на́ших ви́димих і неви́димих побіжда́ющая.","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, благода́рственноє прино́сим пі́ніє о дарова́нії чу́дния Єя́ іко́ни Валаа́мськия. Ти же, Всеми́лостивая Цари́це, я́ко іму́щая держа́ву непобіди́мую і милосе́рдіє неізрече́нноє, от вся́ких зол і бід нас свободи́, да зове́м Ті:","Ра́дуйся, Влади́чице, оби́телі Валаа́мськия і страни́ на́шея ди́вная Засту́пнице."]},{"h":"Молитва","ps":["О Пресвята́я і Преблагослове́нная Влади́чице Богоро́дице, Небесе́ і землі́ Цари́це, оби́телі Валаа́мськия Покрови́тельнице! Припа́даєм і покланя́ємся Тебі́ пред чудотво́рною іко́ною Твоє́ю, і я́ко призрі́ла єси́ ми́лостивно на моли́тву боля́щия раби́ Твоєя́ і дарова́ла єси́ єй ісціле́ніє, та́ко і ни́ні прийми́ на́ше усе́рдноє моле́ніє, Тебі́ приноси́моє. Спаси́ і сохрани́, Всеми́лостивая, Оте́чество на́ше і вся лю́ди правосла́вния, живу́щия в нем і к Тебі́ с любо́вію прибега́ющия, от наше́ствія іноплеме́нних, от гла́да і мо́ра, і от вся́каго зла; упра́ви путі́ на́ша, да возсія́ють в землі́ на́шей пра́вда і мир, ра́дость і любо́в, сохрани́ в ней до сконча́нія ві́ка ві́ру правосла́вную. Воззри́ ми́лостивим о́ком Твої́м на оби́тель Валаа́мськую і соверши́ Сама́ о Го́споді спасе́ніє всіх во ві́рі і наде́жді подвиза́ющихся в ней. Умоли́ Си́на Твоєго́ і Бо́га на́шего, да ізба́вить всіх нас от вся́кия біди́, ско́рби і болі́зні, да наста́вить на ісполне́ніє за́повідей Свої́х, от ві́чния му́ки ізба́вить і да сподо́бит Твої́м хода́тайством всели́тися во оби́теліх Небе́сних і сла́вити та́мо Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["Пресвята́я Госпоже́, Влади́чице Богоро́дице, страни́ на́шея Засту́пнице, оби́телі Валаа́мськия красото́ і сла́во! Взира́юще на пречи́стий лик Твой, в чудотво́рній іко́ні явле́нний, мо́лим Тя, сохрани́ от вся́каго зла оби́тель сію́, ю́же преподо́бнії Се́ргій і Ге́рман основа́ша, во бра́тії мир соблюди́, осіни́ покро́вом Твої́м строї́телей, благотвори́телей і благоукраси́телей єя́. О Всечестна́я на́ша Ма́ти, Ігу́меніє всіх правосла́вних оби́телей і і́ночеськаго житія́ Покрови́тельнице, пребу́ди неотсту́пна от оби́телі сея́, су́щаго достоя́нія Твоєго́, і всеси́льними Твої́ми моли́твами покри́й і заступи́ зді подвиза́ющихся, от вся́ких бід і нужд, помози́ уста́ви преподо́бних оте́ць непоколеби́мо сохрани́ти, ізба́ви от паде́ній гріхо́вних, да́руй нам дух сокруше́нія і смире́нія, наста́ви і́ноков в ісполне́нії обі́тов і всіх христия́н в ді́ланії за́повідей Бо́жиїх. Прийми́ смире́нноє моле́ніє на́ше, согрі́й нас любо́вію Твоє́ю і нікогда́же отступа́й от нас, да не оскуді́єть ві́ра в нас грі́шних, і да сподо́бимся вни́ти в Ца́рствіє Небе́сноє, в не́мже возвели́чим Тя, Ма́тер на́шу Всепі́тую, і просла́вим Си́на Твоєго́ і Бо́га на́шего, со Безнача́льним Єго́ Отце́м, і Пресвяти́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Богоро́дице Ді́во, на Твою́ іко́ну пресві́тлую взира́юще, ра́дуємся, пред не́ю бо на о́строві Валаа́мі мольби́ усе́рдно моля́щихся ісполня́ються; усли́ши, Пречи́стая, і нас моля́щих Ті ся, утверди́ нас во ві́рі і любві́, і іспроси́ ми́рові мир і душа́м на́шим ве́лію ми́лость."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Выдропуська Одигітрія»","e":"Akathist to the Theotokos before her icon “Vydropusk Hodegetria”","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от родо́в дре́вніх Пресвята́я Богоро́дице Одиги́тріє, Засту́пнице всіх к Тебі́ притека́ющих, ско́рая Усли́шательнице і ми́лостивая Предста́тельнице, со умиле́нієм припа́даєм ко Твоєму́ Пречи́стому о́бразу і глаго́лем: отве́рзи о́чі серде́ць на́ших, гріхми́ омраче́нния, во є́же позна́ти нам путь покая́нія. Ті́мже благода́рственні вопіє́м Ті:","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Ікос 1","ps":["А́нгели і Арха́нгели воспіва́ють Тя ви́ну: ра́дуйся, Цари́це Небесе́ і землі́, Ти бо честні́йши всіх безпло́тних сил яви́лася єси́, я́ко із Тебе́ воплоти́ся Госпо́дь наш, до́лу снизше́дий спасе́нія на́шего ра́ди. Ни́ні же, я́ко усе́рдная Моли́твенниця о ро́ді христия́нстім, путеводи́ши всіх чту́щих Тя в селе́нія го́рняя, да взива́єм Ті си́це:","Ра́дуйся, Путеводи́тельнице блага́я;","ра́дуйся, ка́ющихся Предста́тельнице.","Ра́дуйся, Світ спасе́нія ми́ру яви́вшая;","ра́дуйся, із мра́ка неві́рія ізводя́щая.","Ра́дуйся, две́рі покая́нія нам отверза́ющая;","ра́дуйся, Богові́дінію нас науча́ющая.","Ра́дуйся, в скорбі́х ми́лостивая Уті́шительнице;","ра́дуйся, в час су́дний всемо́щная Хода́тайце.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще на мі́сті пусти́нном, іді́же бі храм во і́м'я великому́ченика Бо́жия Гео́ргия, ди́вную іко́ну Твою́ Одиги́трію, в пла́мені стра́шном невреди́мо преби́вшую, і обрі́тше ту с ве́лією ра́достію, жи́теліє ві́си Видропу́ськия возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в син боя́рський і во́їн вели́каго кня́зя моско́вськаго Іоа́нна іко́ну Твою́, я́ко сокро́вище драго́є, де́рзостно похи́ти ю і пренесе́ во о́тчину свою́, град Му́ром, і та́мо поста́ви ве́лію святи́ню сію́ во хра́мі святи́теля Никола́я, да і му́ромстії лю́діє воспою́ть Тя, глаго́люще сицева́я:","Ра́дуйся, іко́ну Твою́ із огня́ невреди́мо ізве́дшая;","ра́дуйся, пла́мень душетлі́нних страсте́й в нас угаша́ющая.","Ра́дуйся, ско́рая Помо́щнице Тя призива́ющих;","ра́дуйся, Заступле́ніє Тя почита́ющих.","Ра́дуйся, междоусо́бния бра́ні ско́ро утиша́ющая;","ра́дуйся, братолю́біє і мир водворя́ющая.","Ра́дуйся, землі́ Ру́ськия ди́вноє сокро́вище;","ра́дуйся, я́ко по всей вселе́нній сла́виться і́м'я Твоє́.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго возбуди́ вітр вели́к і стра́шен зіло́, трус крі́пок і гром си́лен, єгда́ син боя́рський Тя, Цари́це Небе́сная, Плі́нницею найменова́в, повелі́ моле́ніє соверши́ти пред іко́ною Твоє́ю Одиги́трією. І а́біє разверзо́шася кро́ви церко́вния, і падо́ша на лице́ своє́ свяще́нник і всі лю́діє, узрі́вше іко́ну сію́ на возду́сі уноси́му дале́че. Ми же, ве́лію чу́ду сему́ ужаса́ющеся, вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Возиме́в сокруше́ніє серде́чноє о неразу́мії своє́м, син боя́рський возопи́: Уви́ мні, безу́мному! Ка́ко дерзну́х аз, грі́шний, пліни́ти Ту, Є́юже весь мир свободи́ся от гріха́ і рабо́ти вра́жия! Ни́ні посра́мленний де́рзостію своє́ю, ка́юся і молю́ Тя, Пречи́стая, даждь мі неосужде́нно воспіва́ти Тя си́це:","Ра́дуйся, мир Рождество́м Твої́м свободи́вшая;","ра́дуйся, чу́до всім на покая́ніє сугу́боє откри́вшая.","Ра́дуйся, я́ко іко́на Твоя́ а́нгели бисть носи́ма;","ра́дуйся, я́ко святи́ня сія́ і челові́ки чти́ма.","Ра́дуйся, го́рдим вразумля́ющеє противле́ніє;","ра́дуйся, смире́нним благода́ті низпосла́ніє.","Ра́дуйся, к созерца́нію сла́ви Бо́жия нас возвиша́ющая;","ра́дуйся, к покая́нію серде́чному нас обраща́ющая.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 4","ps":["Бу́рею стра́нною восхище́на бисть чу́дная іко́на Одиги́трії і, а́ки на крилу́ ві́треню Небе́сними Си́лами носи́мая, по тріє́х мі́сяціх із гра́да Му́рома во весь Видропу́ськую, па́ки возврати́ся. Ті́мже зря́ще святи́ню сію́, на возду́сі носи́му, селя́нин Флор удиви́ся, понома́р же Фео́дор, во олтари́ на святі́м престо́ле о́ную обрі́т, созива́ше вся лю́ди, благода́рні вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша о чуде́сном Твоє́м отше́ствії, син боя́рський, в покая́ніє прише́д, і воста́в, і́де па́ки во весь Видропу́ськую, посто́м в нище́тні о́бразе себі́ утружда́я іспові́дати безу́міє своє́, і обрі́те та́мо проще́ніє, сле́зно взива́я си́це:","Ра́дуйся, согріша́ющия ско́ро вразумля́ющая;","ра́дуйся, ка́ющіяся от Себе́ не отрева́ющая.","Ра́дуйся, прелага́ющая сле́зи на весе́ліє;","ра́дуйся, подаю́щая ве́ліє ра́дованіє.","Ра́дуйся, наде́жная Засту́пнице на Тя упова́ющим;","ра́дуйся, ско́рая Помо́щнице к Тебі́ притека́ющим.","Ра́дуйся, я́ко от Тебе́ чудеса́ мно́гая ісхо́дять;","ра́дуйся, я́ко о Тебі́ вся́кая твар ра́дується.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ уподо́бися пречестна́я іко́на Твоя́, Одиги́тріє, та бо приведе́ волхви́ к верте́пу Бо́жию, пред Твої́м же святи́м о́бразом ві́рнії прекло́ньше колі́на, благогові́йно воспіва́ють: упра́ви, милосе́рдная Ма́ти, путь житія́ на́шего ко Оте́честву Небе́сному, зане́же прише́льці єсьми́ в ми́рі сем, да взива́єм Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще ди́вную іко́ну твою́ Одиги́трію, землі́ Тверсько́й дарова́нную, і благослове́ніє Ма́тернєє подаю́щую вся́кому путеше́ствовати хотя́щему, мо́лим Тя, да не то́кмо от зла́го обстоя́нія ни ізба́виши і ці́ли сохрани́ши, но і ду́ші на́ша ко благоугожде́нію Бо́жию напра́виши. Ті́мже і ми, пречу́днаго покро́ва Твоєго́ сподо́битися жела́юще, благода́рственно вопіє́м Ті:","Ра́дуйся, притека́ющих к Тебі́ ти́хоє приста́нище;","ра́дуйся, упова́ющим на Тя спаси́тельная крі́посте.","Ра́дуйся ко го́рнім селе́нієм ум наш возводя́щая.","Ра́дуйся, до́льнія суєти́ отріва́ти нас подвиза́ющая.","Ра́дуйся, не́мощі і я́зви врачева́ніє;","ра́дуйся, іскуше́нія і недоумі́нія істребле́ніє.","Ра́дуйся, путі́ пра́вия благословля́ющая;","ра́дуйся, єди́ному Го́споду служи́ти устремля́ющая.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дниця бисть іко́на Твоя́, Путеводи́тельнице, мно́жества ми́лостей Твої́х, я́же ізлія́ла єси́ притека́ющим к Тебі́: ско́рбнії бо прихожда́ху, моле́ніє принося́ще милосе́рдію Твоєму́; приє́млюще же ско́ро ізбавле́ніє от многообра́зних не́мощей душе́вних, вку́пі і тіле́сних, пові́даху всю́ду заступле́ніє і чудеса́ Твоя́, со умиле́нієм вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во ві́си Видропу́ськой благода́ть от іко́ни Твоєя́, Влади́чице: среди́нноє бо мі́сто яви́ся весь сія́ ца́рствующей Москві́ і Петро́ву гра́ду, освяща́я і благословля́я зе́млю на́шу Ру́ськую, мо́лиши бо неуси́пно Си́на Своєго́ Преві́чнаго Бо́га о дарова́нії страні́ на́шей ми́ра і благоде́нствія, ізбавле́нія от междоусо́бния бра́ні і вся́кия ско́рби і печа́лі. Ті́мже славосло́вим Тя си́це:","Ра́дуйся, честни́м Твої́м омофо́ром держа́ву на́шу покрива́ющая;","ра́дуйся, Русь Святу́ю Свої́м уді́лом імену́ющая.","Ра́дуйся, от літ дре́вніх во бранеіх со іноплеме́нники помога́ющая;","ра́дуйся, призива́ющим і́м'я Твоє́ побі́ди умножа́ющая.","Ра́дуйся, прави́телі і вла́сті умудря́ющая;","ра́дуйся, судьби́ Оте́чествія ко бла́гу устроя́ющая.","Ра́дуйся, по́моще на́ша і утвержде́ніє;","ра́дуйся, упова́ніє на́ше і вразумле́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 7","ps":["Хотя́ Госпо́дь яви́ти человіколю́біє Своє́ не то́кмо ві́си Видропу́ськой, но і всей правосла́вній Ру́ськой землі́, устро́ї пренесе́ніє іко́ни сея́ по градо́м і ве́сем, во оби́телі і́ночествующих і до́ми богобоя́зненних христия́н. Ті́мже, я́ко Саму́ Цари́цю Небе́сную сію́ іко́ну чту́ще, восхваля́єм с любо́вію твори́мая от нея́ чудеса́, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий істо́чник ми́лостей яви́ся іко́на Твоя́ Одиги́трія, стра́ждущим бо осла́би посила́ються, немощству́ющим здра́віє, плі́нником свобожде́ніє, заблу́ждшим обраще́ніє, коєму́ждо позна́ніє вели́чія Твоєго́ да́рується, зане́ моли́тва, я́же к Тебі́, Пречи́стая, возноси́мая, непрело́жно усли́шана бива́єть. Ті́мже і заступле́ніє Твоє́ многоси́льноє обріта́єм і благодаря́ще воспіва́єм Ті си́це:","Ра́дуйся, на́ше всемо́щноє заступле́ніє;","ра́дуйся, от вся́кия напа́сти огражде́ніє.","Ра́дуйся, си́рих і убо́гих прия́телище;","ра́дуйся, дів і вдови́ць честни́х прибі́жище.","Ра́дуйся, супру́гом целому́дріє і єдиноми́сліє подава́ющая;","ра́дуйся, ча́да во благоче́стії і послуша́нії жи́ти наставля́ющая.","Ра́дуйся, проше́нія благогові́йних моли́твенников ісполня́ющая;","ра́дуйся, лю́тия біди́ от нас отгоня́ющая.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є соверша́ющих, огради́ нас Твої́м заступле́нієм, Пречи́стая Ді́во, ізведи́ із глубини́ гріхо́в і бу́ри отча́янія, мо́ря жите́йськаго пучи́ну помози́ невла́жними проіти́ стопа́ми, ми́сленнаго фарао́на потопля́ющи, да спаса́ємі Тобо́ю дерзнове́нно возопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся во ви́шніх пребива́ющи, і нас земноро́дних не оста́вила єси́, Влади́чице: коєго́ждо бо воздиха́нія серде́чная сли́шиши і призира́єши на проше́нія ві́рно взива́ющих к Тебі́: ни́ви се́льния благословля́єши і бразди́ жи́тния освяща́єши, во є́же би́ти до́брим плодо́м от землі́ на́шея, ісполня́ющи моле́нія люде́й Твої́х о хлі́бі насу́щном, вопію́щих Ті си́це:","Ра́дуйся, благорастворе́ніє возду́хов низпосила́ющая;","ра́дуйся, во гла́ді су́щих нас не оставля́ющая;","Ра́дуйся, усе́рдних ді́лателей моле́нія прийма́ющая;","ра́дуйся, на небе́сния сокро́вищници упова́ти тіх подвиза́ющая.","Ра́дуйся, незри́моє ві́ри сі́мен прозябе́ніє;","ра́дуйся, зе́рен благоче́стія ізря́дноє насажде́ніє.","Ра́дуйся, плод стори́чний приноси́ти нас сподобля́ющая;","ра́дуйся, пи́щею небе́сною нас пита́ющая.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ безпло́тних воспіва́єть немо́лчно вели́чія Твоя́, Ді́во. А́нгели бо незри́мо поклоне́ніє пред Твоє́ю іко́ною творя́ще, фимія́мом небе́сним пред не́ю кажде́ніє соверша́ють. Ми же, земноро́днії, ка́ко досто́йно восхвали́ти Тя возмо́жем? І́бо вся́коє благодаре́ніє не превозмога́єть мно́жества ми́лостей Твої́х. Ті́мже і припа́дающе к Твоєму́ свято́му о́бразу, іді́же Ти держи́ши на рука́х Свої́х Богомладе́нця Христа́, хвале́бную піснь воспої́м Зижди́телю всіх: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоумі́ють, ка́ко возмо́жно із'ясни́ти мно́жества чуде́с, от іко́ни Твоєя́ ізлива́ємая, ти бо путі́ заблу́ждших ісправля́єши, малові́рния вразумля́єши. Ми же, не дерза́юще іспита́ти вели́чія Твоя́, благогові́йно воспіва́єм Ті си́це:","Ра́дуйся, і́стинния ві́ри Наста́внице;","ра́дуйся, наде́жди несумні́нния Пода́тельнице.","Ра́дуйся, любве́ нелицемі́рния взиска́ніє;","ра́дуйся, му́дрости небе́сния стяжа́ніє.","Ра́дуйся, оте́чеськаго преда́нія Храни́тельнице;","ра́дуйся, ві́ри святи́х апо́стол Защи́тнице.","Ра́дуйся, є́ресі тьмочи́сленния разоря́ющая;","ра́дуйся, пра́воє богопочита́ніє насажда́ющая.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ от поруга́нія іко́ну Твою́ Одиги́трію, благочести́вий селя́нин Стефа́н, ви́дя, я́ко безу́мнії отсту́пници ві́ри оте́чеськия восхоті́ша вве́ргнути во огнь святи́ню хра́ма Видропу́ськаго, откупи́ ю у безбо́жних за єди́н дров'яни́й воз, і благогові́йно внесе́ в дом свой, благодаря́ Бо́га: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая яви́ся страні́ на́шей іко́на Твоя́, Влади́чице, я́ко Ти нікогда́же оставля́єши ми́лостивноє Своє́ о наро́ді христия́нстім попече́ніє, а́ще бо і разоре́ни і пору́гани хра́ми Бо́жії би́ша, і нечести́вії лю́діє святи́ні поху́лиша і істреби́ша. Но поми́ловала єси́ ни і благослови́ла єси́ пребива́ти іко́ні Твоє́й Одиги́трії в землі́ Тверсько́й в дому́ благочести́ваго Стефа́на со Матро́ною і ча́дами їх. Богомо́льці же Твої́ та́йно прихожда́ху в дом сей, і припа́дающе к наде́жной пред Бо́гом Засту́пнице, сле́зно взива́ху Ті си́це:","Ра́дуйся, во іспові́данії Правосла́вія нас утвержда́ющая;","ра́дуйся, благодари́ти за ско́рби і тісноти́ вразумля́ющая.","Ра́дуйся, безу́мія богобо́рцев обличе́ніє;","ра́дуйся, омраче́нних безбо́жієм ісціле́ніє.","Ра́дуйся, усе́рдних служи́телей Свої́х утіша́ющая;","ра́дуйся, о́ним оби́телі Небе́сния уготовля́ющая.","Ра́дуйся, ми́лостиваго всепроще́нія істо́чниче;","ра́дуйся, ві́рним моли́тви за враги́ дарова́ніє.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє вознося́ доброгла́сноє пред честно́ю іко́ною Твоє́ю, усе́рдно про́сим Тя, Богома́ти, усли́ши моле́нія на́ша, к Тебі́ возноси́мая. Умоли́ Влади́ку Христа́ ізба́вити оте́чество і наро́д наш от поги́белі і сохрани́ в нас ві́ру правосла́вную, да со умиле́нієм благода́рственно єди́нім се́рдцем і єди́німи усти́ вознесе́м хвалу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприє́мной свіщи́ уподо́бися іко́на Твоя́ Видропу́ськая, благода́тію от нея́ ізлія́нною ди́вно показу́ющи нам та́йни боже́ственния і науча́ющи а́нгельському житію́. Ті́мже і во́їна Крони́да, і́же споспі́шествовал єсть сопру́жником честни́м Стефа́ну і Матро́не сохрани́ти о́браз Твой святи́й, препроводи́ла єси́ во оби́тель Пско́во-Пече́рськую, і та́мо і́ночеський о́браз восприя́ти с і́менем Нафана́їл сподо́била єси́. Сей же моли́тви ді́латель усе́рдний, му́дростію і му́жеством преукраше́нний, до послі́дняго іздиха́нія іспові́даше Твоє́ благо́є о нас попече́ніє, вопія́ Ті похвали́ сицеви́я:","Ра́дуйся, єва́нгельським путе́м ше́ствовати нас побужда́ющая;","ра́дуйся, во́лю Бо́жию взиска́ти і твори́ти повеліва́ющая.","Ра́дуйся, і́ночеськаго о́браза небе́сная Покрови́тельнице;","ра́дуйся, оби́телей земни́х, во о́браз оби́телей го́рніх, до́брая Устрої́тельнице.","Ра́дуйся, непреста́нную моли́тву стяжева́ти назида́ющая;","ра́дуйся, ума́ і се́рдця чистоту́ созида́ющая.","Ра́дуйся, благогові́йно пред Бо́гом ходи́ти воскриля́ющая;","ра́дуйся, да́же до са́мия сме́рті обі́ти мона́шеськия храни́ти укріпля́ющая.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 12","ps":["Благода́тію боже́ственною защити́ ни, Ді́во Непоро́чная, от пліне́нія врагу́ па́дшия во́лі на́шея і ко́зней дия́вольських, і я́ко младе́нці а́лчущия, ні во что́же вміня́юще би́сер і зла́то, прини́чуть ко млеку́ ма́терню, та́ко і ду́ші на́ша умудри́ іска́ти упокоє́нія то́кмо во Єди́ном Го́споді на́шем, да позна́вше Єго́ бла́гость, воспоє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще заступле́ніє Твоє́, Пресвята́я Влади́чице, мо́лим Тя: бу́ди нам блага́я предста́тельниця в о́ний день стра́шний, єгда́ во сла́ві при́йдеть Пра́ведний Судія́, Син і Бог Твой, да не уподо́бимся смоко́вниці безпло́дней, да не сопричте́мся лука́вому рабу́, но воспри́ймем часть му́дрих дів, со світи́льники горя́щими, іспо́лненними єле́я ми́лості і до́брих діл, велича́юще Тя та́ко:","Ра́дуйся, упова́ніє на́ше в день су́дний;","ра́дуйся, умоле́ніє за ни в час іспита́нія.","Ра́дуйся, огня́ неугаси́маго ізбавля́ющая;","ра́дуйся, во ізбра́нноє ста́до Христо́во нас собира́ющая.","Ра́дуйся, ду́шу полага́ти за дру́ги призива́ющая;","ра́дуйся, сердця́ на́ша ми́лующими би́ти сотворя́ющая.","Ра́дуйся, Ти бо єси́ Хода́тайця поми́лованія грі́шником ка́ющимся;","ра́дуйся, Ти бо вво́диши ві́рния в ра́дость Го́спода Твоєго́.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 13","ps":["О Предста́тельниці на́ша непости́дная, Пресвята́я Богоро́дице Одиги́тріє, прийми́ на́ше возноси́моє к Тебі́ моле́ніє, і от вся́каго зла сохрани́, к доброді́телі упра́ви, путі́ пра́ви сотвори́ і проще́нія гріхо́в на́ших іспроси́, да взира́юще на святу́ю Твою́ іко́ну, воззове́м к щедро́там Отця́ Небе́снаго: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели і Арха́нгели воспіва́ють Тя ви́ну: ра́дуйся, Цари́це Небесе́ і землі́, Ти бо честні́йши всіх безпло́тних сил яви́лася єси́, я́ко із Тебе́ воплоти́ся Госпо́дь наш, до́лу снизше́дий спасе́нія на́шего ра́ди. Ни́ні же, я́ко усе́рдная Моли́твенниця о ро́ді христия́нстім, путеводи́ши всіх чту́щих Тя в селе́нія го́рняя, да взива́єм Ті си́це:","Ра́дуйся, Путеводи́тельнице блага́я;","ра́дуйся, ка́ющихся Предста́тельнице.","Ра́дуйся, Світ спасе́нія ми́ру яви́вшая;","ра́дуйся, із мра́ка неві́рія ізводя́щая.","Ра́дуйся, две́рі покая́нія нам отверза́ющая;","ра́дуйся, Богові́дінію нас науча́ющая.","Ра́дуйся, в скорбі́х ми́лостивая Уті́шительнице;","ра́дуйся, в час су́дний всемо́щная Хода́тайце.","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нная от родо́в дре́вніх Пресвята́я Богоро́дице Одиги́тріє, Засту́пнице всіх к Тебі́ притека́ющих, ско́рая Усли́шательнице і ми́лостивая Предста́тельнице, со умиле́нієм припа́даєм ко Твоєму́ Пречи́стому о́бразу і глаго́лем: отве́рзи о́чі серде́ць на́ших, гріхми́ омраче́нния, во є́же позна́ти нам путь покая́нія. Ті́мже благода́рственні вопіє́м Ті:","Ра́дуйся, Богоро́дице Одиги́тріє, на спасе́нія стезі́ нас наставля́ющая."]},{"h":"Молитва","ps":["О Цари́це Небесе́ і землі́, Влади́чице всеми́лостивая, Одиги́тріє всечестна́я, Предста́тельнице на́ша усе́рдная, при Кресті́ Си́на Твоєго́ і Бо́га всинови́вшая весь па́дший род челові́чеський і по успе́нії Своє́м не оста́вившая нас си́рих і безнаде́жних! Мо́лим Тя, Всенепоро́чная, благода́ть Твою́ не отими́ от ка́ющихся рабо́в Твої́х і упра́ви вся, я́ко Ма́ти Преблага́я: защити́ оте́чество на́ше, ві́ру правосла́вную сохрани́, вла́сті умудри́, ієре́ї укріпи́, ві́рним лю́дем Твої́м по́мощ неоску́дную да́руй, ю́ния вразуми́, ста́рость уті́ши, боля́щия ісціли́, отча́янния возста́ви, заблу́ждшия обрати́ і всім целому́дріє і крі́пость ісхода́тайствуй – Ти бо єси́ блага́я Путеводи́тельниця і милосе́рдная Засту́пниця, к Тебі́ припа́даєм і мо́лим Тя: не отве́ржи нас, но іспроси́ нам до́браго отві́та на Стра́шнім Суди́лищі, да не осу́димся по гріхо́м і беззако́нієм на́шим, но ми́лость улучи́м по безмі́рному человіколю́бію Го́спода і Спаси́теля на́шего Ісу́са Христа́, Єму́же сла́ву і поклоне́ніє возсила́єм, со Безнача́льним Єго́ Отце́м, і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Твоя́, Богоро́дице Ді́во, святи́ня, / я́ко омофо́ром нас от бід покрива́ющая, / яви́ся в о́блаці с шу́мом летя́щая / к ра́досте ві́си Видропу́ськой / єгда́ із нея́ ісхищена бисть / ни́ні да́руєши нам благода́ть многомо́щную / с не́юже і чудеса́ Твоя́, // і подає́ши нам ве́лію ми́лость."]},{"h":"Кондак, глас 6","ps":["Во спасе́ніє нам ро́ждшая Безнача́льного, / і яви́вшая нам своє́ заступле́ніє безконе́чноє, / Сі́м'я До́броє Хлі́ба же́ртвеннаго преломле́нія / безсі́менно во утро́бі пречи́стій возрасти́вшая, / і о́бразом Твої́м Видропу́ським благода́ть ми́ру яви́вшая, // Ді́во, спаса́й Тя велича́ющия."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Овіновська»","e":"Akathist to the Theotokos before her icon “Ovinovo”","secs":[{"h":"Кондак 1","ps":["Ізбра́нная Ді́во Марі́є, Цари́це на́ша Богоро́дице, осіни́вшая страну́ Га́личськую ангелохва́льним явле́нієм іко́ни Своєя́, благода́рственная возсила́єм Ті раби́ Твої́, Влади́чице:","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Ікос 1","ps":["А́нгел со́нми на Небесі́ і христия́н мно́жества на землі́ ра́дуються о Тебі́, Ма́ти на́ша, і ра́достно прино́сять Ті цілова́ніє сицево́є: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю. Ми же, зна́меніє ви́дяще благоволе́нія Твоєго́ к землі́ сей, со умиле́нієм взива́єм:","Ра́дуйся, лю́дем гра́да Га́лича небе́сноє утіше́ніє;","ра́дуйся, і́ночествующим оби́телі Нико́льськия покро́в і защище́ніє.","Ра́дуйся, преподо́бнаго Паї́сія укріпле́ніє;","ра́дуйся, всего́ собо́ра святи́х Га́личських увеселе́ніє.","Ра́дуйся, іко́ною Твоє́ю в ско́рбіх всім помога́ющая;","ра́дуйся, во дні і в нощі́ оби́тель і град покрива́ющая.","Ра́дуйся, от бід страну́ на́шу огражда́ющая;","ра́дуйся, печа́ль на́шу в ра́дость претворя́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 2","ps":["Ви́дим, Свята́я Ді́во, Твоє́ ми́лостивоє промишле́ніє, я́ко покро́в Боже́ственний, распросте́ршійся над гра́дом Га́личем в преди́вней любві́ Матери́нстей Твоє́й к лю́дем. Ти, Всеми́лостивая Госпоже́, яви́ла єси́ іко́ну Твою́ во оби́телі Нико́льськой, да сози́ждеться храм во і́м'я Успе́нія Твоєго́, а́може лю́діє і і́ноці да притека́ють і со слеза́ми воспіва́ють піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума преви́шшему явле́нію іко́ни Твоєя́ ужа́сся, благочести́вий кти́тор, боля́рин Іоа́нн, о́бразу Твоєму́, Влади́чице, поклони́ся до землі́, лю́діє же с тре́петом вопія́ху к Богоро́диці:","Ра́дуйся, Одиги́тріє, чи́ньми А́нгельськими носи́мая;","ра́дуйся, Купино́ Неопали́мая.","Ра́дуйся, вся́кая сумні́нія боля́рина О́винова отри́нувшая;","ра́дуйся, но́воє мі́сто пребива́нія Своєго́ показа́вшая.","Ра́дуйся, в день Успе́нія Твоєго́ двіма́ А́нгелома зді явля́ємая;","ра́дуйся, Матери́нською любо́вію всіх согріва́ющая.","Ра́дуйся, всіх скорб'я́щих ра́достію осіява́ющая;","ра́дуйся, прише́ствієм Твої́м град Твой прославля́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укріпи́ся от Тебе́, Всеблага́я Богоро́дице, кти́тор, єгда́ усли́ша Боже́ственний глас об устроє́нії хра́ма в честь Успе́нія Твоєго́, Пречи́стая Ді́во, і со благогові́нієм облобиза́ о́браз Твой, благода́рственно поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія, Богома́ти, всім лю́дем ру́ку по́мощі простира́єши. Сего́ ра́ди і ігу́мен оби́телі сея́ преподо́бний Паї́сій, на Тя упова́ніє возложи́в, благогові́йнаго стра́ха і ра́дости от виді́нія сего́ іспо́лненний, пома́зоваше себе́ і бра́тію єле́єм от іко́ни Твоєя́, і те́плі возсила́ше Тебі́ такова́я:","Ра́дуйся, я́ко іко́на Твоя́, сві́тлими А́нгели носи́мая, возду́х освяти́;","ра́дуйся, я́ко о́браз Твой всю страну́ Га́личськую просвіти́.","Ра́дуйся, всяк во́зраст посіща́ющая;","ра́дуйся, младе́нці, я́ко Ма́ти, окормля́ющая.","Ра́дуйся, сироти́ і вдови́ці призрева́ющая;","ра́дуйся, і́ночествующих благода́тно охраня́ющая.","Ра́дуйся, благу́ю мисль на се́рдці полага́ющая;","ра́дуйся, люде́й Твої́х Ра́досте неча́янная.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 4","ps":["Бу́рею наше́ствія междоусо́биць лю́тих Га́личськая земля́ поколеба́ся, сро́дниці вразі́ соді́яшася і кня́зіє Васи́лій і Гео́ргій Га́личський друг на дру́га возста́ша. Ти же, Всеми́лостивая Ма́ти, яви́вшая ми́ру всему́ о́браз терпі́нія і злострада́нія при Кресті́ Си́на Твоєго́, научи́ лю́ди га́личськия в пещі́ іскуше́ній і бід взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав о Твоє́м, о Всепі́тая Ма́ти, гряду́щем отше́ствії із гра́да Га́лича, о ізнесе́нії іко́ни Ови́новськия во град Москву́ кня́зем Васи́лієм Те́мним, преподо́бний Паї́сій со слеза́ми увіща́ єго́ о́браз оста́вити. Оба́че князь, не внима́я воздиха́нієм серде́чним, повелі́ со стра́жею соверши́ти пренесе́ніє. Лю́діє же всі, почита́ющії пречи́стий лик Твой, Богома́ти, вопія́ху к Тебі́, Цари́це Небесе́ і землі́:","Ра́дуйся, град Га́лич я́ко ма́лий Назаре́т Твої́м пребива́нієм возвели́чившая;","ра́дуйся, проше́нія люде́й землі́ Га́личськия во бла́го ісполня́ющая.","Ра́дуйся, всіх си́рих защища́ющая;","ра́дуйся, всіх ві́рних утіша́ющая.","Ра́дуйся, іко́ною Твоє́ю Ови́новською Москву́ посіти́вшая;","ра́дуйся, лю́дем моско́вським благослове́ніє істочи́вшая.","Ра́дуйся, любо́в Твою́ к оби́телі возвраще́нієм яви́вшая;","ра́дуйся, мир глубо́кий враждова́вшим дарова́вшая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ зрим іко́ну Твою́, о ми́лостивая Ді́во, ю́же хотя́щи па́ки возврати́ти га́личськой Нико́льськой оби́телі, Пречи́стая Богома́ти, рекла́ єси́ преподо́бному Паї́сію: прийми́ іко́ну Мою́. Вшед нау́тріє во храм і обрі́т іко́ну на мі́сті своє́м стоя́щую, с тре́петом і со слеза́ми благода́рними усти́ воззва́ преподо́бний к Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше возвраще́ніє чу́дноє іко́ни Твоєя́, я́же мно́гою стра́жею охраня́єма бі во Успе́нськом собо́ре гра́да Москви́, оба́че си́лою Бо́жиєю во єди́ну нощ пренесе́ся во оби́тель Нико́льськую, всі лю́діє землі́ Га́личськия благода́рні возопи́ша Богоро́дице:","Ра́дуйся, єди́ная Ра́досте на́ша;","ра́дуйся, єди́ная на́ша Отра́до.","Ра́дуйся, к землі́ Га́личськой благоволе́ніє;","ра́дуйся, от междоусо́бних бра́ней ізбавле́ніє.","Ра́дуйся, в ско́рбіх ско́ро помога́ющая;","ра́дуйся, ві́рних і малове́рних от бід спаса́ющая.","Ра́дуйся, честни́м Покро́вом Твої́м нас осіня́ющая;","ра́дуйся, печа́ль на́шу в ра́дость претворя́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть земля́ Га́личськая преди́вная чудеса́ Твоя́, Богома́ти, я́же на ві́рния чрез святу́ю іко́ну Твою́ Ови́новськую благода́тно ізлива́єши: боля́щим ісціле́нія подає́ши і всім в земни́х іспита́ніїх по́мощ Твою́ простира́єши, вопію́щим к Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ но́вая благода́ть от іко́ни Твоєя́ Ови́новськия немерца́ющею заре́ю чуде́с, Пресвята́я Ді́во; і оби́тель Нико́льськая но́воє і́м'я прия́т в честь Успе́нія Твоєго́, в не́йже і́ноці і всі лю́діє, обра́дованнії Твої́м заступле́нієм, с весе́лієм вопію́ть Тебі́ сицева́я:","Ра́дуйся, о поми́лованії нас грі́шних умоля́ющая;","ра́дуйся, на путь смире́нія і терпі́нія наставля́ющая.","Ра́дуйся, оскуді́ніє оби́телі Твоєя́ восполня́ющая;","ра́дуйся, скорб на́шу в ра́дость претворя́ющая.","Ра́дуйся, от враго́во ви́димих і неви́димих защища́ющая;","ра́дуйся, от мно́гих бід нас ізбавля́ющая.","Ра́дуйся, вся́кий неду́г ісціля́ющая;","ра́дуйся, от паде́нія нас охраня́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 7","ps":["Хотя́ проще́ніє прия́ти, князь Васи́лій стра́ха Бо́жия іспо́лнися, єгда́ усли́ша о пренесе́нії небе́снім чудотво́рния іко́ни Ови́новськия із гра́да Москви́ в Га́лич: сего́ ра́ди со слеза́ми припаде́ ко о́бразу Богома́тере; усли́шан же в моле́нії своє́м бив, те́плі возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє бисть в преді́ліх Га́личських, єгда́ князь Васи́лій во іскупле́ніє своєя́ вини́ повелі́ устро́їти но́вую оби́тель і храм во і́м'я Васи́лія Вели́каго. Ті́мже і ми взива́єм к Богоро́диці:","Ра́дуйся, чу́дно оби́тель і́ночеськую созда́вшая;","ра́дуйся, хра́му свята́го Васи́лія в ней би́ти ізво́лившая.","Ра́дуйся, благослове́ніє подвиза́ющимся дарова́вшая;","ра́дуйся, ві́рно живу́щия любо́вію Твоє́ю утіша́ющая.","Ра́дуйся, прило́ги вра́жия от оби́телей отража́ющая;","ра́дуйся, прило́ги ми́сленния отгоня́ти науча́ющая.","Ра́дуйся, на труди́ і по́двиги і́ноки вразумля́ющая;","ра́дуйся, па́м'ять сме́ртную стяжава́ти наставля́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці єсьми́ в ми́рі сем ми бре́ннії, ті́мже мо́лим Тя, Богома́ти, і про́сим: не лиши́ нас Твоєя́ по́мощі і заступле́нія, да сподо́бимся Тебі́ хвале́бную пі́ти піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім, в ско́рбіх жите́йських обурева́ємим, воі́стину яви́ся благода́тная отра́да о́браз Твой, імену́ємий Ови́новський, к нему́же ми ни́ні приходя́ще, вопіє́м Ті со умиле́нієм:","Ра́дуйся, бід і напа́стей незри́моє ізбавле́ніє;","ра́дуйся, грі́шников ка́ющихся проще́ніє.","Ра́дуйся, усе́рдноє о нас пред Бо́гом заступле́ніє;","ра́дуйся, єжеча́сноє всіх ві́рних охране́ніє.","Ра́дуйся, неду́гов тіле́сних ісціле́ніє;","ра́дуйся, от уз де́монських свобожде́ніє.","Ра́дуйся, воздиха́нія на́ша не отверга́ющая;","ра́дуйся, щедро́ти і ми́лості Твоя́ на нас ізлива́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 9","ps":["Вся́коє тща́ніє о хране́нії Твоєго́ ди́внаго о́браза і́ноці оби́телі Успе́нськия да і́муть Твоє́ю по́мощію, Богома́ти, і, подвиза́ющеся в пості́, моли́тві і бді́нії, но́щію і днем мо́ляться пред ним і Бо́гу вопію́ть: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство на́ше не довлі́єть ко ізглаго́ланію всіх чуде́с от Твоєя́ іко́ни, Богоро́дице Ді́во, ві́домих нам і неві́домих. Но Ти, я́ко милосе́рдная Ма́ти, научи́ нас взива́ти к Тебі́ ві́рно:","Ра́дуйся, благода́тная Богоро́дице Ді́во;","ра́дуйся, ми́лости пода́тельнице.","Ра́дуйся, те́плая о нас Хода́тайце;","ра́дуйся, всеблага́я Врата́рнице.","Ра́дуйся, ко го́рнему ми́ру ум наш направля́ющая;","ра́дуйся, дух наш устремля́ти к Бо́гу науча́ющая.","Ра́дуйся, сердця́ на́ша моли́твою просвіща́ющая;","ра́дуйся, ти́хоє і безм'яте́жноє житіє́ нам да́рующая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи многоско́рбния лю́ди от бід не то́кмо во гра́ді Га́личе, но і в сто́льнем гра́де Москві́, і во іни́х граді́х, ве́сіх і оби́теліх, ізлива́єши благода́ть от іко́ни Твоєя́ Ови́новськия всім ві́рним, вопію́щим к Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і́ночеському ли́ку, Пречи́стая Ді́во Марі́є, і до сконча́нія ві́ка наде́жду несокруши́мую і́мами о святі́й іко́ні Твоє́й. Ті́мже, Ма́ти Бо́жия, с лю́бовію і ра́достію зове́м Тебі́:","Ра́дуйся, я́ко чистоті́ і цілому́дрію нас науча́єши;","ра́дуйся, я́ко по́мисли на́ша просвіща́єши.","Ра́дуйся, я́ко се́рдце на́ше к покая́нію направля́єши;","ра́дуйся, я́ко бу́ри іскуше́ній отража́єши.","Ра́дуйся, я́ко болі́зні душе́вния і тіле́сния ісціля́єши;","ра́дуйся, я́ко житіє́ на́ше до́брі устроя́єши.","Ра́дуйся, я́ко припа́дающих к пречестні́й іко́ні Твоє́й от вся́ких бід защища́єши;","ра́дуйся, я́ко от собла́знов ми́ра сего́ нас огражда́єши.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прийми́ от нас, Всепі́тая Ді́во, на ра́дость дарова́вшая нам Свою́ святу́ю іко́ну, да вку́пі со А́нгели і земноро́дними просла́вим Бо́га, зову́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том боже́ственним украси́ся земля́ Га́личськая в явле́нії чу́дния іко́ни Твоєя́ Ови́новськия, та́ко просвіти́ і нас, ни́ні взива́ющих Тебі́ си́це:","Ра́дуйся, ми́ра всего́ помо́щнице;","ра́дуйся, милосе́рдія істо́чниче.","Ра́дуйся, от А́нгел воспіва́ємая на Небесі́;","ра́дуйся, от ві́рних восхваля́ємая на землі́.","Ра́дуйся, похвало́ ми́ра і утвержде́ніє;","ра́дуйся, всім скорб'я́щим прибі́жище і заступле́ніє.","Ра́дуйся, лю́дем страни́ Га́личськия благода́тноє вспоможе́ніє;","ра́дуйся, злих серде́ць ум'ягче́ніє.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Твою́, Пречи́стая Ді́во, да́руй всім синово́м і дще́рем страни́ на́шея, да воспоє́м усе́рдно Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоєя́ ми́лости, явле́нная свято́му Га́личському кня́зю Дими́трію Кра́сному, чти́вшему умиле́нно іко́ну Ови́новськую, мо́лим Тя, Пресвята́я Ді́во: не лиши́ і нас ми́лости Твоєя́, вопію́щих та́ко:","Ра́дуйся, Це́ркве Небе́сния красото́;","ра́дуйся, Це́ркве земни́я похвало́.","Ра́дуйся, А́нгельськими со́нми воспіва́ємая;","ра́дуйся, кня́жеським ро́дом прославля́ємая.","Ра́дуйся, в напа́стіх всемо́щноє упова́ніє;","ра́дуйся, іко́ну Твою́ чу́дно із'є́мшая із пла́мене.","Ра́дуйся, і нас от запале́нія страсте́й сохраня́ющая;","ра́дуйся, ро́су благода́ті низпосила́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, прийми́ от нас сіє́ благода́рственноє пі́ніє, я́ко лик Твой святи́й на ра́дость даде́ся всім, вопію́щим к Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел со́нми на Небесі́ і христия́н мно́жества на землі́ ра́дуються о Тебі́, Ма́ти на́ша, і ра́достно прино́сять Ті цілова́ніє сицево́є: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю. Ми же, зна́меніє ви́дяще благоволе́нія Твоєго́ к землі́ сей, со умиле́нієм взива́єм:","Ра́дуйся, лю́дем гра́да Га́лича небе́сноє утіше́ніє;","ра́дуйся, і́ночествующим оби́телі Нико́льськия покро́в і защище́ніє.","Ра́дуйся, преподо́бнаго Паї́сія укріпле́ніє;","ра́дуйся, всего́ собо́ра святи́х Га́личських увеселе́ніє.","Ра́дуйся, іко́ною Твоє́ю в ско́рбіх всім помога́ющая;","ра́дуйся, во дні і в нощі́ оби́тель і град покрива́ющая.","Ра́дуйся, от бід страну́ на́шу огражда́ющая;","ра́дуйся, печа́ль на́шу в ра́дость претворя́ющая.","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нная Ді́во Марі́є, Цари́це на́ша Богоро́дице, осіни́вшая страну́ Га́личськую ангелохва́льним явле́нієм іко́ни Своєя́, благода́рственная возсила́єм Ті раби́ Твої́, Влади́чице:","Ра́дуйся, Ма́ти Бо́жия, зе́млю Га́личськую о́бразом Свої́м охраня́ющая."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во Марі́є, Ма́ти Бо́жия, прийми́ многоболі́зненноє воздиха́ніє на́ше, і да́руй коєму́ждо проше́нію ісполне́ніє, скорб'я́щим ско́рби облегчи́, оби́димих от оби́д ізба́ви, немощни́м і разсла́бленним і боля́щим здра́віє да́руй, і сохрани́ нас во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Благодатне Небо»","e":"Akathist to the Theotokos before her icon “Blessed Heaven”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, Благода́тним Не́бом на́ми імену́ємой, ті́лу на́шему і душа́м спасе́ніє подаю́щей, благода́рственноє прино́сим пі́ніє, Богороди́тельнице. Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, от вся́ких нас бід і гріхо́в свободи́, да зове́м Ті:","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Ікос 1","ps":["А́нгели і пра́ведних душі́ удиви́шася, єгда́ предста́ла єси́ пред Сино́м Твої́м і Бо́гом і мно́гим моле́нієм ходатайствовала о лю́діх, во грісі́х пребива́ющих. Ми же, очи́ма ві́ри толи́коє Твоє́ благоутро́біє зря́ще, со умиле́нієм взива́єм Тебі́ си́це:","Ра́дуйся, моли́тви всіх христия́н приє́млющая;","ра́дуйся, і са́мих отча́янних грі́шников моле́нія не отверга́ющая.","Ра́дуйся, к Си́ну Твоєму́ о них предста́тельствующая;","ра́дуйся, неча́янную ра́дость спасе́нія їм подаю́щая.","Ра́дуйся, предста́тельством Твої́м весь мир спаса́ющая;","ра́дуйся, вся на́ша печа́лі утоля́ющая.","Ра́дуйся, житіє́ на́ше до́брі устроя́ющая;","ра́дуйся, ізбавле́ніє от гріхо́во всім челові́ком прине́сшая.","Ра́дуйся, Ра́дость всему́ ми́ру роди́вшая;","ра́дуйся, є́же ка́ко ні єди́наго же научи́вшая.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 2","ps":["Ви́дящи Пречи́стая лю́ди грі́шния, с ві́рою і упова́нієм пред честно́ю Єя́ іко́ною до́лу повергающихся і сле́зно моля́щихся о грісі́х свої́х, внят моле́нію їх, да всі, зря́ще Ма́тернєє Єя́ милосе́рдіє, на небесі́ і на землі́ вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський воі́стину превосхо́дить любо́в Твоя́ к ро́ду христия́нському, о не́мже мо́лишися Си́ну Твоєму́ і Бо́гу, ми же, зря́ще Тя, неотсту́пную Предста́тельницю за нас грі́шних, со слеза́ми вопіє́м Ті:","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго, от Бо́га нам дарова́нная;","ра́дуйся, Путеводи́тельнице на́ша, к небе́сному оте́честву нас возводя́щая.","Ра́дуйся, ві́рних огражде́ніє і прибі́жище;","ра́дуйся, по́моще призива́ющих і́м'я Твоє́ свято́є.","Ра́дуйся, презрі́нних і отве́рженних от ро́ва поги́белі ісхища́ющая;","ра́дуйся, тіх на путь пра́вий обраща́ющая.","Ра́дуйся, непреста́нноє уни́ніє і мрак душе́вний отгоня́ющая;","ра́дуйся, оста́вленних врачми на Свої́ всемощнеї ру́ці приє́млющая.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 3","ps":["Си́ла благода́ті преізобилова та́мо, іді́же умно́жися гріх, да ра́дуються на небесі́ всі а́нгели о грі́шниціх ка́ющихся, пою́ще пред престо́лом Бо́жиїм: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи к ро́ду христия́нському Ма́тернєє милосе́рдіє, всім, с ві́рою і упова́нієм прибегающим к Тебі́, подає́ши ру́ку по́мощі, Влади́чице, да всі єди́ним се́рдцем і єди́німи усти́ славосло́віє Тебі́ прино́сять сицево́є:","Ра́дуйся, я́ко Тобо́ю к нам нисхо́дить Бо́жиє благоволе́ніє;","ра́дуйся, я́ко во всіх біда́х і обстоя́ніїх на́ших прино́сиши Си́ну Твоєму́ усе́рдния о нас моли́тви.","Ра́дуйся, я́ко на́ша моли́тви прия́тними Бо́гу соді́ловаєши;","ра́дуйся, я́ко от ви́димих враго́в нас ізбавля́єши.","Ра́дуйся, я́ко се́рдця злих челові́к ум'ягчаєши;","ра́дуйся, я́ко от клевети́, досажде́нія і укоре́нія нас ізимаєши.","Ра́дуйся, я́ко Тобо́ю вся блага́я жела́нія на́ша ісполня́ються;","ра́дуйся, я́ко мно́го мо́жеть моли́тва Твоя́ пред Сино́м Твої́м і Бо́гом.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 4","ps":["Пред честно́ю іко́ною Твоє́ю, Цари́це Небе́сная, склоняєм колі́на душ і тіле́с на́ших і со умиле́нієм дерзнове́нно мо́лимся Ті: спаси́ нас, о Ма́ти милосе́рдія, да не поги́бнем до конця́ во грісі́х на́ших; Ти бо єси́ всім грі́шником єди́на наде́жда і прибі́жище: преклони́ся у́бо на ми́лость, блага́я Ма́ти, і умоли́ о нас Си́на Твоєго́ і Творця́ на́шего, да непреста́нно зове́м Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше небожителіє, я́ко моли́твами Твої́ми пред Сино́м Твої́м проще́ніє гріхо́в і спасе́ніє на землі́ су́щим грі́шником да́руються, прославля́ють Тя, благосердную Цари́цю небесе́ і землі́. І ми, грі́шнії, уві́дівше таково́є Твоє́ заступле́ніє о нас, грі́шних, недоуміва́єм, ка́ко благохвали́ти Тя возмо́жем по достоя́нію, і от глубини́ се́рдця на́шего умиле́нно воспіва́єм Ті си́це:","Ра́дуйся, Спору́чнице спасе́нія грі́шних;","ра́дуйся, Взиска́ніє поги́бших.","Ра́дуйся, неча́янная грі́шних Ра́досте;","ра́дуйся, па́дших воста́ніє.","Ра́дуйся, Предста́тельнице к Бо́гу, мир от бід спаса́ющая;","ра́дуйся, я́ко гла́са моли́тв Твої́х бі́си трепе́щуть.","Ра́дуйся, я́ко а́нгели сему́ ра́дуються;","ра́дуйся, я́ко і нас, земноро́дних, си́ла моли́тв Твої́х весе́лія ісполня́єть.","Ра́дуйся, я́ко ті́ми от ти́ни гріхо́в нас ізимаєши;","ра́дуйся, я́ко пла́мень страсте́й на́ших угаша́єши.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ чудотво́рную іко́ну Ма́тере Твоєя́ показа́л єси́ нам, Го́споди, і́бо, взира́юще на о́браз Єя́ тіле́снима очи́ма, умо́м і се́рдцем к Первообра́зній возвиша́ємся, і Є́ю к Тебі́ востекаєм, пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше а́нгели, храни́теліє христия́н, я́ко Бо́жия Ма́тер споспішеству́єть їм в наставле́нії тіх, заступле́нії і спасе́нії, потща́шася си́це возопи́ти Честні́йшей Херуви́м і Славнейшей без сравне́нія Серафи́м:","Ра́дуйся, с Сино́м Твої́м і Бо́гом ві́чно ца́рствующая;","ра́дуйся, Єму́ всегда́ о ро́ді христия́нськом моле́нія принося́щая.","Ра́дуйся, в христия́нстій ві́рі і благоче́стії Наста́внице;","ра́дуйся, уповающим на Тя непости́дний коне́ць жи́зні да́рующая.","Ра́дуйся, Ма́терним Твої́м предста́тельством от ві́чнаго муче́нія нас ізбавля́ющая;","ра́дуйся, хода́тайством к Си́ну Твоєму́ жи́зні ві́чния сподобля́ющая.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 6","ps":["Ди́вная діла́ милосе́рдія Твоєго́, лю́дем явле́нная, предаде́ пи́смені святи́тель Дими́трій Росто́вський в науче́ніє і утіше́ніє всім ві́рним, да і ті́ї, во грісі́х, біда́х, ско́рбіх і озлобле́нії су́ще, на всяк день пред честни́м Твої́м о́бразом, Благода́тноє Не́бо іменуємим, колі́на преклоня́ють і, ізби́вше бід, печа́лей і напа́стей, вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам, я́ко пресві́тлая заря́, чудотво́рная іко́на Твоя́, Богома́ти, прогоня́ющи тьму бід і скорбе́й от всіх с любо́вію вопію́щих Ті си́це:","Ра́дуйся, Ціли́тельнице на́ша в болі́зніх тіле́сних;","ра́дуйся, блага́я Уті́шительнице в печа́ліх на́ших душе́вних.","Ра́дуйся, скорб на́шу в ра́дость претворя́ющая;","ра́дуйся, ненаді́ющихся несумні́нною наде́ждою возвеселяющая.","Ра́дуйся, а́лчущих Пита́тельнице;","ра́дуйся, наги́х одія́ніє.","Ра́дуйся, вдов Уті́шительнице;","ра́дуйся, безма́терніх сиро́т незри́мая Воспита́тельнице.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 7","ps":["Хотя́ Законода́вець правосу́дний Госпо́дь Сам би́ти зако́на ісполни́тель і яви́ти милосе́рдія Своєго́ бе́здну, преклони́ся на усе́рдноє моле́ніє Твоє́, Преблагослове́нная Ма́ти Ді́во, о лю́діх во грісі́х пребива́ющих і ми́лостей Бо́жиїх ча́ющих, глаго́ля: Зако́н повеліва́єть, да син чтить ма́тер. Аз Син Твой, Ти же Ма́ти Моя́, Аз Тя до́лжен чти́ти, послу́шая Твоєго́ моле́нія, бу́ди у́бо, я́ко же хо́щеши. О ни́хже мо́лишися — прощаються їм гріси́ Тебе́ ра́ди. Ми же, ви́дяще такову́ю си́лу моли́тви Хода́тайці на́шея о проще́нії согріше́ній на́ших, просла́вим милосе́рдіє і неізрече́нноє благоутро́біє Єя́, зову́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє ди́вноє і сла́вноє зна́меніє всім ві́рним яви́ся, я́ко не то́кмо Ма́тері Твоєя́, но і пречи́стому Єя́ ли́ку, на дські ізображе́нному, си́лу чудотворе́нія дарова́л єси́, Го́споди; сему́ та́їнству див'я́щеся, во умиле́нії се́рдця вопіє́м к Ней такова́я:","Ра́дуйся, прему́дрости і бла́гости Бо́жия открове́ніє;","ра́дуйся, ві́ри утвержде́ніє.","Ра́дуйся, благода́ті явле́ніє;","ра́дуйся, душеполе́зних зна́ній дарова́ніє.","Ра́дуйся, сло́во прему́дрости просящим да́рующая;","ра́дуйся, несми́сленних разу́мними соделовающая.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 8","ps":["Ви́дяще сла́вная діла́ і многоразли́чную прему́дрость Бо́жию в ми́рі і жи́зні на́шей, предста́тельством Твої́м пред Бо́гом над на́ми соверша́ющаяся, о Не́бо благода́тноє, Пречи́стая Влади́чице, устрані́мся земни́я суєти́ і ізли́шніх жите́йських попече́ній, і ум і се́рдце на́ше на небеса́ возведе́м, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся во ви́шніх пребива́єши, і ни́жніх ніка́коже отступила єси́, премилосе́рдная Цари́це небесе́ і землі́. А́ще бо по успе́нії Твоє́м і взошла єси́ на небеса́ с пречи́стою Твоє́ю пло́тію, оба́че і грі́шния землі́ не оста́вила єси́, явля́ющися прича́стниця промишле́нія Си́на Твоєго́ о ро́ді христия́нськом, сего́ ра́ди Тя по до́лгу ублажа́єм:","Ра́дуйся, сія́нієм пречи́стия душі́ Твоєя́ всю зе́млю просвіти́вшая;","ра́дуйся, чистото́ю тілесе́ Твоєго́ вся небеса́ возвесели́вшая.","Ра́дуйся, о всем ми́рі усе́рдная Предста́тельнице;","ра́дуйся, всіх нас при Кресті́ Си́на Твоєго́ усинови́вшая.","Ра́дуйся, всегда́ Ма́тернюю любо́в к нам явля́ющая;","ра́дуйся, в ско́рбіх утіша́ющая.","Ра́дуйся, всіх даро́в духо́вних і тіле́сних незави́стная пода́тельнице;","ра́дуйся, благ вре́менних і ві́чних Хода́тайце.","Ра́дуйся, две́рі ца́рствія Христо́ва ві́рним отверза́ющая;","ра́дуйся, і на землі́ чи́стаго весе́лія се́рдця на́ша ісполня́ющая.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє удиви́ся ді́лу Твоєго́ милосе́рдія, Го́споди, я́ко толи́ко тве́рдую і те́плую Засту́пницю і Помо́щницю ро́ду христия́нському дарова́л єси́, нам неви́димо спребивающу, сли́шащу же Тебе́ пою́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не возмо́жеть по достоя́нію благохвали́ти Тя, Пресвята́я Богоро́дице, і воспі́ти неісче́тная чудеса́ Твоя́, от іко́ни Твоєя́ явля́ємая, і́миже правосла́вния лю́ди от бід, напа́стей і вся́каго зла сохраня́єши. Ми же, до́брі ві́дуще о мно́гих чудотво́рних явле́ніїх Твоєго́ честна́го ли́ка би́вших і поклоне́нієм єму́ потре́бная ко вре́менній і ві́чній жи́зні приє́млюще, с весе́лієм Богоро́дице взива́єм:","Ра́дуйся, я́ко от свяще́ннаго ли́ка Твоєго́ чудеса́ ді́ються;","ра́дуйся, я́ко утаї́ся прему́дрость і благода́ть сія́ от му́дрих і разу́мних ві́ка сего́.","Ра́дуйся, я́ко откри́ся та младе́нцем во ві́рі;","ра́дуйся, я́ко прославля́ющих Тя прославля́єши.","Ра́дуйся, я́ко отверга́ющих Тя пред всі́ми посрамля́єши;","ра́дуйся, я́ко от вся́каго зла прибіга́ющих к Тебі́ ізбавля́єши.","Ра́дуйся, я́ко вся болі́зні челові́чеськія душе́вния і тіле́сния ми́лостивно врачу́єши;","ра́дуйся, я́ко пра́ведний гнів Бо́жий на нас Твої́м моле́нієм ско́ро утоля́єши.","Ра́дуйся, я́ко Ти єси́ ти́хоє приста́нище всім с ві́рою к Тебі́ притекающим;","ра́дуйся, кораблю́ хотя́щих спасти́ся.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ще душі́ своя́ от ві́чния сме́рти, ми, недосто́йная ча́да Твоя́, прекло́ньше колі́на своя́ пред пречи́стим Твої́м о́бразом, мо́лим Тя, Небе́сная Цари́це і милосе́рдная Ма́ти спасе́нія на́шего: сотвори́ нас прича́стники ві́чнаго блаже́нства в Небе́сном Ца́рствії Си́на Твоєго́, пою́щих Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і приста́нище небу́рноє Ти єси́, Богоро́дице Ді́во, всім к Тебі́ притекающим, ті́мже і нас огради́ і покри́й от всіх враг ви́димих і неви́димих, да с ві́рою і умиле́нієм поклоняющеся пречестні́й і цільбоно́сній іко́ні Твоє́й, ра́достно вопіє́м Ті:","Ра́дуйся, сохраня́ти і спаса́ти всіх призива́ющих Тя обіща́вшая;","ра́дуйся, к Си́ну Твоєму́ і Бо́гу моли́тви ві́рних принося́щая.","Ра́дуйся, і Сама́ непреста́нно у престо́ла Єго́ моля́щаяся о нас;","ра́дуйся, благода́ть Твої́м іко́нам дарова́вшая.","Ра́дуйся, всю вселе́нную луча́ми тіх озаря́ющая;","ра́дуйся, ро́да христия́нськаго похвало́ і непости́дноє упова́ніє.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє принося́ще Ті, недостоїнії, про́сим Тебе́, Ді́во Богоро́дице: не пре́зри гла́са рабо́в Твої́х, к Тебі́ бо в напа́стіх і ско́рбіх прибіга́єм і пред Тобо́ю в біда́х на́ших сле́зи пролива́єм, пою́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная свіща́ су́щим во тьмі гріха́ і юдо́лі пла́ча яви́ся преди́вная іко́на Твоя́, Пречи́стая Влади́чице: всім бо притекающим к ней струї́ ісціле́ній ізлива́єть і чуде́с заря́ми се́рдця ві́рних весели́ть, подвиза́ющи взива́ти си́це:","Ра́дуйся, Боже́ственний Світ неізрече́нно роди́вшая;","ра́дуйся, тьму сме́ртную рождество́м Твої́м просвіти́вшая.","Ра́дуйся, страни́ на́шея неуси́пная Покрови́тельнице;","ра́дуйся, ві́рних па́стирей Це́ркве ободря́ющая і вразумляющая.","Ра́дуйся, люде́й правосла́вних Храни́тельнице;","ра́дуйся, богобоя́зненних і́ноков і і́нокинь при́сноє Утіше́ніє.","Ра́дуйся, ка́ющихся пред Бо́гом грі́шников непости́дная Засту́пнице;","ра́дуйся, ра́дости небе́сния всім нам Пода́тельнице.","Ра́дуйся, всіх христия́н те́плая Хода́тайце;","ра́дуйся, о лю́діх Твої́х при́сная Моли́твеннице.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 12","ps":["Благода́ть боже́ственную іспроси́ нам у Си́на Твоєго́ і Бо́га, простри́ нам ру́ку по́мощі, отжени́ от нас вся́каго врага́ і супоста́та, умири́ на́шу жизнь, да не поги́бнем лю́ті без покая́нія, но прийми́ нас во ві́чния кро́ви, Богороди́тельнице, да ра́дующеся поє́м Бо́гу, Тобо́ю нас спаса́ющему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вная Твоя́ чудеса́, уми́льно припа́даєм пред пречи́стим о́бразом Твої́м і, благогові́йно лобиза́юще єго́, немо́лчними пі́сньми воспіва́єм Тя, преди́вная Цари́це небесе́ і землі́, і про́сим Тя, Влади́чице, усли́ши на́ше моле́ніє в час сей і благода́ть Си́на Твоєго́ нам низпосли́, с любо́вію вопію́щим Тебі́:","Ра́дуйся, ми́лостей Си́на Твоєго́ і Бо́га нас сподобля́ющая;","ра́дуйся, десну́ю часть моли́твами Твої́ми нам грі́шним уготовля́ющая.","Ра́дуйся, ізнемога́ющих от уни́нія і печа́лі ско́рая Уті́шительнице;","ра́дуйся, грі́шником кающимся спасе́ніє подаю́щая.","Ра́дуйся, і нераска́янних грі́шников к покая́нію обраща́ющая;","ра́дуйся, всіх По́моще, ско́рбним вдови́цям і си́рим помога́ющая.","Ра́дуйся, а́лчущих і жа́ждущих пра́вди к Бо́гу приводя́щая;","ра́дуйся, ро́да христия́нськаго Засту́пнице усе́рдная.","Ра́дуйся, Це́ркве Правосла́вния неруши́мая Стіно́ і Не́бо благода́тноє;","ра́дуйся, страни́ на́шея Покро́ве і Защище́ніє.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 13","ps":["О всепі́тая Ма́ти, невмісти́маго Бо́га во чре́ві вмісти́вшая і Ра́дость всему́ ми́ру роди́вшая! Ни́нішнєє приє́мши пі́ніє, вся на́ша печа́лі на ра́дость преложи́, от вся́кия ізба́ви напа́сти всіх і бу́дущия ізми́ муки́ о Тебі́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели і пра́ведних душі́ удиви́шася, єгда́ предста́ла єси́ пред Сино́м Твої́м і Бо́гом і мно́гим моле́нієм ходатайствовала о лю́діх, во грісі́х пребива́ющих. Ми же, очи́ма ві́ри толи́коє Твоє́ благоутро́біє зря́ще, со умиле́нієм взива́єм Тебі́ си́це:","Ра́дуйся, моли́тви всіх христия́н приє́млющая;","ра́дуйся, і са́мих отча́янних грі́шников моле́нія не отверга́ющая.","Ра́дуйся, к Си́ну Твоєму́ о них предста́тельствующая;","ра́дуйся, неча́янную ра́дость спасе́нія їм подаю́щая.","Ра́дуйся, предста́тельством Твої́м весь мир спаса́ющая;","ра́дуйся, вся на́ша печа́лі утоля́ющая.","Ра́дуйся, житіє́ на́ше до́брі устроя́ющая;","ра́дуйся, ізбавле́ніє от гріхо́во всім челові́ком прине́сшая.","Ра́дуйся, Ра́дость всему́ ми́ру роди́вшая;","ра́дуйся, є́же ка́ко ні єди́наго же научи́вшая.","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, Благода́тним Не́бом на́ми імену́ємой, ті́лу на́шему і душа́м спасе́ніє подаю́щей, благода́рственноє прино́сим пі́ніє, Богороди́тельнице. Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, от вся́ких нас бід і гріхо́в свободи́, да зове́м Ті:","Ра́дуйся, Благода́тноє Не́бо, ра́дость і спасе́ніє нам да́рующая."]},{"h":"Молитва","ps":["Что Тя нарече́м, о Благода́тная Богома́ти Богоотрокови́це, Пренепоро́чная Марі́є? Ки́їми піснопі́нії возвели́чим Тя, возвеличенную Не́бом і земле́ю, А́нгелами і челові́ки? Яви́ся бо на Тебі́ неслишанноє от ві́ка на землі́ і несві́домоє А́нгелами на Небесі́ та́їнство, па́че ума́ і сло́ва, вочелові́ченія Бо́га Сло́ва, рожде́ннаго сискони от Безнача́льнаго Отця́ без ма́тері і воплоще́ннаго в Твоє́й утро́бі і с нетлі́нною печа́тію ді́вства Твоєго́ роди́вшагося. О, чу́до всіх дре́вніх і но́вих чуде́с! Непрело́жноє сло́во Самаго́ Бо́га о побідоно́снім сі́мені жени́ іспо́лнися і соверши́ся в Безмужней Ді́ві. О, неізмі́римая глубина́ прему́дрості і вели́чія Бо́жия! Ки́їми імени́ нарече́м Тя, о Неві́ста Неневі́стная? Заре́ю ли нарече́м Тя восходя́щаго на не́бі со́лнця? Но Ти – са́моє Не́бо, із Тебе́ бо возсія́ Со́лнце Пра́вди – Христо́с Бог наш, Спаси́тель грі́шних. Імену́єм ли Тя врата́ми, вводящими в потерянний прародителями рай, обиловавший всі́ми благами? Но Ти Сама́ єси́ благода́тний рай, проізрасти́вшая Цвіт нетлі́нія, врачу́ющий і отгоня́ющий смерденіє гріха́ і злово́ніє прародительськаго тлі́нія. Нарече́м ли Тя юною Непоро́чною Ді́вою, не познавшей бра́ка? Но Ти і до ста́рости пребила́ Неіскусобра́чною і ді́вственною до рожде́нія, і в рожде́нії, і по рожде́нії Си́на пребила́ єси́. Найменуєм ли Тя Чи́стою і Свято́ю Марі́єю, превозшедшею Своє́ю чистото́ю всіх ма́терей і праматерей? Но Ти не то́кмо родила́ Того́ Младе́нця Христа́, но і носи́ла Єго́ при Свої́х пе́рсіх і пита́ла Твої́м матеродевственним млеко́м, Того́, І́же пита́єть вся́коє созда́ніє, Єму́же со стра́хом і тре́петом предстоя́ть Небесниє си́ли і Єго́ же хва́лить вся́коє диха́ніє і твар. О, воі́стину Ти ди́вная єси́ в жена́х, чу́дная в ді́вах, неподражаємая в ма́теріх! К Тебі́ пред Твої́м Боже́ственним лико́м припа́даєм і пред Твої́ми святи́ми стопа́ми поверга́єм і слагаєм все на́ші ми́слі, жела́нія, намі́ренія і чу́вства. Освяти́ їх Твої́м Богома́тернім призрі́нієм і вознеси́ їх, я́ко же́ртву на́шего смире́ннаго се́рдця, я́ко малоценную ле́пту на́шей духо́вной нищети́, к Престо́лу Си́на Твоєго́, Спаси́теля на́шего, да і́миже вість судьба́ми упра́вить наш путь ко спасе́нію і наслі́дію Ца́рствія Єго́, не іму́щаго конця́ во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 6","ps":["Что Тя нарече́м, о, Благода́тная? / Не́бо? – я́ко возсія́ла єси́ Со́лнце Пра́вди; / рай? – я́ко прозябла́ єси́ Цвіт нетлі́нія; / Ді́ву? – я́ко пребила́ єси́ нетлі́нна; / Чи́стую Ма́тер? – я́ко імі́ла єси́ на святи́х Твої́х об'я́тіях Си́на, всіх Бо́га. // Того́ моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице, / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]}];
export default D;
